local Icons = {
	at = ICON_AT,
	cell = ICON_CELL,
	alias = {
		activity = "activity", bell = "bell", box = "cube", boxes = "stack-2", ["chevron-down"] = "chevron-down",
		clock = "clock", crosshair = "crosshair", ellipsis = "dots", eye = "eye", flame = "flame", folder = "folder",
		footprints = "shoe", gauge = "gauge", globe = "world", hand = "mood-smile", info = "info-circle",
		keyboard = "keyboard", layers = "stack-2", link = "link", list = "list", map = "map", ["map-pin"] = "map-pin",
		monitor = "device-desktop", move = "arrows-move", package = "package", palette = "palette",
		["person-standing"] = "walk", person = "user", power = "power", rocket = "rocket", save = "device-floppy",
		["scan-eye"] = "scan", search = "search", settings = "settings", ["shield-check"] = "shield-check",
		shirt = "shirt", skull = "skull", ["sliders-horizontal"] = "adjustments-horizontal", sparkles = "sparkles",
		star = "star", sword = "sword", swords = "swords", target = "target", user = "user", users = "users",
