		plus = "plus", ["refresh-cw"] = "refresh", check = "check", ["volume-2"] = "volume", ["trash-2"] = "trash",
		copy = "copy", clipboard = "clipboard", ["circle-dot"] = "circle-dot", crown = "crown",
