-- ------------------------------------------------------------- text field --
-- A field whose letters fade in as they are typed, with a caret that glides
-- to wherever the cursor goes. The real TextBox underneath takes the keys and
-- the clicks; its own text and caret are hidden in the field's colour.
function K.input(parent, cfg)
	local z = cfg.ZIndex or 5
	local size = cfg.TextSize or 13
	local holder = new("Frame", {
		Name = "Input",
		Position = cfg.Position or UDim2.new(),
		Size = cfg.Size or UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		ZIndex = z,
	}, parent)
	local box = new("TextBox", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		ClearTextOnFocus = false,
		FontFace = K.face.medium,
		Text = "",
		TextSize = size,
		TextColor3 = cfg.Background or C.field,
		TextTransparency = 1,
		TextXAlignment = Enum.TextXAlignment.Left,
		PlaceholderText = "",
		ZIndex = z + 3,
	}, holder)
	local mark = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(0, size + 6),
		BackgroundColor3 = C.chip,
		BorderSizePixel = 0,
		Visible = false,
		ZIndex = z,
	}, holder)
	corner(mark, 3)
	local shown = K.text(holder, {
		Size = UDim2.new(0, 4000, 1, 0),
		RichText = true,
		Text = "",
		TextSize = size,
		TextColor3 = C.text,
		TextTruncate = Enum.TextTruncate.None,
		ZIndex = z + 1,
	})
	local hint = K.text(holder, {
		Size = UDim2.fromScale(1, 1),
		Text = cfg.Placeholder or "",
		TextSize = size,
		TextColor3 = C.faint,
		ZIndex = z + 1,
	})
	local caret = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(2, size + 3),
		BackgroundColor3 = C.text,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		ZIndex = z + 2,
	}, holder)
	corner(caret, 1)
	local ruler = K.text(holder, {
		Size = UDim2.new(0, 4000, 1, 0),
		Text = "",
		TextSize = size,
		TextTransparency = 1,
		TextTruncate = Enum.TextTruncate.None,
		ZIndex = z,
	})
	local function scale() return math.max(scaler.Scale * K.pop.Scale, 0.01) end
	-- a trailing bar keeps trailing spaces counted
	local function px(text)
		ruler.Text = text .. "|"
		local w = ruler.TextBounds.X
		ruler.Text = "|"
		return (w - ruler.TextBounds.X) / scale()
	end

	local FADE = 0.2
	local chars, born = {}, {}
	local textDirty, fadingUntil, wasFading = true, 0, false
	local changed = 0
	local function split(text)
		local out = {}
		for c in string.gmatch(text, utf8.charpattern) do out[#out + 1] = c end
		return out
	end
	local ESC = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;", ['"'] = "&quot;", ["'"] = "&apos;" }
	box:GetPropertyChangedSignal("Text"):Connect(function()
		local now = os.clock()
		local nextChars = split(box.Text)
		local p = 0
		while p < #chars and p < #nextChars and chars[p + 1] == nextChars[p + 1] do p += 1 end
		local s = 0
		while s < #chars - p and s < #nextChars - p and chars[#chars - s] == nextChars[#nextChars - s] do s += 1 end
		local nextBorn = {}
		for i = 1, p do nextBorn[i] = born[i] end
		for i = p + 1, #nextChars - s do nextBorn[i] = now end
		for i = 1, s do nextBorn[#nextChars - s + i] = born[#chars - s + i] end
		chars, born, changed = nextChars, nextBorn, now
		textDirty, fadingUntil = true, now + FADE
	end)

	local caretX, offset = 0, 0
	local lastText, lastCursor, target = nil, nil, 0
	local lastShown
	connectUI(box:GetPropertyChangedSignal("TextSize"), function()
		lastText = nil
		caret.Size = UDim2.fromOffset(2, box.TextSize + 3)
		mark.Size = UDim2.fromOffset(mark.Size.X.Offset, box.TextSize + 6)
	end, holder)
	connectUI(box:GetPropertyChangedSignal("FontFace"), function() lastText = nil end, holder)
	connectUI(K.RS.RenderStepped, function(dt)
		LPH_ATTRIBUTES(VM(NONE))
		if not (root.Visible and parent.Visible and holder.Visible) or holder:IsDescendantOf(K.attic) then return end
		local now = os.clock()
		if textDirty or now < fadingUntil or wasFading then
			local parts = table.create(#chars)
			for i, c in ipairs(chars) do
				local a = (now - born[i]) / FADE
				local e = ESC[c] or c
				if a < 1 then
					parts[i] = string.format('<font transparency="%.2f">%s</font>', (1 - a) ^ 3, e)
				else
					parts[i] = e
				end
			end
			local text = table.concat(parts)
			if text ~= lastShown then
				shown.Text = text
				lastShown = text
			end
			textDirty, wasFading = false, now < fadingUntil
		end
		if hint.Visible ~= (#chars == 0) then hint.Visible = #chars == 0 end
		local focused = box:IsFocused()
		local cursor = box.CursorPosition
		if box.Text ~= lastText or cursor ~= lastCursor then
			if cursor ~= lastCursor then changed = math.max(changed, now) end
			lastText, lastCursor = box.Text, cursor
			target = cursor > 0 and px(string.sub(box.Text, 1, cursor - 1)) or px(box.Text)
		end
		caretX += (target - caretX) * (1 - math.exp(-dt * 32))
		if math.abs(target - caretX) < 0.01 then caretX = target end
		local room = holder.AbsoluteSize.X / scale() - 6
		local want = math.max(0, target - room)
		offset += (want - offset) * (1 - math.exp(-dt * 24))
		if math.abs(want - offset) < 0.01 then offset = want end
		local shownPos = UDim2.fromOffset(-offset, 0)
		if shown.Position ~= shownPos then shown.Position = shownPos end
		local caretPos = UDim2.new(0, math.floor(caretX - offset + 0.5), 0.5, 0)
		if caret.Position ~= caretPos then caret.Position = caretPos end
		-- solid while typing, then a slow soft pulse
		local idle = now - changed
		local pulse = idle < 0.6 and 0 or (0.5 - 0.5 * math.cos((idle - 0.6) * math.pi * 2 / 1.1))
		local alpha = focused and pulse or 1
		if caret.BackgroundTransparency ~= alpha then caret.BackgroundTransparency = alpha end
		local sel = box.SelectionStart
		if focused and sel and sel > 0 and cursor > 0 and sel ~= cursor then
			local a, b = math.min(sel, cursor), math.max(sel, cursor)
			local x1, x2 = px(string.sub(box.Text, 1, a - 1)), px(string.sub(box.Text, 1, b - 1))
			mark.Visible = true
			mark.Position = UDim2.new(0, x1 - offset, 0.5, 0)
			mark.Size = UDim2.fromOffset(x2 - x1, box.TextSize + 6)
		else
			if mark.Visible then mark.Visible = false end
		end
	end, holder)
	return { holder = holder, box = box, hint = hint }
end

