-- --------------------------------------------------------------- scrolling --
-- On a PC pages glide: the wheel moves a target and every frame closes part
-- of the gap. The smallest list under the pointer that can still scroll gets
-- the notch and keeps it, no handing over to the page behind. Phones scroll
-- natively.
K.scrollers = setmetatable({}, { __mode = "k" })
K.scrollMotion = setmetatable({}, { __mode = "k" })
K.wheelBlockers = setmetatable({}, { __mode = "k" })
K.frontPanels = setmetatable({}, { __mode = "k" })
function K.frontAt(pointer)
	for panel in pairs(K.frontPanels) do
		if K.inside(panel, pointer) then
			local parent, visible = panel, true
			while parent do
				if parent:IsA("GuiObject") and not parent.Visible then visible = false; break end
				if parent:IsA("ScreenGui") then visible = parent.Enabled; break end
				parent = parent.Parent
			end
			if visible then return true end
		end
	end
	return false
end
function K.scroller(sf)
	sf.ScrollBarImageColor3 = C.chip
	if MOBILE then
		sf.ScrollingEnabled = true
		sf.ElasticBehavior = Enum.ElasticBehavior.WhenScrollable
		return sf
	end
	sf.ScrollingEnabled = false
	sf.ScrollBarImageTransparency = 1
	K.scrollers[sf] = { target = sf.CanvasPosition.Y, shown = 0 }
	return sf
end

do
	-- CanvasPosition is in the window's own units; Absolute* sizes are screen
	-- pixels, scaled by every UIScale above (menu size, the open/close pop).
	-- Mixed, a smaller menu never reached the bottom and a bigger one aimed
	-- past it and never settled, so the wheel went dead for a moment.
	local function unit(sf)
		local s, o = 1, sf
		while o and o ~= gui do
			local u = o:FindFirstChildOfClass("UIScale")
			if u then s *= u.Scale end
			o = o.Parent
		end
		return math.max(s, 0.01)
	end
	local function room(sf)
		return math.max(sf.AbsoluteCanvasSize.Y - sf.AbsoluteWindowSize.Y, 0) / unit(sf)
	end
	local function onScreen(sf, pointer)
		if not sf.Parent or sf:IsDescendantOf(K.attic) then return false end
		local o = sf
		while o and o ~= gui do
			if o:IsA("GuiObject") and not o.Visible then return false end
			if pointer and o:IsA("GuiObject") and o.ClipsDescendants and not K.inside(o, pointer) then return false end
			o = o.Parent
		end
		return o == gui
	end
	connectUI(UIS.InputChanged, function(input)
		if input.UserInputType ~= Enum.UserInputType.MouseWheel or not root.Visible then return end
		local p = K.pointer()
		if K.frontAt(p) then return end
		local surface, z
		for _, panel in ipairs(K.layer:GetChildren()) do
			if panel:IsA("GuiObject") and panel.Visible and K.inside(panel, p) and (not z or panel.ZIndex > z) then
				surface, z = panel, panel.ZIndex
			end
		end
		if not surface and K.sheetFrame and K.sheetFrame.Visible then
			if not K.inside(K.sheetFrame, p) then return end
			surface = K.sheetFrame
		end
		if not surface then
			for widget in pairs(K.wheelBlockers) do
				if K.inside(widget, p) and onScreen(widget, p) then return end
			end
		end
		-- the innermost list under the pointer takes the notch; one already at
		-- its end (and not still gliding) hands it to the list behind it, so a
		-- gallery at its bottom no longer pins the page
		local lists = {}
		for sf in pairs(K.scrollers) do
			if K.inside(sf, p) and onScreen(sf, p) and (not surface or sf:IsDescendantOf(surface)) and room(sf) > 0 then
				lists[#lists + 1] = sf
			end
		end
		table.sort(lists, function(a, b) return a.AbsoluteSize.X * a.AbsoluteSize.Y < b.AbsoluteSize.X * b.AbsoluteSize.Y end)
		local down = input.Position.Z < 0
		local best
		for _, sf in ipairs(lists) do
			local at, gliding = sf.CanvasPosition.Y, K.scrollMotion[sf] ~= nil
			if gliding or (down and at < room(sf) - 0.5) or (not down and at > 0.5) then best = sf; break end
		end
		if not best then return end
		local state = K.scrollers[best]
		local step = math.max(56, best.AbsoluteWindowSize.Y / unit(best) * 0.2)
		local current = best.CanvasPosition.Y
		if not K.scrollMotion[best] or math.abs(state.target - current) > step * 4 then state.target = current end
		state.target = math.clamp(state.target - input.Position.Z * step, 0, room(best))
		state.shown = os.clock()
		K.scrollMotion[best] = state
	end)
	connectUI(K.RS.RenderStepped, function(dt)
		LPH_ATTRIBUTES(VM(NONE))
		if not root.Visible then return end
		local clock, glide, fade = os.clock(), 1 - math.exp(-dt * 15), 1 - math.exp(-dt * 10)
		for sf, state in pairs(K.scrollMotion) do
			if sf.Parent then
				if not onScreen(sf) then continue end
				local max = room(sf)
				if state.target > max then state.target = max end
				local y = sf.CanvasPosition.Y
				local gap = state.target - y
				if math.abs(gap) > 0.5 then
					sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, y + gap * glide)
				elseif gap ~= 0 then
					sf.CanvasPosition = Vector2.new(sf.CanvasPosition.X, state.target)
				end
				local want = (clock - state.shown < 0.9 and max > 0) and 0.4 or 1
				local now = sf.ScrollBarImageTransparency
				if math.abs(now - want) > 0.01 then
					sf.ScrollBarImageTransparency = now + (want - now) * fade
				elseif want == 1 and math.abs(gap) <= 0.5 then
					K.scrollMotion[sf] = nil
				end
			else
				K.scrollers[sf] = nil
				K.scrollMotion[sf] = nil
			end
		end
	end)
	function K.scrollTo(sf, y, instant)
		local state = K.scrollers[sf]
		if not state then
			sf.CanvasPosition = Vector2.new(0, y)
			return
		end
		state.target = math.clamp(y, 0, room(sf))
		state.shown = os.clock()
		K.scrollMotion[sf] = state
		if instant then sf.CanvasPosition = Vector2.new(0, state.target) end
	end
end

