	{ name = "Player", icon = "run", subs = { "Movement", "Movement Recorder", "Character", "Identity Spoofing" } },
	{ name = "World", icon = "world", subs = { "Lighting", "Post Processing", "Sky & Weather" } },
	{ name = "Cosmetics", icon = "shirt", subs = { "Presets", "Overview", "Skins", "Wraps", "Charms", "Finishers" } },
	{ name = "Automation", icon = "bolt", subs = { "Match Flow", "Auto Loadout", "In-Match Automation", "Detection" } },
	{ name = "Favorites", icon = "star", subs = { "Saved" }, aside = true },
	-- the menu's own settings: the gear opens them
	{ name = "Settings", icon = "settings", subs = { "Menu", "Theme", "Script" }, aside = true },
}

local tabs, current = {}, nil
local registry, bindables = {}, {}
local galleryByPath = {}
local refreshKeyList, rebuildFavs
K.searchIndex = {}
K.binds = {}
K.current = function() return current end
local notify

function K.releaseHold(control)
	if not control.held then return end
	control.held = false
	local item = registry[control.path]
	if item then item.set(false) end
end

function K.assignBind(control, keyName)
	K.releaseHold(control)
	control.listening = false
	if control.bindKey and K.binds[control.bindKey] == control then K.binds[control.bindKey] = nil end
	control.bindKey = keyName
	-- a control that runs its own keys (secret) may share one; the menu's own
	-- binds are one per key
	if keyName and not control.secret then
		local previous = K.binds[keyName]
		if previous and previous ~= control then
			K.releaseHold(previous)
			previous.bindKey = nil
			if previous.paintBind then previous.paintBind() end
		end
		K.binds[keyName] = control
	end
	if control.paintBind then control.paintBind() end
	if control.onAssign then control.onAssign(keyName) end
	if refreshKeyList then refreshKeyList() end
end

local function paintTab(tab, hovered)
	local on = tab == current
	if tab.label then
		tween(tab.label, 0.2, { TextColor3 = on and C.text or (hovered and C.value or C.sub) })
	end
	if tab.utility then
		tab.utility:SetAttribute("Lit", on)
		local ic = tab.utility:FindFirstChildOfClass("ImageLabel")
		if ic then
			K.Icons.set(ic, tab.iconName, on)
			tween(ic, 0.2, { ImageColor3 = on and C.text or C.sub })
		end
	end
	if tab.pill then
		local s = tab.pill
		tween(s.bg, 0.3, { BackgroundTransparency = on and 0 or 1 }, K.ease.out)
		tween(s.icon, 0.3, { ImageColor3 = on and C.onAccent or (hovered and C.text or C.sub) })
		K.Icons.set(s.icon, tab.iconName, on)
		tween(s.name, 0.3, { TextTransparency = on and 0 or 1 })
		tween(s.button, 0.38, { Size = UDim2.fromOffset(on and (50 + s.name.TextBounds.X / math.max(scaler.Scale, 0.01)) or 42, 38) }, K.ease.out)
	end
end

-- the pill under the open category
function K.markTab(tab, instant)
	local pill = K.catPill
	if MOBILE or not tab.label then
		pill.Visible = false
		return
	end
	pill.Visible = true
	local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
	local b = tab.button
	local x = (b.AbsolutePosition.X - K.top.AbsolutePosition.X) / s
	local pos, size = UDim2.new(0, x, 0.5, 0), UDim2.fromOffset(b.AbsoluteSize.X / s, 32)
	if instant or pill.Size.X.Offset < 1 then
		pill.Position, pill.Size = pos, size
	else
		tween(pill, 0.42, { Position = pos, Size = size }, K.ease.out)
	end
end

-- the page swap: the new page drifts in from the side it lies on
function K.showPage(page, instant, dx)
	local veil = K.pageVeil
	local active = running[veil]
	if active and active.BackgroundTransparency then active.BackgroundTransparency:Cancel() end
	page.Parent = K.content
	page.Visible = true
	if instant then
		page.Position = UDim2.new()
		veil.Visible = false
		return
	end
	page.Position = UDim2.fromOffset(dx or 0, 0)
	tween(page, 0.42, { Position = UDim2.new() }, K.ease.out)
	veil.BackgroundTransparency = 0
	veil.Visible = true
	tween(veil, 0.3, { BackgroundTransparency = 1 }, K.ease.out).Completed:Connect(function(state)
		if state == Enum.PlaybackState.Completed then veil.Visible = false end
	end)
	if K.stagger then K.stagger(page) end
end

function K.hidePage(page)
	page.Visible = false
	page.Parent = K.attic
end

-- the page area starts lower when a category has pages to pick from
function K.layoutContent(tab, instant)
	local pages = #tab.subs > 1
	local top = L.TOP + (pages and L.SUB or 0)
	K.subbar.Visible = pages
	local goalPos = UDim2.fromOffset(0, top)
	local goalSize = UDim2.new(1, 0, 1, -top - L.DOCK)
	local rulePos = UDim2.fromOffset(0, top - 1)
	if instant then
		K.content.Position, K.content.Size = goalPos, goalSize
		K.headRule.Position = rulePos
	else
		tween(K.content, 0.35, { Position = goalPos, Size = goalSize }, K.ease.out)
		tween(K.headRule, 0.35, { Position = rulePos }, K.ease.out)
	end
end

-- the page words are rebuilt for each category
K.trayButtons = {}
function K.buildTray(tab)
	for _, b in ipairs(K.trayButtons) do b:Destroy() end
	table.clear(K.trayButtons)
	if #tab.subs <= 1 then return end
	for index, sub in ipairs(tab.subs) do
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.fromOffset(0, K.SEG),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			FontFace = K.face.semi,
			Text = sub.name,
			TextSize = 12,
			TextColor3 = (tab.active == index) and C.text or C.sub,
			ZIndex = 6,
		}, K.trayList)
		pad(b, 0, 0, 14, 14)
		b.MouseEnter:Connect(function()
			if tab.active ~= index then tween(b, 0.15, { TextColor3 = C.value }) end
		end)
		b.MouseLeave:Connect(function()
			tween(b, 0.2, { TextColor3 = tab.active == index and C.text or C.sub })
		end)
		b.MouseButton1Click:Connect(function() K.selectSub(tab, index) end)
		b:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if current == tab and tab.active == index then K.markSub(tab, true) end
		end)
		sub.tabButton = b
		K.trayButtons[#K.trayButtons + 1] = b
	end
end

function K.markSub(tab, instant)
	LPH_ATTRIBUTES(VM(NONE))
	local sub = tab.subs[tab.active or 1]
	local b = sub and sub.tabButton
	if not (b and b.Parent) then return end
	for index, other in ipairs(tab.subs) do
		if other.tabButton then
			local color = index == tab.active and C.text or C.sub
			if other.inkTarget ~= color then
				other.inkTarget = color
				if other.tabButton.TextColor3 ~= color then tween(other.tabButton, 0.2, { TextColor3 = color }) end
			end
		end
	end
	task.defer(function()
		if not b.Parent then return end
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local x = (b.AbsolutePosition.X - K.tray.AbsolutePosition.X) / s + K.tray.CanvasPosition.X / s
		local pos, size = UDim2.new(0, x, 0.5, 0), UDim2.fromOffset(b.AbsoluteSize.X / s, K.SEG)
		if instant or K.traySlide.Size.X.Offset < 1 then
			K.traySlide.Position, K.traySlide.Size = pos, size
		else
			tween(K.traySlide, 0.38, { Position = pos, Size = size }, K.ease.out)
		end
	end)
end

function K.selectSub(tab, index, instant, animatePage)
	if tab.active == index and not instant then return end
	local previous = tab.active or index
	tab.active = index
	for i, sub in ipairs(tab.subs) do
		if i ~= index and sub.page.Parent ~= K.attic then K.hidePage(sub.page) end
	end
	if tab == current then
		local skip = instant and not animatePage
		K.showPage(tab.subs[index].page, skip, index >= previous and 18 or -18)
		if K.reflow then K.reflow(tab.subs[index]) end
		K.markSub(tab, skip)
		if not skip then SFX.click() end
	end
	if K.closeAll then K.closeAll() end
end

local function selectTab(tab, instant, subIndex)
	if current == tab then
		if subIndex then K.selectSub(tab, subIndex, instant) end
		return
	end
	if tab.name == "Favorites" and rebuildFavs then pcall(rebuildFavs) end
	local before = current
	if before and before.onClose then pcall(before.onClose) end
	current = tab
	for _, other in ipairs(tabs) do
		paintTab(other, false)
		if other ~= tab then
			for _, sub in ipairs(other.subs) do
				if sub.page.Parent ~= K.attic then K.hidePage(sub.page) end
			end
		end
	end
	K.buildTray(tab)
	K.traySlide.Size = UDim2.fromOffset(0, K.SEG)
	K.layoutContent(tab, instant or before == nil)
	K.markTab(tab, instant)
	local dir = before and ((tab.order or 0) >= (before.order or 0) and 26 or -26) or 0
	tab.active = tab.active or 1
	local index = subIndex or tab.active
	tab.active = nil
	K.selectSub(tab, index, true, not instant)
	if not instant and dir ~= 0 then
		local page = tab.subs[index].page
		page.Position = UDim2.fromOffset(dir, 0)
		tween(page, 0.45, { Position = UDim2.new() }, K.ease.out)
	end
	if tab.onOpen then pcall(tab.onOpen) end
end

for index, data in ipairs(TABS) do
	local tab = { name = data.name, subs = {}, iconName = data.icon, order = index }
	-- on a phone the gear in the top bar opens Settings, so the dock skips it
	if MOBILE and data.name ~= "Settings" then
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.fromOffset(42, 38),
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ClipsDescendants = true,
			ZIndex = 41,
		}, K.dockList)
		local bg = new("Frame", {
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = C.accent,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 41,
		}, b)
		corner(bg, "full")
		local icon = K.glyph(b, data.icon, 19, C.sub, {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 11, 0.5, 0),
			ZIndex = 42,
		})
		local name = K.text(b, {
			Position = UDim2.fromOffset(37, 0),
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			FontFace = K.face.semi,
			Text = data.name,
			TextSize = 12,
			TextColor3 = C.onAccent,
			TextTransparency = 1,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 42,
		})
		tab.pill = { button = b, bg = bg, icon = icon, name = name }
		tab.button = b
		b.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	elseif data.aside then
		-- Favorites and Settings sit with the tools on the right
		tab.utility = ({ Favorites = K.favButton, Settings = K.settingsButton })[data.name]
		tab.button = tab.utility
		tab.utility.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	else
		local b = new("TextButton", {
			LayoutOrder = index,
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 7,
		}, K.cats)
		pad(b, 0, 0, 14, 14)
		tab.label = K.text(b, {
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			Text = data.name,
			TextSize = 13,
			TextColor3 = C.sub,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 7,
		})
		tab.button = b
		-- a font that loads late or changes moves the words: the pill follows
		b:GetPropertyChangedSignal("AbsoluteSize"):Connect(function()
			if current == tab then K.markTab(tab, true) end
		end)
		b:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
			if current == tab then K.markTab(tab, true) end
		end)
		b.MouseEnter:Connect(function() paintTab(tab, true) end)
		b.MouseLeave:Connect(function() paintTab(tab, false) end)
		b.MouseButton1Click:Connect(function()
			if current ~= tab then selectTab(tab); SFX.click() end
		end)
	end
	for subIndex, subName in ipairs(data.subs) do
		local page = new("Frame", {
			Name = data.name .. "/" .. subName,
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Visible = false,
		}, K.attic)
		tab.subs[subIndex] = { name = subName, page = page, columns = {}, cards = {} }
		K.searchIndex[#K.searchIndex + 1] = { label = subName, where = data.name, tab = tab, sub = subIndex }
	end
	tabs[index] = tab
end

K.jump = function(tabName, subName)
	for _, t in ipairs(tabs) do
		if t.name == tabName then
			for i, sub in ipairs(t.subs) do
				if sub.name == subName or subName == nil then
					selectTab(t, false, i)
					return
				end
			end
		end
	end
end


-- once Inter has loaded, the words have their real widths: line the
