task.spawn(function()
	pcall(function()
		local params = Instance.new("GetTextBoundsParams")
		params.Text = "Visuals"
		params.Font = K.face.medium
		params.Size = 13
		game:GetService("TextService"):GetTextBoundsAsync(params)
	end)
	task.wait(0.1)
	if current then
		K.markTab(current, true)
		K.markSub(current, true)
	end
end)

-- ---------------------------------------------------------- moving around --
function K.clampRoot()
	local viewport = K.view()
	local halfW = root.AbsoluteSize.X / 2
	local halfH = root.AbsoluteSize.Y / 2
	local minX, maxX = halfW + 8, viewport.X - halfW - 8
	local minY, maxY = halfH + 8, viewport.Y - halfH - 8
	if minX > maxX then minX, maxX = viewport.X / 2, viewport.X / 2 end
	if minY > maxY then minY, maxY = viewport.Y / 2, viewport.Y / 2 end
	local x = root.Position.X.Scale * viewport.X + root.Position.X.Offset
	local y = root.Position.Y.Scale * viewport.Y + root.Position.Y.Offset
	root.Position += UDim2.fromOffset(math.clamp(x, minX, maxX) - x, math.clamp(y, minY, maxY) - y)
end

K.desired = Vector2.new(L.W, L.H)
function K.fitRoot()
	local viewport = K.view()
	local s = scaler.Scale
	if MOBILE then
		root.Size = UDim2.fromOffset(math.floor((viewport.X - 20) / s), math.floor((viewport.Y - 16) / s))
		root.Position = UDim2.fromScale(0.5, 0.5)
		return
	end
	local maxW = math.max(L.MINW, math.floor((viewport.X - 40) / s))
	local maxH = math.max(L.MINH, math.floor((viewport.Y - 60) / s))
	root.Size = UDim2.fromOffset(math.clamp(K.desired.X, L.MINW, maxW), math.clamp(K.desired.Y, L.MINH, maxH))
	K.clampRoot()
end

function K.setMenuScale(v)
	local viewport = K.view()
	baseScale = math.max(0.4, math.min(v, (viewport.X - 40) / L.MINW, (viewport.Y - 60) / L.MINH))
	scaler.Scale = baseScale
	K.fitRoot()
	for _, o in ipairs(followScale) do o.Scale = baseScale * (o:GetAttribute("Follow") or 0.92) end
	pcall(writefile, ROOT .. "/scale.txt", tostring(baseScale))
end

do
	local dragging, start, origin
	connectUI(UIS.InputBegan, function(input)
		if not K.isPress(input) or not root.Visible or UIS:GetFocusedTextBox() then return end
		local p = K.pointer(input)
		if K.frontAt(p) then return end
		if not K.inside(main, p) then return end
		for _, panel in ipairs(K.layer:GetChildren()) do
			if panel:IsA("GuiObject") and panel.Visible and K.inside(panel, p) then return end
		end
		for _, object in ipairs(main:GetDescendants()) do
			local control = object:IsA("GuiButton") or object:IsA("TextBox") or object:IsA("ViewportFrame")
			if input.UserInputType == Enum.UserInputType.Touch then control = control or object:IsA("ScrollingFrame") end
			if control and K.inside(object, p) then
				local visible, parent = true, object
				while parent and parent ~= main do
					if parent:IsA("GuiObject") and (not parent.Visible or (parent.ClipsDescendants and not K.inside(parent, p))) then visible = false; break end
					parent = parent.Parent
				end
				if visible then return end
			end
		end
		dragging, start, origin = input, input.Position, root.Position
	end)
	connectUI(UIS.InputChanged, function(input)
		if dragging and (input == dragging or input.UserInputType == Enum.UserInputType.MouseMovement) then
			local delta = input.Position - start
			root.Position = UDim2.new(origin.X.Scale, origin.X.Offset + delta.X, origin.Y.Scale, origin.Y.Offset + delta.Y)
			K.clampRoot()
			if K.closeFloating then K.closeFloating() end
		end
	end)
	connectUI(UIS.InputEnded, function(input)
		if input == dragging or input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = nil end
	end)
end

-- the corner resizes (PC): three dots that light up under the pointer
if not MOBILE then
	local grip = new("TextButton", {
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -4, 1, -4),
		Size = UDim2.fromOffset(18, 18),
		BackgroundTransparency = 1,
		Text = "",
		ZIndex = 20,
	}, main)
	local dots = {}
	for i, spec in ipairs({ { 12, 12 }, { 7, 12 }, { 12, 7 } }) do
		dots[i] = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(spec[1], spec[2]),
			Size = UDim2.fromOffset(2, 2),
			BackgroundColor3 = C.chip,
			BorderSizePixel = 0,
			ZIndex = 21,
		}, grip)
		corner(dots[i], "full")
	end
	grip.MouseEnter:Connect(function() for _, d in ipairs(dots) do tween(d, 0.15, { BackgroundColor3 = C.text }) end end)
	grip.MouseLeave:Connect(function() for _, d in ipairs(dots) do tween(d, 0.2, { BackgroundColor3 = C.chip }) end end)
	local resizing, start, startSize, startPos
	grip.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			resizing, start = input, input.Position
			startSize = Vector2.new(root.Size.X.Offset, root.Size.Y.Offset)
			startPos = root.Position
		end
	end)
	connectUI(UIS.InputChanged, function(input)
		if resizing and input.UserInputType == Enum.UserInputType.MouseMovement then
			local s = scaler.Scale
			local d = (input.Position - start) / s
			local screen = K.view() / s
			local w = math.clamp(startSize.X + d.X, L.MINW, math.max(L.MINW, screen.X - 40 / s))
			local h = math.clamp(startSize.Y + d.Y, L.MINH, math.max(L.MINH, screen.Y - 60 / s))
			K.desired = Vector2.new(w, h)
			root.Size = UDim2.fromOffset(w, h)
			root.Position = startPos + UDim2.fromOffset((w - startSize.X) * s / 2, (h - startSize.Y) * s / 2)
			K.clampRoot()
			if K.closeFloating then K.closeFloating() end
		end
	end)
	connectUI(UIS.InputEnded, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then resizing = nil end
	end)
end

connectUI(root:GetPropertyChangedSignal("AbsoluteSize"), function()
	if current and K.reflow then K.reflow(current.subs[current.active or 1]) end
	if current then K.markTab(current, true); K.markSub(current, true) end
end)
connectUI(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), function()
	if MOBILE then
		baseScale = math.clamp(K.view().Y / 410, 0.62, 1)
		scaler.Scale = baseScale
	end
	K.fitRoot()
end)

-- ------------------------------------------------------------------ toasts --
-- Short lines at the bottom middle of the screen: a dark capsule, a dot and
-- the words. They rise in, stack upwards and sink away.
do
	local stack = new("Frame", {
		Name = "Toasts",
		AnchorPoint = Vector2.new(0.5, 1),
		Position = UDim2.new(0.5, 0, 1, -28),
		Size = UDim2.fromOffset(420, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		ZIndex = 200,
	}, gui)
	local s = new("UIScale", { Scale = baseScale * 0.92 }, stack)
	s:SetAttribute("Follow", 0.92)
	followScale[#followScale + 1] = s
	new("UIListLayout", {
		SortOrder = Enum.SortOrder.LayoutOrder,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Bottom,
		Padding = UDim.new(0, 6),
	}, stack)
	K.toasts = stack
	local order = 0
	local live = {}
	function notify(text, duration)
		text = tostring(text or "")
		if text == "" then return end
		duration = tonumber(duration) or math.clamp(1.6 + #text / 32, 2, 5)
		for _, t in ipairs(live) do
			if t.text == text and t.frame.Parent then
				t.until_ = os.clock() + duration
				return
			end
		end
		order += 1
		local holder = new("Frame", {
			LayoutOrder = order,
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			ZIndex = 200,
		}, stack)
		local pill = new("Frame", {
			Position = UDim2.fromOffset(0, 14),
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundColor3 = C.panel,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 201,
		}, holder)
		corner(pill, "full")
		local edge = stroke(pill, C.border, 1)
		K.sheen(pill, 0.84)
		pad(pill, 0, 0, 14, 16)
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 10),
		}, pill)
		local dot = new("Frame", {
			LayoutOrder = 1,
			Size = UDim2.fromOffset(6, 6),
			BackgroundColor3 = C.accent,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			ZIndex = 202,
		}, pill)
		corner(dot, "full")
		local label = K.text(pill, {
			LayoutOrder = 2,
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			RichText = true,
			Text = text,
			TextSize = 13,
			TextTransparency = 1,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 202,
		})
		local entry = { frame = holder, text = text, until_ = os.clock() + duration }
		table.insert(live, entry)
		tween(pill, 0.45, { Position = UDim2.new(), BackgroundTransparency = 0 }, K.ease.out)
		tween(edge, 0.45, { Transparency = 0 })
		tween(dot, 0.45, { BackgroundTransparency = 0 })
		tween(label, 0.35, { TextTransparency = 0 })
		while #live > 4 do
			local old = table.remove(live, 1)
			old.until_ = 0
		end
		task.spawn(function()
			while os.clock() < entry.until_ do task.wait(0.1) end
			for i, t in ipairs(live) do if t == entry then table.remove(live, i) break end end
			tween(pill, 0.25, { Position = UDim2.fromOffset(0, 10), BackgroundTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			tween(edge, 0.2, { Transparency = 1 })
			tween(dot, 0.2, { BackgroundTransparency = 1 })
			tween(label, 0.2, { TextTransparency = 1 })
			task.wait(0.22)
			holder.AutomaticSize = Enum.AutomaticSize.None
			holder.Size = UDim2.fromOffset(holder.AbsoluteSize.X / math.max(s.Scale, 0.01), 36)
			tween(holder, 0.2, { Size = UDim2.fromOffset(holder.Size.X.Offset, 0) }, K.ease.out)
			task.wait(0.22)
			holder:Destroy()
		end)
	end
end

-- ====================================================================== 20_controls.lua
-- ---------------------------------------------------------------- floating --
-- One slot for a floating list / picker / menu. The sheet (right side of the
-- window) is separate and stacks. A click outside closes what floats.
K.slot = { popup = nil, dialog = nil }

function K.closePopup()
	local p = K.slot.popup
	if not p then return end
	K.slot.popup = nil
	if K.activeSlider and p.frame and K.activeSlider.row:IsDescendantOf(p.frame) then K.stopSlider() end
	if p.onClose then pcall(p.onClose) end
	if p.frame and p.frame.Parent then
		local frame = p.frame
		tween(frame, 0.1, { Position = frame.Position + UDim2.fromOffset(0, -4) })
		task.delay(0.07, function() frame:Destroy() end)
	end
end

function K.closeFloating()
	K.closePopup()
	if K.slot.dialog then K.slot.dialog.close() end
	if K.closeSearch then K.closeSearch() end
end

function K.closeAll()
	K.closeFloating()
	if K.closeSheets then K.closeSheets(true) end
end

-- a floating panel: shadow, black glass, a grey edge, a short drop in
function K.float(width, height, z, parent)
	z = z or 60
	local holder = new("Frame", {
		Size = UDim2.fromOffset(width, height),
		BackgroundTransparency = 1,
		ZIndex = z,
	}, parent or K.layer)
	K.shadow(holder, 26, 0.3, z)
	local box = new("Frame", {
		Name = "Box",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = z + 1,
	}, holder)
	corner(box, 10)
	stroke(box, C.border, 0)
	K.sheen(box, 0.86)
	local veil = new("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ZIndex = z + 40,
	}, box)
	tween(veil, 0.2, { BackgroundTransparency = 1 }).Completed:Connect(function() veil:Destroy() end)
	return holder, box
end

-- where a floating panel of `size` goes next to `anchor` (layer units out)
function K.place(anchor, size, side)
	local s = scaler.Scale
	local screen = K.view() / s
	local a = K.toLayer(anchor.AbsolutePosition)
	local as = anchor.AbsoluteSize / s
	local x = side == "end" and (a.X + as.X - size.X) or a.X
	local y = a.Y + as.Y + 6
	if y + size.Y > screen.Y - 8 then y = a.Y - size.Y - 6 end
	x = math.clamp(x, 8, math.max(8, screen.X - size.X - 8))
	y = math.clamp(y, 8, math.max(8, screen.Y - size.Y - 8))
	return x, y
end

-- drop the new floating panel in from a few pixels above
function K.drop(holder, x, y)
	holder.Position = UDim2.fromOffset(x, y - 6)
	tween(holder, 0.25, { Position = UDim2.fromOffset(x, y) }, K.ease.out)
end

-- the pick list behind dropdowns and multi-selects
function K.listPopup(anchor, options, isOn, onPick, multi)
	K.closePopup()
	local ITEM = MOBILE and 34 or 30
	local searchable = #options > 12
	local width = math.max(anchor.AbsoluteSize.X / scaler.Scale + 24, 200)
	local listH = math.min(#options * (ITEM + 2) + 8, MOBILE and 220 or 290)
	local height = listH + (searchable and 38 or 0)
	local holder, box = K.float(width, height, 100)
	K.drop(holder, K.place(anchor, Vector2.new(width, height), "end"))
	local filter
	if searchable then
		filter = new("TextBox", {
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 0, 36),
			BackgroundTransparency = 1,
			ClearTextOnFocus = false,
			FontFace = K.face.medium,
			PlaceholderText = "Filter",
			PlaceholderColor3 = C.faint,
			Text = "",
			TextSize = 12,
			TextColor3 = C.text,
			TextXAlignment = Enum.TextXAlignment.Left,
			ZIndex = 103,
		}, box)
		rule(box, { Position = UDim2.fromOffset(0, 36), ZIndex = 103 })
	end
	local list = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, searchable and 38 or 0),
		Size = UDim2.new(1, 0, 1, searchable and -38 or 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollBarImageColor3 = C.sub,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Active = true,
		ZIndex = 102,
	}, box)
	K.scroller(list)
	pad(list, 5, 5, 5, 5)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, list)
	local items = {}
	for i, option in ipairs(options) do
		local on = isOn(option)
		local item = new("TextButton", {
			LayoutOrder = i,
			Size = UDim2.new(1, 0, 0, ITEM),
			BackgroundColor3 = C.hover,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 103,
		}, list)
		corner(item, 7)
		local label = K.text(item, {
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, -36, 1, 0),
			Text = option,
			TextSize = 13,
			TextColor3 = on and C.text or C.sub,
			ZIndex = 104,
		})
		local mark = K.glyph(item, "check", 13, C.text, {
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, -9, 0.5, 0),
			ImageTransparency = on and 0 or 1,
			ZIndex = 104,
		})
		item.MouseEnter:Connect(function()
			tween(item, 0.12, { BackgroundTransparency = 0 })
			tween(label, 0.12, { TextColor3 = C.text })
		end)
		item.MouseLeave:Connect(function()
			tween(item, 0.18, { BackgroundTransparency = 1 })
			tween(label, 0.18, { TextColor3 = isOn(option) and C.text or C.sub })
		end)
		item.MouseButton1Click:Connect(function()
			onPick(option)
			if multi then
				tween(mark, 0.14, { ImageTransparency = isOn(option) and 0 or 1 })
			end
		end)
		items[#items + 1] = { item = item, text = string.lower(option) }
		if i <= 14 then
			label.TextTransparency = 1
			task.delay(0.01 * i, function()
				if label.Parent then tween(label, 0.18, { TextTransparency = 0 }) end
			end)
		end
	end
	if filter then
		filter:GetPropertyChangedSignal("Text"):Connect(function()
			local q = string.lower(filter.Text)
			for _, it in ipairs(items) do
				it.item.Visible = q == "" or string.find(it.text, q, 1, true) ~= nil
			end
		end)
		if not MOBILE then task.defer(function() filter:CaptureFocus() end) end
	end
	for i, option in ipairs(options) do
		if isOn(option) then
			task.defer(function() K.scrollTo(list, math.max(0, (i - 3) * (ITEM + 2)), true) end)
			break
		end
	end
	K.slot.popup = { frame = holder, owner = anchor }
	return holder
end

-- ------------------------------------------------------------------ sheet --
-- A panel floats in from the right edge of the window for anything with more
-- to say than a row: a function's extra settings, the configs. Sheets stack;
-- the top one shows, a back arrow returns. The window behind dims.
do
	local INSET = MOBILE and 8 or 10
	local W = 340
	local function goal(open)
		if MOBILE then
			return open and UDim2.new(0, INSET, 0, L.TOP + INSET) or UDim2.new(1, 24, 0, L.TOP + INSET)
		end
		return open and UDim2.new(1, -(W + INSET), 0, L.TOP + INSET) or UDim2.new(1, 24, 0, L.TOP + INSET)
	end
	local holder = new("Frame", {
		Name = "Sheet",
		Position = goal(false),
		Size = MOBILE and UDim2.new(1, -INSET * 2, 1, -(L.TOP + L.DOCK + INSET))
			or UDim2.new(0, W, 1, -(L.TOP + INSET * 2)),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 60,
	}, main)
	K.shadow(holder, 26, 0.25, 60)
	local sheet = new("Frame", {
		Name = "Box",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.panel,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		ZIndex = 61,
	}, holder)
	corner(sheet, 12)
	stroke(sheet, C.border, 0)
	K.sheen(sheet, 0.86)
	-- the dim over the window: the window's own shape, so its corners stay round
	local scrim = new("TextButton", {
		Name = "Scrim",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.void,
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		Visible = false,
		ZIndex = 55,
	}, main)
	corner(scrim, L.RADIUS)
	local head = new("Frame", { Size = UDim2.new(1, 0, 0, 50), BackgroundTransparency = 1, ZIndex = 62 }, sheet)
	rule(head, { AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), ZIndex = 62 })
	local back = K.iconButton(head, "arrow-left", 28, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
		Visible = false,
		ZIndex = 63,
	})
	local title = K.text(head, {
		Position = UDim2.fromOffset(18, 0),
		Size = UDim2.new(1, -70, 1, 0),
		FontFace = K.face.semi,
		TextSize = 14,
		Text = "",
		ZIndex = 63,
	})
	local close = K.iconButton(head, "x", 28, {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -10, 0.5, 0),
		ZIndex = 63,
	})
	local scroll = new("ScrollingFrame", {
		Position = UDim2.fromOffset(0, 51),
		Size = UDim2.new(1, 0, 1, -51),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Active = true,
		ZIndex = 61,
	}, sheet)
	K.scroller(scroll)
	K.sheetFrame = holder

	local stack = {}
	local shown, fitConn
	-- the panel is as tall as what it holds, up to the window's height
	local function fit(animate)
		if not shown then return end
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local full = holder.Parent.AbsoluteSize.Y / s - (MOBILE and (L.TOP + L.DOCK + INSET) or (L.TOP + INSET * 2))
		local want = math.min(math.floor(shown.body.AbsoluteSize.Y / s) + 51 + 12, full)
		local size = MOBILE and UDim2.new(1, -INSET * 2, 0, want) or UDim2.fromOffset(W, want)
		if animate then tween(holder, 0.25, { Size = size }, K.ease.out) else holder.Size = size end
	end
	local function show(top, dir)
		if shown then shown.y = scroll.CanvasPosition.Y end
		shown = top
		K.scrollMotion[scroll] = nil
		for _, child in ipairs(scroll:GetChildren()) do
			if child:IsA("GuiObject") then child.Parent = K.attic end
		end
		if fitConn then fitConn:Disconnect(); fitConn = nil end
		if not top then return end
		top.body.Parent = scroll
		fitConn = top.body:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() fit(true) end)
		task.defer(fit, holder.Visible)
		title.Text = top.title
		back.Visible = #stack > 1
		title.Position = UDim2.fromOffset(#stack > 1 and 44 or 18, 0)
		K.scrollTo(scroll, top.y or 0, true)
		task.defer(function() if shown == top then K.scrollTo(scroll, top.y or 0, true) end end)
		if dir then
			top.body.Position = UDim2.fromOffset(dir * 24, 0)
			tween(top.body, 0.35, { Position = UDim2.new() }, K.ease.out)
		end
	end
	local function slide(open)
		if open then
			holder.Visible, scrim.Visible = true, true
			tween(holder, 0.45, { Position = goal(true) }, K.ease.out)
			tween(scrim, 0.3, { BackgroundTransparency = 0.5 })
		else
			tween(scrim, 0.22, { BackgroundTransparency = 1 })
			tween(holder, 0.28, { Position = goal(false) }, Enum.EasingStyle.Quart, Enum.EasingDirection.In).Completed:Connect(function(state)
				if state == Enum.PlaybackState.Completed and #stack == 0 then
					holder.Visible, scrim.Visible = false, false
				end
			end)
		end
	end
	-- body: a Frame (AutomaticSize Y) that lives in the attic while closed
	function K.openSheet(name, body, opts)
		opts = opts or {}
		K.closePopup()
		for i, entry in ipairs(stack) do
			if entry.body == body then
				if i == #stack then return end
				-- open already: go back to it
				for j = #stack, i + 1, -1 do
					local gone = table.remove(stack, j)
					if gone.onClose then pcall(gone.onClose) end
				end
				show(stack[#stack], -1)
				return
			end
		end
		if opts.replace then K.closeSheets(false) end
		stack[#stack + 1] = { title = name, body = body, onClose = opts.onClose, owner = opts.owner }
		show(stack[#stack], #stack > 1 and 1 or nil)
		if #stack == 1 then slide(true) end
	end
	function K.popSheet()
		local gone = table.remove(stack)
		if gone and gone.onClose then pcall(gone.onClose) end
		if #stack == 0 then
			show(nil)
			slide(false)
		else
			show(stack[#stack], -1)
		end
	end
	function K.closeSheets(animate)
		if #stack == 0 then return end
		for i = #stack, 1, -1 do
			local gone = stack[i]
			stack[i] = nil
			if gone.onClose then pcall(gone.onClose) end
		end
		show(nil)
		if animate == false then
			holder.Visible, scrim.Visible = false, false
			holder.Position = goal(false)
			scrim.BackgroundTransparency = 1
		else
			slide(false)
		end
	end
	function K.sheetOpen(body)
		for _, entry in ipairs(stack) do if entry.body == body then return true end end
		return false
	end
	back.MouseButton1Click:Connect(function() SFX.click(); K.popSheet() end)
	close.MouseButton1Click:Connect(function() SFX.click(); K.closeSheets(true) end)
	scrim.MouseButton1Click:Connect(function() K.closeSheets(true) end)
end

-- ------------------------------------------------------------------- rows --
-- a name starts with a capital
local function nice(text)
	if type(text) ~= "string" then return text end
	return (string.gsub(text, "^%l", string.upper))
end

local ROW = L.ROW
K.rowOrders = setmetatable({}, { __mode = "k" })
K.bodyCard = setmetatable({}, { __mode = "k" })

local function rowBase(parent, height)
	local order = (K.rowOrders[parent] or 0) + 1
	K.rowOrders[parent] = order
	local info = K.bodyCard[parent]
	if info then info.rows += (height or ROW) end
	return new("Frame", {
		Name = "Row",
		LayoutOrder = order,
		Size = UDim2.new(1, 0, 0, height or ROW),
		BackgroundTransparency = 1,
	}, parent)
end

local function rowLabel(row, text, reserve)
	return K.text(row, {
		Name = "Label",
		Size = UDim2.new(1, -(reserve or 0), 0, ROW),
		Text = nice(text),
		TextSize = 13,
		TextColor3 = C.value,
		ZIndex = 2,
	})
end

-- under the pointer a row's name brightens; nothing moves
function K.rowHover(row, hit, rest)
	local label = row:FindFirstChild("Label")
	if not label then return end
	hit.MouseEnter:Connect(function()
		tween(label, 0.15, { TextColor3 = C.text })
	end)
	hit.MouseLeave:Connect(function()
		tween(label, 0.22, { TextColor3 = rest and rest() or C.value })
	end)
end

-- right-hand controls sit right to left in this order; a dropdown's field
-- takes half the row
-- Once any switch row of a section carries a colour, the other switch rows
-- keep its place empty, so the option icons stand in one column.
local ARRANGE = { "Box", "Swatch", "Swatch2", "Gear", "Bind", "Pin", "Star" }
local SWATCH = MOBILE and 20 or 16
local tinted = setmetatable({}, { __mode = "k" })
local function arrange(row, quiet)
	local body = row.Parent
	if body and not tinted[body] and row:FindFirstChild("Swatch") and row:FindFirstChild("Box") then
		tinted[body] = true
		if not quiet then
			for _, other in ipairs(body:GetChildren()) do
				if other ~= row and other.Name == "Row" then arrange(other, true) end
			end
		end
	end
	local reserve = body and tinted[body] and row:FindFirstChild("Box") ~= nil
	local x = 0
	local tall = row.Size.Y.Offset > ROW
	local label = row:FindFirstChild("Label")
	local field = row:FindFirstChild("Field")
	local star = row:FindFirstChild("Star")
	for _, name in ipairs(ARRANGE) do
		local o = row:FindFirstChild(name)
		-- beside a dropdown the star goes left of the field, which keeps its
		-- right edge in line with the switches
		if name == "Star" and field then o = nil end
		if o and o.Visible then
			o.AnchorPoint = Vector2.new(1, 0.5)
			o.Position = UDim2.new(1, -x, tall and 0 or 0.5, tall and ROW / 2 or 0)
			x += o.Size.X.Offset + (name == "Star" and 4 or 10)
		elseif name == "Swatch" and reserve then
			x += SWATCH + 10
		end
	end
	if field then
		field.AnchorPoint = Vector2.new(1, 0.5)
		field.Position = UDim2.new(1, -x, 0.5, 0)
		field.Size = UDim2.new(0.55, -x, 0, ROW)
		if star then
			star.AnchorPoint = Vector2.new(1, 0.5)
			star.Position = UDim2.new(0.45, -4, 0.5, 0)
		end
		if label then label.Size = UDim2.new(0.45, star and -28 or -6, 0, ROW) end
		return
	end
	if label then label.Size = UDim2.new(1, -(x + 4), 0, ROW) end
end
K.arrange = arrange

-- the switch: a grey capsule; on, it turns white and the knob goes dark
function K.switch(parent, props)
	local W, H = MOBILE and 38 or 34, MOBILE and 22 or 20
	local track = new("Frame", {
		Name = "Box",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.fromOffset(W, H),
		BackgroundColor3 = C.track,
		BorderSizePixel = 0,
		ZIndex = 3,
	}, parent)
	corner(track, "full")
	K.sheen(track, 0.78, true)
	for k, v in pairs(props or {}) do track[k] = v end
	local D = H - 6
	local knob = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 3, 0.5, 0),
		Size = UDim2.fromOffset(D, D),
		BackgroundColor3 = C.knob,
		BorderSizePixel = 0,
		ZIndex = 4,
	}, track)
	corner(knob, "full")
	K.sheen(knob, 0.84, true)
	return track, function(on, animate)
		local k = {
			Position = on and UDim2.new(1, -(D + 3), 0.5, 0) or UDim2.new(0, 3, 0.5, 0),
			BackgroundColor3 = on and C.onAccent or C.knob,
		}
		local t = { BackgroundColor3 = on and C.accent or C.track }
		if animate then
			tween(knob, 0.3, k, K.ease.out)
			tween(track, 0.22, t)
		else
			knob.Position, knob.BackgroundColor3 = k.Position, k.BackgroundColor3
			track.BackgroundColor3 = t.BackgroundColor3
		end
	end
end

local Section = {}
Section.__index = Section

-- a key on a control: right click the row (or the chip) and press one
function Section:bindable(text, hit, holder, trigger)
	local control = { path = self.path .. "/" .. text, label = text, trigger = trigger }
	local chip = new("TextButton", {
		Name = "Bind",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.fromOffset(22, 20),
		BackgroundColor3 = C.field,
		BackgroundTransparency = 0,
		AutoButtonColor = false,
		FontFace = K.face.semi,
		Text = "",
		TextSize = 11,
		TextColor3 = C.sub,
		Visible = false,
		ZIndex = 4,
	}, holder)
	corner(chip, 6)
	local edge = stroke(chip, C.text, 1)
	control.chip = chip
	control.badge = chip
	function control.paintBind()
		local key = control.bindKey
		chip.Visible = key ~= nil or control.listening == true
		chip.Text = control.listening and "..." or (key or "")
		chip.TextColor3 = control.listening and C.text or C.sub
		edge.Transparency = control.listening and 0 or 1
		chip.Size = UDim2.fromOffset(math.max(24, 14 + #chip.Text * 7), 20)
		if holder ~= self.tools and holder.Parent then task.defer(arrange, holder) end
	end
	local function listen()
		if MOBILE then return end
		K.closeAll()
		if K.pendingBind and K.pendingBind ~= control then
			K.pendingBind.listening = false
			K.pendingBind.paintBind()
		end
		K.pendingBind = control
		control.listening = true
		control.paintBind()
		SFX.click()
	end
	control.listen = listen
	bindables[control.path] = control
	hit.MouseButton2Click:Connect(listen)
	chip.MouseButton1Click:Connect(listen)
	return control
end

-- the star: pins a control to Favorites; it waits in the left margin
local FAV_FILE = ROOT .. "/favorites" .. K.CONFIG_EXT
K.favs, K.favSpecs, K.favItems = {}, {}, {}
local saveFavs
-- The star pins a control to Favorites. It stands in the row's line of
-- controls, left of the rest, so stars form one column down a card; it shows
-- under the pointer, and stays lit once pinned. On a slider it sits by the value.
function Section:fav(row, text, spec, holder)
	if self.nofav then return end
	local path = self.path .. "/" .. text
	spec.label = text
	K.favSpecs[path] = spec
	local tall = not holder and row.Size.Y.Offset > ROW
	local star = new("ImageButton", {
		Name = "Star",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = tall and UDim2.new(1, -76, 0, 13) or UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(18, 18),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Image = "",
		LayoutOrder = 0,
		ZIndex = 5,
	}, holder or row)
	local icon = K.glyph(star, "star", 13, C.faint, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		ImageTransparency = 1,
		ZIndex = 6,
	})
	local pop = new("UIScale", { Scale = 1 }, icon)
	local hovered, over = false, false
	local function paint()
		local on = K.favs[path]
		K.Icons.set(icon, "star", on)
		icon.ImageColor3 = on and C.text or (over and C.text or C.faint)
		icon.ImageTransparency = (on or hovered) and 0 or 1
	end
	paint()
	local host = holder and self.card or row
	host.MouseEnter:Connect(function() hovered = true; paint() end)
	host.MouseLeave:Connect(function() hovered = false; paint() end)
	star.MouseEnter:Connect(function() over = true; paint() end)
	star.MouseLeave:Connect(function() over = false; paint() end)
	star.MouseButton1Click:Connect(function()
		K.favs[path] = (not K.favs[path]) or nil
		paint()
		pop.Scale = 1.4
		tween(pop, 0.35, { Scale = 1 }, K.ease.spring)
		if K.favs[path] then SFX.on() else SFX.off() end
		if saveFavs then saveFavs() end
	end)
end

function Section:register(text, get, set, target)
	self.hasRows = true
	if self.noRegister then return end
	if get then
		registry[self.path .. "/" .. text] = { get = get, set = set }
	end
	if self.nofav then return end
	if not target then
		target = self.header or self.card
		local order = -math.huge
		for _, child in ipairs(self.body:GetChildren()) do
			if child:IsA("GuiObject") and (child.Name == "Row" or child.Name == "Buttons") and child.LayoutOrder > order then
				target, order = child, child.LayoutOrder
			end
		end
	end
	K.searchIndex[#K.searchIndex + 1] = { label = nice(text), where = self.where, tab = self.tab, sub = self.sub, card = self.card, target = target, section = self }
end

-- The first toggle of a section that switches the whole section on becomes
-- the switch on its title line; the rows fade back while it is off.
local MASTER = { enabled = true, global = true }
local function isMaster(sec, text)
	if not sec.tools or sec.nofav or sec.hasRows then return false end
	local t, title = string.lower(text), string.lower(sec.title or "")
	return MASTER[t] or t == title or t .. "s" == title or t == title .. "s"
end

function Section:master(text, on, callback)
	local track, paintPill = K.switch(self.tools, { LayoutOrder = 9, AnchorPoint = Vector2.zero })
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 6 }, track)
	-- a zero-height first item in the body list holds the shade, sized to
	-- the body, so the list keeps its order
	local host = new("Frame", {
		Name = "Dim",
		LayoutOrder = -1,
		Size = UDim2.new(1, 0, 0, 0),
		BackgroundTransparency = 1,
		ZIndex = 10,
	}, self.body)
	local shade = new("Frame", {
		Position = UDim2.fromOffset(-L.CARD, 0),
		Size = UDim2.new(1, L.CARD * 2, 0, 0),
		BackgroundColor3 = C.card,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Active = false,
		ZIndex = 20,
	}, host)
	local fade = new("UIGradient", { Rotation = 90 }, shade)
	local body = self.body
	local function fit()
		local height = body.AbsoluteSize.Y / math.max(scaler.Scale * K.pop.Scale, 0.01) + L.CARD
		if math.abs(shade.Size.Y.Offset - height) > 0.01 then
			shade.Size = UDim2.new(1, L.CARD * 2, 0, height)
			fade.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(math.clamp(1 - 16 / math.max(height, 16), 0.01, 0.99), 0),
				NumberSequenceKeypoint.new(1, 1),
			})
		end
	end
	body:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
	fit()
	local head = self.head
	local function paint(animate)
		paintPill(on, animate)
		local goal = on and 1 or 0.45
		if animate then
			tween(shade, 0.3, { BackgroundTransparency = goal })
			tween(head, 0.3, { TextColor3 = on and C.text or C.sub })
		else
			shade.BackgroundTransparency = goal
			head.TextColor3 = on and C.text or C.sub
		end
	end
	paint(false)
	self:register(text, function() return on end, function(v)
		on = v == true
		paint(false)
		if refreshKeyList then refreshKeyList() end
		if callback then task.spawn(callback, on) end
	end)
	local function flip()
		on = not on
		paint(true)
		if refreshKeyList then refreshKeyList() end
		if on then SFX.on() else SFX.off() end
		if callback then task.spawn(callback, on) end
	end
	hit.MouseButton1Click:Connect(flip)
	local control = self:bindable(text, hit, self.tools, flip)
	control.chip.LayoutOrder = 8
	self.header.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton2 then control.listen() end
	end)
	self:fav(self.header, text, { kind = "toggle" }, self.tools)
	return self, self.header
end

function Section:toggle(text, default, callback)
	local on = default == true
	if isMaster(self, text) then return self:master(text, on, callback) end
	local row = rowBase(self.body)
	local label = rowLabel(row, text, 48)
	local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 3 }, row)
	local _, paintPill = K.switch(row)
	local function rest() return on and C.text or C.sub end
	K.rowHover(row, hit, rest)
	local function paint(animate)
		paintPill(on, animate)
		if animate then tween(label, 0.2, { TextColor3 = on and C.text or C.sub }) else label.TextColor3 = rest() end
	end
	paint(false)
	self:register(text, function() return on end, function(v)
		on = v == true
		paint(false)
		if refreshKeyList then refreshKeyList() end
		if callback then task.spawn(callback, on) end
	end)
	local function flip()
		on = not on
		paint(true)
		if refreshKeyList then refreshKeyList() end
		if on then SFX.on() else SFX.off() end
		if callback then task.spawn(callback, on) end
	end
	hit.MouseButton1Click:Connect(flip)
	self:bindable(text, hit, row, flip)
	self:fav(row, text, { kind = "toggle" })
	arrange(row)
	return self, row
end

Section.switch = function(self, text, default, callback)
	local _, row = Section.toggle(self, text, default, callback)
	return self, row
end

-- a dropdown's field: a soft box with the value and a chevron
local function fieldBox(row)
	local box = new("TextButton", {
		Name = "Field",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.new(0.55, 0, 0, ROW),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 3,
	}, row)
	local face = new("Frame", {
		Name = "Face",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, ROW - 8),
		BackgroundColor3 = C.field,
		BorderSizePixel = 0,
		ZIndex = 3,
	}, box)
	corner(face, 7)
	K.sheen(face, 0.82)
	local label = K.text(face, {
		Name = "Value",
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -34, 1, 0),
		Text = "",
		TextSize = 12,
		TextColor3 = C.value,
		ZIndex = 4,
	})
	local caret = K.glyph(face, "chevron-down", 13, C.sub, {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, -8, 0.5, 0),
		ZIndex = 4,
	})
	box.MouseEnter:Connect(function()
		tween(face, 0.15, { BackgroundColor3 = C.hover })
		tween(label, 0.15, { TextColor3 = C.text })
		tween(caret, 0.15, { ImageColor3 = C.text })
	end)
	box.MouseLeave:Connect(function()
		tween(face, 0.2, { BackgroundColor3 = C.field })
		tween(label, 0.2, { TextColor3 = C.value })
		tween(caret, 0.2, { ImageColor3 = C.sub })
	end)
	return box, label, caret
end

function Section:dropdown(text, options, default, callback)
	local value = default or options[1]
	local row = rowBase(self.body)
	rowLabel(row, text, 0)
	local box, label, caret = fieldBox(row)
	label.Text = value or ""
	K.rowHover(row, box)
	self:register(text, function() return value end, function(v)
		if table.find(options, v) then
			value = v
			label.Text = v
			if callback then task.spawn(callback, v) end
		end
	end)
	box.MouseButton1Click:Connect(function()
		local reopen = not (K.slot.popup and K.slot.popup.owner == box)
		K.closePopup()
		if not reopen then return end
		SFX.click()
		tween(caret, 0.25, { Rotation = 180 }, K.ease.out)
		K.listPopup(box, options, function(o) return o == value end, function(option)
			value = option
			label.Text = option
			K.closePopup()
			SFX.click()
			if callback then task.spawn(callback, option) end
		end)
		K.slot.popup.onClose = function() tween(caret, 0.25, { Rotation = 0 }, K.ease.out) end
	end)
	self:fav(row, text, { kind = "dropdown", options = options })
	arrange(row)
	return self, row
end

-- a list where any number can be on; its value is the list of what is
function Section:multi(text, options, default, callback)
	local on = {}
	for _, v in ipairs(type(default) == "table" and default or { default }) do on[tostring(v)] = true end
	local row = rowBase(self.body)
	rowLabel(row, text, 0)
	local box, label, caret = fieldBox(row)
	K.rowHover(row, box)
	local function list()
		local out = {}
		for _, o in ipairs(options) do
			if on[o] then out[#out + 1] = o end
		end
		return out
	end
	local function paint()
		local l = list()
		label.Text = #l == 0 and "None" or (#l == #options and #options > 1) and ("All " .. #l) or table.concat(l, ", ")
	end
	paint()
	local function fire()
		if callback then task.spawn(callback, list()) end
	end
	local function set(v)
		table.clear(on)
		for _, o in ipairs(type(v) == "table" and v or { v }) do on[tostring(o)] = true end
		paint()
		fire()
	end
	self:register(text, list, set)
	box.MouseButton1Click:Connect(function()
		local reopen = not (K.slot.popup and K.slot.popup.owner == box)
		K.closePopup()
		if not reopen then return end
		SFX.click()
		tween(caret, 0.25, { Rotation = 180 }, K.ease.out)
		K.listPopup(box, options, function(o) return on[o] == true end, function(option)
			on[option] = not on[option] or nil
			SFX.click()
			paint()
			fire()
		end, true)
		K.slot.popup.onClose = function() tween(caret, 0.25, { Rotation = 0 }, K.ease.out) end
	end)
	self:fav(row, text, { kind = "multi", options = options })
	arrange(row)
	return {
		get = list,
		set = set,
		setlist = function(l)
			table.clear(options)
			for i, v in ipairs(l) do options[i] = tostring(v) end
			paint()
		end,
	}
end

-- one slider drags at a time, wherever the pointer goes
K.activeSlider = nil
function K.stopSlider()
	local active = K.activeSlider
	K.activeSlider = nil
	if active and active.release then active.release() end
end
connectUI(UIS.InputChanged, function(input)
	local active = K.activeSlider
	if not active then return end
	if not root.Visible then K.stopSlider() return end
	if input == active.input or input.UserInputType == Enum.UserInputType.MouseMovement then
		active.move(input.Position.X)
	end
end)
connectUI(UIS.InputEnded, function(input)
	local active = K.activeSlider
	if active and (input == active.input or (active.input.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1)) then
		K.stopSlider()
	end
end)

-- a rounded track, a white fill for the value, a round knob to hold
function Section:slider(text, min, max, default, callback, suffix, step)
	local value = default or min
	suffix = suffix or ""
	local H = MOBILE and 50 or 46
	local row = rowBase(self.body, H)
	local label = rowLabel(row, text, 76)
	label.Size = UDim2.new(1, -76, 0, 26)
	local readout = new("TextBox", {
		Name = "Value",
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.fromOffset(72, 26),
		BackgroundTransparency = 1,
		ClearTextOnFocus = false,
		FontFace = K.face.medium,
		TextSize = 12,
		TextColor3 = C.sub,
		TextXAlignment = Enum.TextXAlignment.Right,
		ZIndex = 3,
	}, row)
	local K0 = MOBILE and 16 or 14
	local bar = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, K0 / 2, 0, H - 12),
		Size = UDim2.new(1, -K0, 0, 4),
		BackgroundColor3 = C.track,
		BorderSizePixel = 0,
		ZIndex = 2,
	}, row)
	corner(bar, "full")
	local fill = new("Frame", { Size = UDim2.fromScale(0, 1), BackgroundColor3 = C.accent, BorderSizePixel = 0, ZIndex = 3 }, bar)
	corner(fill, "full")
	local knob = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(K0, K0),
		BackgroundColor3 = C.accent,
		BorderSizePixel = 0,
		ZIndex = 4,
	}, bar)
	corner(knob, "full")
	K.sheen(knob, 0.84, true)
	local knobScale = new("UIScale", { Scale = 1 }, knob)
	local grab = new("TextButton", {
		Position = UDim2.fromOffset(0, H - 28),
		Size = UDim2.new(1, 0, 0, 28),
		BackgroundTransparency = 1,
		Text = "",
		ZIndex = 5,
	}, row)
	K.rowHover(row, grab)
	local hovering, dragging = false, false
	local function grow()
		tween(knobScale, 0.2, { Scale = (dragging and 1.25) or (hovering and 1.12) or 1 }, K.ease.out)
		tween(readout, 0.2, { TextColor3 = (dragging or hovering) and C.text or C.sub })
	end
	grab.MouseEnter:Connect(function() hovering = true; grow() end)
	grab.MouseLeave:Connect(function() hovering = false; grow() end)
	step = step or 1
	local places = step < 1 and math.max(math.ceil(-math.log10(step) - 1e-9), 0) or 0
	local queued, dispatching
	local function emit(v)
		if not callback then return end
		queued = v
		if dispatching then return end
		dispatching = true
		task.spawn(function()
			while queued ~= nil do
				local latest = queued
				queued = nil
				local ok, err = pcall(callback, latest)
				if not ok then warn("[slider] " .. tostring(err)) end
			end
			dispatching = false
		end)
	end
	local function set(v, fire, animate)
		v = math.clamp(min + math.floor((v - min) / step + 0.5) * step, min, max)
		local changed = v ~= value
		value = v
		local k = max > min and (value - min) / (max - min) or 0
		if animate then
			tween(fill, 0.25, { Size = UDim2.fromScale(k, 1) }, K.ease.out)
			tween(knob, 0.25, { Position = UDim2.fromScale(k, 0.5) }, K.ease.out)
		else
			fill.Size = UDim2.fromScale(k, 1)
			knob.Position = UDim2.fromScale(k, 0.5)
		end
		readout.Text = (places > 0 and string.format("%." .. places .. "f", value) or tostring(value)) .. suffix
		if fire and changed then emit(value) end
	end
	set(value, false)
	readout.Focused:Connect(function()
		readout.Text = places > 0 and string.format("%." .. places .. "f", value) or tostring(value)
		readout.TextColor3 = C.text
	end)
	readout.FocusLost:Connect(function()
		readout.TextColor3 = C.sub
		local typed = tonumber(readout.Text:match("[-+]?%d*%.?%d+"))
		set(typed or value, typed ~= nil, true)
	end)
	self:register(text, function() return value end, function(v)
		if tonumber(v) then set(tonumber(v), true) end
	end)
	local function follow(x)
		set(min + (max - min) * math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1), true)
	end
	grab.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			K.stopSlider()
			dragging = true
			grow()
			K.activeSlider = {
				input = input, row = row, move = follow,
				release = function() dragging = false; grow() end,
			}
			follow(input.Position.X)
		end
	end)
	row.Destroying:Connect(function()
		if K.activeSlider and K.activeSlider.row == row then K.activeSlider = nil end
	end)
	self:fav(row, text, { kind = "slider", min = min, max = max, step = step, suffix = suffix })
	return self, row
end

-- buttons: an outline that turns solid white under the pointer; two share a
-- row when they come one after the other
function Section:button(text, callback)
	local kids, last = self.body:GetChildren(), nil
	for i = #kids, 1, -1 do
		if kids[i]:IsA("GuiObject") and kids[i].Name ~= "Dim" then last = kids[i] break end
	end
	local bar = last
	local H = MOBILE and 36 or 30
	if not (bar and bar.Name == "Buttons" and #bar:GetChildren() < 3) then
		bar = rowBase(self.body, H + 8)
		bar.Name = "Buttons"
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			SortOrder = Enum.SortOrder.LayoutOrder,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 8),
		}, bar)
	end
	local b = new("TextButton", {
		Size = UDim2.new(1, 0, 0, H),
		BackgroundColor3 = C.field,
		AutoButtonColor = false,
		FontFace = K.face.medium,
		Text = nice(text),
		TextSize = 13,
		TextColor3 = C.value,
		ZIndex = 3,
	}, bar)
	corner(b, 8)
	K.sheen(b, 0.82)
	local pair = {}
	for _, c in ipairs(bar:GetChildren()) do
		if c:IsA("TextButton") then pair[#pair + 1] = c end
	end
	for _, c in ipairs(pair) do c.Size = UDim2.new(1 / #pair, -8 * (#pair - 1) / #pair, 0, H) end
	self:register(text)
	b.MouseEnter:Connect(function()
		tween(b, 0.15, { BackgroundColor3 = C.hover, TextColor3 = C.text })
	end)
	b.MouseLeave:Connect(function()
		tween(b, 0.22, { BackgroundColor3 = C.field, TextColor3 = C.value })
	end)
	K.press(b)
	local function press()
		SFX.click()
		if callback then task.spawn(callback) end
	end
	b.MouseButton1Click:Connect(press)
	self:bindable(text, b, b, press)
	return self
end

-- ------------------------------------------------------------------ colour --
local function toColor(v)
	if typeof(v) == "Color3" then return v end
	if type(v) == "string" then
		local ok, c = pcall(Color3.fromHex, v)
		if ok then return c end
	end
	return nil
end

K.recent = {}
K.SWATCHES = {
	Color3.fromRGB(255, 255, 255), Color3.fromRGB(170, 170, 176), Color3.fromRGB(90, 90, 96),
	Color3.fromRGB(255, 90, 90), Color3.fromRGB(255, 190, 80), Color3.fromRGB(110, 220, 140),
	Color3.fromRGB(90, 160, 255), Color3.fromRGB(190, 120, 255),
}

-- a square of shade, a hue line, the hex, a row of quick picks
function K.openPicker(anchor, start, onPick)
	K.closePopup()
	local W, P = 232, 12
	local fieldH = 132
	local height = P + fieldH + 12 + 8 + 12 + 28 + 10 + 18 + P
	local holder, box = K.float(W, height, 110)
	K.drop(holder, K.place(anchor, Vector2.new(W, height), "end"))
	K.slot.popup = { frame = holder, owner = anchor }
	local h, s, v = start:ToHSV()

	local field = new("TextButton", {
		Position = UDim2.fromOffset(P, P),
		Size = UDim2.new(1, -P * 2, 0, fieldH),
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 112,
	}, box)
	corner(field, 7)
	local white = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, ZIndex = 113 }, field)
	corner(white, 7)
	new("UIGradient", { Transparency = NumberSequence.new(0, 1) }, white)
	local black = new("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0, ZIndex = 114 }, field)
	corner(black, 7)
	new("UIGradient", { Rotation = 90, Transparency = NumberSequence.new(1, 0) }, black)
	local dot = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Size = UDim2.fromOffset(12, 12),
		BackgroundTransparency = 1,
		ZIndex = 115,
	}, field)
	corner(dot, "full")
	stroke(dot, Color3.new(1, 1, 1), 0).Thickness = 2

	local strip = new("TextButton", {
		Position = UDim2.fromOffset(P, P + fieldH + 12),
		Size = UDim2.new(1, -P * 2, 0, 8),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 112,
	}, box)
	corner(strip, "full")
	local hues = {}
	for i = 0, 6 do hues[#hues + 1] = ColorSequenceKeypoint.new(i / 6, Color3.fromHSV((i / 6) % 1, 1, 1)) end
	new("UIGradient", { Color = ColorSequence.new(hues) }, strip)
	local thumb = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(h, 0.5),
		Size = UDim2.fromOffset(4, 16),
		BackgroundColor3 = Color3.new(1, 1, 1),
		BorderSizePixel = 0,
		ZIndex = 113,
	}, strip)
	corner(thumb, 2)
	stroke(thumb, C.window, 0)

	local y = P + fieldH + 12 + 8 + 12
	local preview = new("Frame", {
		Position = UDim2.fromOffset(P, y),
		Size = UDim2.fromOffset(28, 28),
		BorderSizePixel = 0,
		ZIndex = 112,
	}, box)
	corner(preview, 7)
	stroke(preview, C.border, 0)
	local hex = new("TextBox", {
		Position = UDim2.fromOffset(P + 36, y),
		Size = UDim2.new(1, -(P * 2 + 36), 0, 28),
		BackgroundColor3 = C.field,
		ClearTextOnFocus = false,
		FontFace = K.face.medium,
		Text = "",
		TextSize = 12,
		TextColor3 = C.text,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 112,
	}, box)
	corner(hex, 7)
	pad(hex, 0, 0, 10, 10)

	local row = new("Frame", {
		Position = UDim2.fromOffset(P, y + 38),
		Size = UDim2.new(1, -P * 2, 0, 18),
		BackgroundTransparency = 1,
		ZIndex = 112,
	}, box)
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
	}, row)

	local function paint(fire)
		local c = Color3.fromHSV(h, s, v)
		field.BackgroundColor3 = Color3.fromHSV(h, 1, 1)
		dot.Position = UDim2.fromScale(s, 1 - v)
		thumb.Position = UDim2.fromScale(h, 0.5)
		preview.BackgroundColor3 = c
		if not hex:IsFocused() then hex.Text = "#" .. string.upper(c:ToHex()) end
		if fire then onPick(c) end
	end
	paint(false)

	local picks = {}
	for _, c in ipairs(K.recent) do picks[#picks + 1] = c end
	for _, c in ipairs(K.SWATCHES) do
		if #picks >= 9 then break end
		local seen = false
		for _, p in ipairs(picks) do if p == c then seen = true end end
		if not seen then picks[#picks + 1] = c end
	end
	for i, c in ipairs(picks) do
		if i > 9 then break end
		local sw = new("TextButton", {
			LayoutOrder = i,
			Size = UDim2.fromOffset(18, 18),
			BackgroundColor3 = c,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 113,
		}, row)
		corner(sw, "full")
		stroke(sw, C.border, 0)
		K.press(sw)
		sw.MouseButton1Click:Connect(function()
			h, s, v = c:ToHSV()
			paint(true)
		end)
	end

	hex.FocusLost:Connect(function()
		local text = hex.Text:gsub("[^%x]", "")
		if #text == 6 then
			local c = toColor(text)
			if c then
				h, s, v = c:ToHSV()
				paint(true)
				return
			end
		end
		paint(false)
	end)

	local dragging
	local function follow(input)
		local p = K.pointer(input)
		if dragging == field then
			s = math.clamp((p.X - field.AbsolutePosition.X) / math.max(field.AbsoluteSize.X, 1), 0, 1)
			v = 1 - math.clamp((p.Y - field.AbsolutePosition.Y) / math.max(field.AbsoluteSize.Y, 1), 0, 1)
		elseif dragging == strip then
			h = math.clamp((p.X - strip.AbsolutePosition.X) / math.max(strip.AbsoluteSize.X, 1), 0, 0.999)
		end
		paint(true)
	end
	for _, area in ipairs({ field, strip }) do
		area.InputBegan:Connect(function(input)
			if K.isPress(input) then
				dragging = area
				follow(input)
			end
		end)
	end
	local moved = UIS.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			follow(input)
		end
	end)
	local ended = UIS.InputEnded:Connect(function(input)
		if K.isPress(input) then dragging = nil end
	end)
	holder.Destroying:Connect(function()
		moved:Disconnect()
		ended:Disconnect()
		local c = Color3.fromHSV(h, s, v)
		for i = #K.recent, 1, -1 do if K.recent[i] == c then table.remove(K.recent, i) end end
		table.insert(K.recent, 1, c)
		while #K.recent > 4 do table.remove(K.recent) end
	end)
end

-- a colour's mark on a row: a small rounded square with a grey ring (a round
-- one next to a switch read as a second switch knob)
local function swatchButton(row, value)
	local swatch = new("TextButton", {
		Name = "Swatch",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.fromOffset(MOBILE and 20 or 16, MOBILE and 20 or 16),
		BackgroundColor3 = value,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 4,
	}, row)
	corner(swatch, 5)
	stroke(swatch, C.chip, 0).Thickness = 1.5
	K.press(swatch)
	return swatch
end

-- values travel through configs as hex
function Section:color(text, default, callback)
	local value = toColor(default) or C.accent
	local row = rowBase(self.body)
	rowLabel(row, text, 40)
	local swatch = swatchButton(row, value)
	K.rowHover(row, swatch)
	local function set(c, fire)
		value = c
		swatch.BackgroundColor3 = c
		if fire and callback then task.spawn(callback, c) end
	end
	self:register(text, function() return value:ToHex() end, function(v)
		local c = toColor(v)
		if c then set(c, true) end
	end)
	swatch.MouseButton1Click:Connect(function()
		if K.slot.popup and K.slot.popup.owner == swatch then K.closePopup() return end
		SFX.click()
		K.openPicker(swatch, value, function(c) set(c, true) end)
	end)
	self:fav(row, text, { kind = "color" })
	arrange(row)
	return {
		get = function() return value end,
		set = function(c)
			c = toColor(c)
			if c then set(c, true) end
		end,
	}
end

-- a colour riding on the end of another row (a toggle's colour)
function Section:inlineColor(row, text, default, callback)
	local value = toColor(default) or C.accent
	local swatch = swatchButton(row, value)
	local function set(c, fire)
		value = c
		swatch.BackgroundColor3 = c
		if fire and callback then task.spawn(callback, c) end
	end
	self:register(text, function() return value:ToHex() end, function(v)
		local c = toColor(v)
		if c then set(c, true) end
	end)
	swatch.MouseButton1Click:Connect(function()
		if K.slot.popup and K.slot.popup.owner == swatch then K.closePopup() return end
		SFX.click()
		K.openPicker(swatch, value, function(c) set(c, true) end)
	end)
	arrange(row)
	return { get = function() return value end, set = function(c) c = toColor(c) if c then set(c, true) end end }
end

-- the callback gets the key's name, "" when cleared
function Section:keybind(text, default, callback)
	local key = typeof(default) == "EnumItem" and default.Name or default
	local row = rowBase(self.body)
	rowLabel(row, text, 0)
	local box = new("TextButton", {
		Name = "Field",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.new(0.55, 0, 0, ROW),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 3,
	}, row)
	local chip = K.text(box, {
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(0, ROW - 8),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundColor3 = C.field,
		BackgroundTransparency = 0,
		FontFace = K.face.semi,
		TextSize = 12,
		TextColor3 = C.value,
		TextXAlignment = Enum.TextXAlignment.Center,
		TextTruncate = Enum.TextTruncate.None,
		ZIndex = 4,
	})
	corner(chip, 7)
	K.sheen(chip, 0.82)
	pad(chip, 0, 0, 11, 11)
	K.rowHover(row, box)
	box.MouseEnter:Connect(function() tween(chip, 0.15, { BackgroundColor3 = C.hover }) end)
	box.MouseLeave:Connect(function() tween(chip, 0.2, { BackgroundColor3 = C.field }) end)
	local function show(text_, color)
		chip.Text = text_
		chip.TextColor3 = color
	end
	local function set(v, fire)
		if typeof(v) == "EnumItem" then v = v.Name end
		key = (type(v) == "string" and v ~= "" and v ~= "none" and v ~= "None") and v or nil
		show(key or "None", key and C.text or C.faint)
		if fire and callback then task.spawn(callback, key or "") end
	end
	set(key, false)
	self:register(text, function() return key end, function(v) set(v, true) end)
	local listening
	box.MouseButton1Click:Connect(function()
		if listening then return end
		listening = connectUI(UIS.InputBegan, function(input)
			if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
			listening:Disconnect()
			uiConnections[listening] = nil
			listening = nil
			local clear = input.KeyCode == Enum.KeyCode.Escape or input.KeyCode == Enum.KeyCode.Backspace
			set(not clear and input.KeyCode or nil, true)
			if clear then SFX.off() else SFX.on() end
		end, row)
		SFX.click()
		show("Press a key", C.text)
	end)
	self:fav(row, text, { kind = "keybind" })
	arrange(row)
	return { get = function() return key end, set = function(v) set(v, true) end }
end

function Section:label(text)
	self.hasRows = true
	local row = rowBase(self.body, 22)
	local l = rowLabel(row, text, 0)
	l.Size = UDim2.new(1, 0, 1, 0)
	l.FontFace = K.face.regular
	l.TextColor3, l.TextSize = C.sub, 12
	l.TextWrapped = true
	l.TextTruncate = Enum.TextTruncate.None
	l.Text = (string.gsub(l.Text, "^%l", string.upper))
	local function fit()
		row.Size = UDim2.new(1, 0, 0, math.max(22, l.TextBounds.Y / math.max(scaler.Scale, 0.01) + 6))
	end
	l:GetPropertyChangedSignal("TextBounds"):Connect(fit)
	return {
		get = function() return l.Text end,
		set = function(v) l.Text = (string.gsub(tostring(v), "^%l", string.upper)) end,
	}
end

-- A function's extra settings: three dots at the end of its row open them
-- in the sheet on the right. The body waits in the attic until then.
function Section:options(row, name, title)
	local inHeader = self.tools ~= nil and row == self.header
	local gear = new("ImageButton", {
		Name = "Gear",
		AnchorPoint = Vector2.new(1, 0.5),
		Size = UDim2.fromOffset(20, 20),
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Image = "",
		LayoutOrder = 7,
		ZIndex = 5,
	}, inHeader and self.tools or row)
	local icon = K.glyph(gear, "adjustments-horizontal", 16, C.faint, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		ZIndex = 6,
	})
	if not inHeader then arrange(row) end
	gear.MouseEnter:Connect(function() tween(icon, 0.15, { ImageColor3 = C.text }) end)
	gear.MouseLeave:Connect(function()
		tween(icon, 0.2, { ImageColor3 = gear:GetAttribute("Open") and C.text or C.faint })
	end)

	local body = new("Frame", {
		Name = "Options",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
	}, K.attic)
	pad(body, 10, 18, 20, 20)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, MOBILE and 2 or 1) }, body)

	local function reveal()
		if self.revealOptions and not K.sheetOpen(self.body) then self.revealOptions() end
		gear:SetAttribute("Open", true)
		tween(icon, 0.2, { ImageColor3 = C.text })
		K.openSheet(nice(title or name), body, {
			replace = not self.inSheet,
			owner = gear,
			onClose = function()
				gear:SetAttribute("Open", false)
				tween(icon, 0.2, { ImageColor3 = C.faint })
			end,
		})
	end
	gear.MouseButton1Click:Connect(function()
		if K.sheetOpen(body) then K.closeSheets(true); return end
		SFX.click()
		reveal()
	end)

	return setmetatable({
		body = body,
		head = self.head,
		card = self.card,
		tab = self.tab,
		sub = self.sub,
		inSheet = true,
		revealOptions = reveal,
		path = self.path .. "/" .. name,
		where = self.where .. " / " .. nice(title or name),
	}, Section)
end

-- a click outside closes a floating list (the sheet has its own scrim)
connectUI(UIS.InputBegan, function(input)
	if not K.isPress(input) then return end
	local p = K.pointer(input)
	local popup = K.slot.popup
	if popup and not K.inside(popup.frame, p) and not (popup.owner and K.inside(popup.owner, p)) then
		task.defer(K.closePopup)
	end
end)

-- a small menu at the pointer: a title and a list of things to do
local function popmenu(cfg)
	K.closePopup()
	local rows = cfg.items or {}
	local sliders = cfg.sliders or {}
	local ITEM = MOBILE and 34 or 30
	local width = tonumber(cfg.width) or 200
	local titled = cfg.title ~= nil and cfg.title ~= ""
	local height = (titled and 32 or 4) + #rows * (ITEM + 2) + #sliders * (MOBILE and 50 or 46) + 6
	local holder, box = K.float(width, height, 120)
	local s = scaler.Scale
	local screen = K.view() / s
	local at = K.toLayer(Vector2.new(tonumber(cfg.x) or 0, tonumber(cfg.y) or 0))
	if cfg.follow and cfg.follow.Parent then
		K.drop(holder, K.place(cfg.follow, Vector2.new(width, height), "end"))
	else
		K.drop(holder, math.clamp(at.X, 8, math.max(8, screen.X - width - 8)), math.clamp(at.Y, 8, math.max(8, screen.Y - height - 8)))
	end
	K.slot.popup = { frame = holder, owner = cfg.follow }
	if titled then
		K.text(box, {
			Position = UDim2.fromOffset(12, 0),
			Size = UDim2.new(1, -24, 0, 30),
			FontFace = K.face.semi,
			Text = tostring(cfg.title),
			TextSize = 12,
			TextColor3 = C.sub,
			ZIndex = 123,
		})
	end
	for i, r in ipairs(rows) do
		local b = new("TextButton", {
			Position = UDim2.fromOffset(4, (titled and 30 or 4) + (i - 1) * (ITEM + 2)),
			Size = UDim2.new(1, -8, 0, ITEM),
			BackgroundColor3 = C.hover,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Text = "",
			ZIndex = 122,
		}, box)
		corner(b, 7)
		local iconName = r.icon and K.Icons.has(r.icon) and r.icon
		local ic
		if iconName then
			ic = K.glyph(b, iconName, 14, C.sub, {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 10, 0.5, 0),
				ZIndex = 123,
			})
		end
		local label = K.text(b, {
			Position = UDim2.fromOffset(iconName and 32 or 10, 0),
			Size = UDim2.new(1, -(iconName and 42 or 20), 1, 0),
			Text = tostring(r.name or ""),
			TextSize = 13,
			TextColor3 = r.on and C.text or C.value,
			ZIndex = 123,
		})
		b.MouseEnter:Connect(function()
			tween(b, 0.12, { BackgroundTransparency = 0 })
			tween(label, 0.12, { TextColor3 = C.text })
			if ic then tween(ic, 0.12, { ImageColor3 = C.text }) end
		end)
		b.MouseLeave:Connect(function()
			tween(b, 0.18, { BackgroundTransparency = 1 })
			tween(label, 0.18, { TextColor3 = r.on and C.text or C.value })
			if ic then tween(ic, 0.18, { ImageColor3 = C.sub }) end
		end)
		b.MouseButton1Click:Connect(function()
			K.closePopup()
			SFX.click()
			if r.callback then task.spawn(r.callback) end
		end)
	end
	if #sliders > 0 then
		local body = new("Frame", {
			Position = UDim2.fromOffset(12, (titled and 32 or 4) + #rows * (ITEM + 2)),
			Size = UDim2.new(1, -24, 0, #sliders * (MOBILE and 50 or 46)),
			BackgroundTransparency = 1, ZIndex = 122,
		}, box)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, body)
		local section = setmetatable({ body = body, nofav = true, noRegister = true }, Section)
		for _, slider in ipairs(sliders) do
			section:slider(tostring(slider.name or "Value"), tonumber(slider.min) or 0, tonumber(slider.max) or 100,
				tonumber(slider.value) or 0, slider.callback, tostring(slider.suffix or ""), tonumber(slider.step) or 1)
		end
	end
end

-- one line of text asked for in a small dialog over a darkened screen
local function askinput(cfg)
	K.closeFloating()
	local W = MOBILE and 300 or 340
	local confirming = cfg.confirm == true
	local shade = new("TextButton", {
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = C.void,
		BackgroundTransparency = 1,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 140,
	}, K.layer)
	tween(shade, 0.25, { BackgroundTransparency = 0.4 })
	local holder, box = K.float(W, 152, 141, shade)
	holder.AnchorPoint = Vector2.new(0.5, 0.5)
	holder.Position = UDim2.new(0.5, 0, 0.5, 8)
	tween(holder, 0.3, { Position = UDim2.fromScale(0.5, 0.5) }, K.ease.out)
	K.text(box, {
		Position = UDim2.fromOffset(20, 16),
		Size = UDim2.new(1, -40, 0, 20),
		FontFace = K.face.semi,
		Text = nice(tostring(cfg.title or "")),
		TextSize = 15,
		ZIndex = 143,
	})
	local field = new(confirming and "TextLabel" or "TextBox", {
		Position = UDim2.fromOffset(20, 50),
		Size = UDim2.new(1, -40, 0, 36),
		BackgroundColor3 = C.field,
		FontFace = K.face.medium,
		Text = confirming and tostring(cfg.message or "") or tostring(cfg.text or ""),
		TextSize = 13,
		TextColor3 = C.text,
		TextXAlignment = Enum.TextXAlignment.Left,
		ZIndex = 143,
	}, box)
	if confirming then
		field.BackgroundTransparency = 1
		field.TextWrapped = true
	else
		field.ClearTextOnFocus = false
		field.PlaceholderText = tostring(cfg.hint or "")
		field.PlaceholderColor3 = C.faint
		corner(field, 8)
		local edge = stroke(field, C.text, 1)
		pad(field, 0, 0, 12, 12)
		field.Focused:Connect(function() tween(edge, 0.15, { Transparency = 0.6 }) end)
		field.FocusLost:Connect(function() tween(edge, 0.2, { Transparency = 1 }) end)
	end
	local function button(text, x, primary)
		local b = new("TextButton", {
			Position = UDim2.new(x, x == 0 and 20 or 5, 0, 100),
			Size = UDim2.new(0.5, -25, 0, 34),
			BackgroundColor3 = primary and C.accent or C.field,
			AutoButtonColor = false,
			FontFace = K.face.semi,
			Text = nice(text),
			TextSize = 13,
			TextColor3 = primary and C.onAccent or C.text,
			ZIndex = 143,
		}, box)
		corner(b, 8)
		K.sheen(b, 0.84, primary)
		K.press(b)
		return b
	end
	local no = button(tostring(cfg.deny or "Cancel"), 0, false)
	local yes = button(tostring(cfg.accept or "OK"), 0.5, true)
	local done = false
	local function finish(ok)
		if done then return end
		done = true
		if K.slot.dialog and K.slot.dialog.frame == shade then K.slot.dialog = nil end
		local text = field.Text
		tween(shade, 0.15, { BackgroundTransparency = 1 })
		holder.Visible = false
		task.delay(0.16, function() shade:Destroy() end)
		SFX.click()
		if ok and cfg.callback then
			task.spawn(function()
				if not K.unloaded and gui.Parent and env.__SaladGui == gui then cfg.callback(text) end
			end)
		end
	end
	K.slot.dialog = { frame = shade, close = function() finish(false) end }
	yes.MouseButton1Click:Connect(function() finish(true) end)
	no.MouseButton1Click:Connect(function() finish(false) end)
	shade.MouseButton1Click:Connect(function()
		if not K.inside(holder, K.pointer()) then finish(false) end
	end)
	if not confirming then
		field.FocusLost:Connect(function(enter) if enter then finish(true) end end)
		task.defer(function() if not done and field.Parent then field:CaptureFocus() end end)
	end
end

function K.confirm(title, message, accept, callback)
	askinput({ confirm = true, title = title, message = message, accept = accept, callback = callback })
end

-- ====================================================================== 30_pages.lua
-- ------------------------------------------------------------------- pages --
local function findSub(tabName, subName)
	local tab
	for _, t in ipairs(tabs) do
		if t.name == tabName then tab = t end
	end
	for i, s in ipairs(tab and tab.subs or {}) do
		if s.name == subName then return tab, s, i end
	end
	error("unknown tab/sub: " .. tostring(tabName) .. "/" .. tostring(subName))
end

local function pageOf(sub)
	if sub.scroll then return sub end
	sub.scroll = new("ScrollingFrame", {
		Name = "Scroll",
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 2,
		ScrollBarImageColor3 = C.sub,
		ScrollingDirection = Enum.ScrollingDirection.Y,
	}, sub.page)
	K.scroller(sub.scroll)
	pad(sub.scroll, MOBILE and 10 or 16, L.PAD, L.PAD, L.PAD)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, COL_GAP) }, sub.scroll)
	sub.cols = new("Frame", { Name = "Cols", LayoutOrder = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 }, sub.scroll)
	sub.wide = new("Frame", { Name = "Wide", LayoutOrder = 2, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 }, sub.scroll)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, COL_GAP) }, sub.wide)
	for i = 1, 3 do
		local column = new("Frame", {
			Name = "Column" .. i,
			Size = UDim2.new(1 / 3, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
		}, sub.cols)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, COL_GAP) }, column)
		sub.columns[i] = column
	end
	return sub
end

-- Columns as the width allows (three from 900, two from 520, else one).
-- A section remembers the column it asked for; with fewer columns the third
-- column's sections fill whichever of the first two is shorter, and on one
-- column everything stacks in reading order. Wide galleries ("span") sit
-- beside column one; a section a feature moved itself is left where it is.
K.cardOrder = 0
function K.columnsFor(width)
	if MOBILE then return width >= 640 and 2 or 1 end
	return width >= 900 and 3 or (width >= 520 and 2 or 1)
end

function K.reflow(sub)
	LPH_ATTRIBUTES(VM(NONE))
	if not (sub and sub.cols) then return end
	local width = root.Size.X.Offset - L.PAD * 2
	local n = K.columnsFor(width)
	local spanning = false
	for _, c in ipairs(sub.cards) do if c.span == "rest" then spanning = true end end
	local own = { [sub.wide] = true, [sub.cols] = true, [sub.columns[1]] = true, [sub.columns[2]] = true, [sub.columns[3]] = true }
	-- Columns nobody uses close up: a page whose cards asked for columns 1
	-- and 3 lays them out as two halves, not with an empty middle. Hidden
	-- cards do not hold a column open.
	local slot = {}
	if not spanning then
		local used = {}
		for _, c in ipairs(sub.cards) do
			local f = c.frame
			local placedElsewhere = f.Parent and not own[f.Parent]
			if not c.custom and not c.span and c.want ~= "full" and f.Visible and not placedElsewhere then
				used[c.want] = true
			end
		end
		local k = 0
		for i = 1, 3 do
			if used[i] then
				k += 1
				slot[i] = k
			end
		end
		if k >= 2 and k < n then n = k end
	end
	sub.ncols = n
	for i = 1, 3 do
		local column = sub.columns[i]
		column.Visible = i <= n
		if i <= n then
			column.Position = UDim2.new((i - 1) / n, (i - 1) * COL_GAP / n, 0, 0)
			column.Size = UDim2.new(1 / n, -(n - 1) * COL_GAP / n, 0, 0)
		end
		if spanning and n > 1 and i == 1 then
			column.Size = UDim2.new(n == 3 and 1 / 3 or 0.5, n == 3 and -COL_GAP * 2 / 3 or -COL_GAP / 2, 0, 0)
		end
	end
	local heights = { 0, 0, 0 }
	local halves = 0
	local mine = { [sub.wide] = true, [sub.cols] = true, [sub.columns[1]] = true, [sub.columns[2]] = true, [sub.columns[3]] = true }
	for _, c in ipairs(sub.cards) do
		local f = c.frame
		if f.Parent and not mine[f.Parent] then c.custom = true end
		if c.custom then
			-- placed by its owner
		elseif c.span then
			if n == 1 then
				f.Parent = sub.wide
				f.LayoutOrder = c.order
				f.Position = UDim2.new()
				f.Size = UDim2.new(1, 0, 0, 0)
			elseif c.span == "half" then
				halves += 1
				local right = halves % 2 == 0
				f.Parent = sub.cols
				f.Position = UDim2.new(right and 0.5 or 0, right and COL_GAP / 2 or 0, 0, 0)
				f.Size = UDim2.new(0.5, -COL_GAP / 2, 0, 0)
			else
				f.Parent = sub.cols
				if n == 3 then
					f.Position = UDim2.new(1 / 3, COL_GAP / 3, 0, 0)
					f.Size = UDim2.new(2 / 3, -COL_GAP / 3, 0, 0)
				else
					f.Position = UDim2.new(0.5, COL_GAP / 2, 0, 0)
					f.Size = UDim2.new(0.5, -COL_GAP / 2, 0, 0)
				end
			end
		elseif c.want == "full" then
			f.Parent = sub.wide
			f.LayoutOrder = c.order
		else
			local col
			local want = slot[c.want] or c.want
			if n >= 3 then
				col = want
			elseif n == 2 then
				col = want <= 2 and want or (heights[1] <= heights[2] and 1 or 2)
				if spanning then col = 1 end
			else
				col = 1
			end
			f.Parent = sub.columns[col]
			f.LayoutOrder = n == 1 and (c.want * 100000 + c.order) or c.order
			heights[col] += c.est()
		end
	end
end

function K.span(tabName, subName, frame, span)
	local _, sub = findSub(tabName, subName)
	pageOf(sub)
	for _, c in ipairs(sub.cards) do
		if c.frame == frame then
			c.span = span == "half" and "half" or "rest"
			K.reflow(sub)
			return
		end
	end
end

local function columnOf(sub, columnIndex)
	pageOf(sub)
	if columnIndex == "full" then return sub.wide end
	return sub.columns[math.clamp(tonumber(columnIndex) or 1, 1, 3)]
end

-- A section is a soft card a step lighter than the window: its name on top,
-- the rows under it. `icon` stays for code that tints it; it is never shown.
local function card(parent, title)
	local frame = new("Frame", {
		Name = "Section",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundColor3 = C.card,
		BorderSizePixel = 0,
	}, parent)
	corner(frame, 12)
	K.sheen(frame, 0.8)
	pad(frame, MOBILE and 6 or 8, L.CARD, L.CARD, L.CARD)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, frame)
	local header = new("Frame", {
		Name = "Header",
		LayoutOrder = 0,
		Size = UDim2.new(1, 0, 0, MOBILE and 36 or 34),
		BackgroundTransparency = 1,
	}, frame)
	local head = K.text(header, {
		Name = "Title",
		Size = UDim2.new(1, -110, 1, 0),
		FontFace = K.face.semi,
		Text = tostring(nice(title)),
		TextSize = 13,
		TextColor3 = C.text,
		ZIndex = 2,
	})
	local icon = new("ImageLabel", { Name = "Icon", Visible = false, BackgroundTransparency = 1, Size = UDim2.fromOffset(1, 1) }, header)
	local tools = new("Frame", {
		Name = "Tools",
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.new(1, 0, 0.5, 0),
		Size = UDim2.fromOffset(0, 24),
		AutomaticSize = Enum.AutomaticSize.X,
		BackgroundTransparency = 1,
		ZIndex = 3,
	}, header)
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
	}, tools)
	local body = new("Frame", {
		Name = "Body",
		LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
	}, frame)
	return frame, header, head, body, tools, icon
end

function K.addCard(sub, frame, want, body, fixed)
	K.cardOrder += 1
	local info = { frame = frame, want = want, order = K.cardOrder, rows = 0 }
	function info.est() return 60 + (fixed or info.rows) end
	if body then K.bodyCard[body] = info end
	sub.cards[#sub.cards + 1] = info
	-- a card that hides or shows can open or close a column
	local function reflow()
		if sub.reflowQueued then return end
		sub.reflowQueued = true
		task.defer(function()
			sub.reflowQueued = nil
			if sub.page.Parent then K.reflow(sub) end
		end)
	end
	connectUI(frame:GetPropertyChangedSignal("Visible"), reflow, frame)
	reflow()
	return info
end

-- the rows of a freshly shown page come up one after another
function K.stagger(page)
	LPH_ATTRIBUTES(VM(NONE))
	local n = 0
	for _, d in ipairs(page:GetDescendants()) do
		if n >= 22 then break end
		if d.Name == "Label" and d:IsA("TextLabel") and d.Parent and d.Parent.Name == "Row" then
			n += 1
			local goal = d.TextTransparency
			d.TextTransparency = 1
			task.delay(0.02 * n, function()
				if d.Parent then tween(d, 0.3, { TextTransparency = goal }) end
			end)
		end
	end
end

local builtSections = {}
function UI.section(tabName, subName, columnIndex, title, reuse)
	local key = tabName .. "/" .. subName .. "/" .. tostring(title)
	if reuse and builtSections[key] then return builtSections[key] end
	local tab, sub, subIndex = findSub(tabName, subName)
	local frame, header, head, body, tools, icon = card(columnOf(sub, columnIndex), title)
	pad(body, 0, 0, 0, 0)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, MOBILE and 2 or 0) }, body)
	tab.cards = (tab.cards or 0) + 1
	K.addCard(sub, frame, columnIndex, body)
	local where = tabName .. " / " .. subName .. " / " .. nice(title)
	K.searchIndex[#K.searchIndex + 1] = { label = nice(title), where = tabName .. " / " .. subName, tab = tab, sub = subIndex, card = frame }
	local made = setmetatable({
		body = body,
		head = head,
		card = frame,
		header = header,
		tools = tools,
		icon = icon,
		title = title,
		tab = tab,
		sub = subIndex,
		path = tabName .. "/" .. subName .. "/" .. title,
		where = where,
	}, Section)
	builtSections[key] = made
	return made
end

local THUMBS = {
	asset = "rbxthumb://type=Asset&id=%d&w=150&h=150",
	bundlethumbnail = "rbxthumb://type=BundleThumbnail&id=%d&w=150&h=150",
	avatarheadshot = "rbxthumb://type=AvatarHeadShot&id=%d&w=150&h=150",
	avatar = "rbxthumb://type=Avatar&id=%d&w=352&h=352",
	avatarbust = "rbxthumb://type=AvatarBust&id=%d&w=150&h=150",
	outfit = "rbxthumb://type=Outfit&id=%d&w=150&h=150",
}

-- A grid of pictures to pick from, one or many. Only the cells in view
-- exist, so a list of thousands scrolls like a list of ten.
function UI.gallery(tabName, subName, columnIndex, cfg)
	LPH_ATTRIBUTES(VM(NONE))
	local tab, sub, subIndex = findSub(tabName, subName)
	local name = cfg.Name or "list"
	local multi = cfg.Multi and true or false
	local size = math.floor((tonumber(cfg.Cell) or 74) * (MOBILE and 0.95 or 1))
	local gap = 6
	local maxHeight = math.clamp((tonumber(cfg.Height) or 260) * (MOBILE and 1 or 1.25), 60, MOBILE and 240 or 420)
	local shape = THUMBS[string.lower(tostring(cfg.Thumb or "Asset"))]
	local frame, _, _, body, headTools = card(columnOf(sub, columnIndex), name)
	pad(body, 2, 0, 0, 0)
	tab.cards = (tab.cards or 0) + 1
	K.addCard(sub, frame, columnIndex, nil, maxHeight + 40)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 10) }, body)

	local count = K.text(headTools, {
		LayoutOrder = 99,
		Size = UDim2.fromOffset(0, 20),
		AutomaticSize = Enum.AutomaticSize.X,
		Text = "0",
		TextSize = 12,
		TextColor3 = C.faint,
		TextTruncate = Enum.TextTruncate.None,
	})

	local data, view, bag, pick, query = {}, {}, {}, nil, ""
	local api = {}

	local tools = {}
	for _, b in ipairs(type(cfg.Buttons) == "table" and cfg.Buttons or {}) do tools[#tools + 1] = b end
	if multi and cfg.Tools ~= false then
		tools[#tools + 1] = { icon = "select-all", callback = function() api.all() end }
		tools[#tools + 1] = { icon = "eraser", callback = function() api.clear() end }
	end
	for order, b in ipairs(tools) do
		local hit
		if type(b.text) == "string" and b.text ~= "" then
			hit = new("TextButton", {
				LayoutOrder = order, Size = UDim2.fromOffset(0, 24), AutomaticSize = Enum.AutomaticSize.X,
				BackgroundColor3 = C.field, BorderSizePixel = 0, AutoButtonColor = false,
				FontFace = K.face.medium, Text = b.text, TextSize = 12, TextColor3 = C.value, ZIndex = 4,
			}, headTools)
			corner(hit, 6)
			pad(hit, 0, 0, 8, 8)
			hit.MouseEnter:Connect(function() tween(hit, 0.15, { BackgroundColor3 = C.hover, TextColor3 = C.text }) end)
			hit.MouseLeave:Connect(function() tween(hit, 0.2, { BackgroundColor3 = C.field, TextColor3 = C.value }) end)
			K.press(hit)
		else
			hit = K.iconButton(headTools, K.Icons.has(tostring(b.icon)) and tostring(b.icon) or "dots", 24, { LayoutOrder = order })
		end
		hit.MouseButton1Click:Connect(function()
			SFX.click()
			if b.callback then task.spawn(b.callback) end
		end)
	end

	local field
	if cfg.Search ~= false then
		local box = new("Frame", {
			LayoutOrder = 1,
			Size = UDim2.new(1, 0, 0, MOBILE and 34 or 30),
			BackgroundColor3 = C.field,
			BorderSizePixel = 0,
		}, body)
		corner(box, 8)
		K.sheen(box, 0.84, true)
		local line = stroke(box, C.text, 1)
		K.glyph(box, "search", 14, C.faint, {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 10, 0.5, 0),
		})
		field = new("TextBox", {
			Position = UDim2.fromOffset(32, 0),
			Size = UDim2.new(1, -40, 1, 0),
			BackgroundTransparency = 1,
			ClearTextOnFocus = false,
			FontFace = K.face.medium,
			PlaceholderText = "Search " .. string.lower(tostring(nice(name))),
			PlaceholderColor3 = C.faint,
			Text = "",
			TextSize = 13,
			TextColor3 = C.text,
			TextXAlignment = Enum.TextXAlignment.Left,
		}, box)
		field.Focused:Connect(function() tween(line, 0.2, { Transparency = 0.65 }) end)
		field.FocusLost:Connect(function() tween(line, 0.25, { Transparency = 1 }) end)
	end

	local list = new("ScrollingFrame", {
		LayoutOrder = 2,
		Size = UDim2.new(1, 0, 0, 60),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		CanvasSize = UDim2.new(),
		ScrollBarThickness = 2,
		ScrollBarImageColor3 = C.sub,
		ScrollingDirection = Enum.ScrollingDirection.Y,
		Active = true,
	}, body)
	K.scroller(list)
	local empty = new("Frame", {
		Position = UDim2.fromOffset(1, 1),
		Size = UDim2.new(1, -2, 0, 86),
		BackgroundColor3 = C.window,
		BorderSizePixel = 0,
		Visible = false,
	}, list)
	corner(empty, 10)
	stroke(empty, C.line, 0)
	K.sheen(empty, 0.9, true)
	local emptyIcon = K.glyph(empty, K.Icons.has(tostring(cfg.EmptyIcon)) and cfg.EmptyIcon or "layout-grid", 22, C.faint, {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 20),
	})
	local emptyText = K.text(empty, {
		Position = UDim2.fromOffset(0, 50),
		Size = UDim2.new(1, 0, 0, 18),
		Text = "",
		TextSize = 12,
		TextColor3 = C.faint,
		TextXAlignment = Enum.TextXAlignment.Center,
	})

	local function melt(v)
		if type(v) == "string" then
			return v ~= "" and { name = v, label = v } or nil
		end
		if type(v) ~= "table" then return nil end
		local nm = v.name or v.Name or v.label or v.Label or v.id or v.Id
		if nm == nil then return nil end
		nm = tostring(nm)
		local id = tonumber(v.id or v.Id or v.ID or v.asset or v.Asset or v.assetid or v.AssetId or v.userid or v.UserId)
		local art = v.image or v.Image or v.icon or v.Icon or v.art or v.thumb or v.Thumb
		local rect = v.rect or v.rectOffset
		local rectsize = v.rectsize or v.rectSize
		if typeof(rect) ~= "Vector2" then rect = nil end
		if typeof(rectsize) ~= "Vector2" then rectsize = nil end
		return {
			name = nm,
			label = tostring(v.display or v.Display or v.label or v.Label or nm),
			id = id,
			art = (type(art) == "string" or type(art) == "number") and art or nil,
			rect = rect,
			rectsize = rectsize,
			raw = v,
		}
	end

	local function picture(e)
		if e.art then
			if tonumber(e.art) then return "rbxassetid://" .. tostring(e.art) end
			if type(e.art) == "string" and e.art:find("://") then return e.art end
			return ""
		end
		if shape and e.id and e.id > 0 then return string.format(shape, e.id) end
		return ""
	end

	local function chosen(nm)
		if multi then return bag[nm] == true end
		return pick == nm
	end

	local function value()
		if not multi then return pick end
		local out = {}
		for _, e in ipairs(data) do
			if bag[e.name] then out[#out + 1] = e.name end
		end
		return out
	end

	local callbackGeneration = 0
	local function shout()
		if not cfg.Callback then return end
		callbackGeneration += 1
		local generation, selected = callbackGeneration, value()
		task.spawn(function()
			if generation == callbackGeneration then cfg.Callback(selected) end
		end)
	end

	local pool, live = {}, 0
	local galPath = tabName .. "/" .. subName .. "/" .. name
	-- Each cell is a small stage: the picture sits on a darker inset with a soft
	-- glow behind it and leans in under the pointer. Picked: a white edge and a
	-- check badge. The star (pin to Favorites) and the action sit in round chips
	-- on the picture's corners.
	local function dress(c, animate)
		local on = c.entry ~= nil and chosen(c.entry.name)
		local hovered = c.hovered == true
		local goals = {
			edge = { Color = on and C.knob or (hovered and C.track or C.hover) },
			frame = { BackgroundColor3 = hovered and C.chip or C.hover },
			badge = { Scale = on and 1 or 0 },
			glow = { ImageTransparency = hovered and 0.78 or 0.9 },
			zoom = { Scale = hovered and 1.07 or 1 },
			label = { TextColor3 = on and C.text or (hovered and C.value or C.sub) },
		}
		if animate then
			tween(c.edge, 0.2, goals.edge)
			tween(c.frame, 0.2, goals.frame)
			tween(c.badgeScale, 0.3, goals.badge, on and K.ease.spring or K.ease.out)
			if c.glow then tween(c.glow, 0.25, goals.glow) end
			tween(c.zoom, 0.3, goals.zoom, K.ease.out)
			tween(c.label, 0.2, goals.label)
		else
			c.edge.Color = goals.edge.Color
			c.frame.BackgroundColor3 = goals.frame.BackgroundColor3
			c.badgeScale.Scale = goals.badge.Scale
			if c.glow then c.glow.ImageTransparency = goals.glow.ImageTransparency end
			c.zoom.Scale = goals.zoom.Scale
			c.label.TextColor3 = goals.label.TextColor3
		end
		if c.star then
			local pinned = c.entry and K.favItems[galPath .. "|" .. c.entry.name]
			K.Icons.set(c.starIcon, "star", pinned ~= nil)
			c.starIcon.ImageColor3 = pinned and C.text or C.value
			local show = pinned ~= nil or hovered
			c.star.BackgroundTransparency = show and 0.25 or 1
			c.starIcon.ImageTransparency = show and 0 or 1
		end
		if c.act then
			c.act.BackgroundTransparency = hovered and 0.25 or 0.45
			c.actIcon.ImageTransparency = hovered and 0 or 0.35
		end
	end

	local layout
	local layoutQueued = false
	local viewGeneration = 0
	local drawnGeneration, drawnFirst, drawnLast, drawnCell, drawnLanes
	local function visible()
		return root.Visible and sub.page.Visible and sub.page.Parent == K.content and frame.Visible
	end
	local function queueLayout()
		if layoutQueued or not visible() then return end
		layoutQueued = true
		task.defer(function()
			layoutQueued = false
			if frame.Parent then layout() end
		end)
	end
	local function updateCount()
		local picked = 0
		if multi then
			for _, e in ipairs(data) do if bag[e.name] then picked += 1 end end
		else
			picked = pick and 1 or 0
		end
		count.Text = #view == #data and (multi and (picked .. " / " .. #data) or tostring(#data)) or (#view .. " / " .. #data)
	end
	local function tap(e)
		if multi then
			bag[e.name] = not bag[e.name] or nil
		elseif pick == e.name and cfg.Reset then
			pick = nil
		else
			pick = e.name
		end
		SFX.click()
		for i = 1, live do dress(pool[i], true) end
		updateCount()
		shout()
	end

	local function spot(c)
		local at = c.frame.AbsolutePosition
		return at.X + c.frame.AbsoluteSize.X * 0.5, at.Y + 12
	end

	local function makeCell()
		local c = {}
		c.frame = new("TextButton", {
			Size = UDim2.fromOffset(size, size + 20),
			BackgroundColor3 = C.hover,
			AutoButtonColor = false,
			Text = "",
		}, list)
		corner(c.frame, 10)
		K.sheen(c.frame, 0.8, true)
		c.edge = stroke(c.frame, C.hover, 0)
		c.edge.Thickness = 1.5
		c.stage = new("Frame", {
			Position = UDim2.fromOffset(4, 4),
			Size = UDim2.fromOffset(size - 8, size - 8),
			BackgroundColor3 = C.card,
			BorderSizePixel = 0,
			ClipsDescendants = true,
		}, c.frame)
		corner(c.stage, 8)
		if K.art.glow then
			c.glow = new("ImageLabel", {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.55),
				Size = UDim2.fromScale(1.3, 1.3),
				BackgroundTransparency = 1,
				Image = K.art.glow,
				ImageColor3 = C.text,
				ImageTransparency = 0.9,
			}, c.stage)
		end
		c.thumb = new("ImageLabel", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.new(1, -6, 1, -6),
			BackgroundTransparency = 1,
			ScaleType = Enum.ScaleType.Fit,
		}, c.stage)
		c.zoom = new("UIScale", { Scale = 1 }, c.thumb)
		c.label = K.text(c.frame, {
			Position = UDim2.new(0, 6, 0, size - 3),
			Size = UDim2.new(1, -12, 0, 20),
			FontFace = K.face.semi,
			Text = "",
			TextSize = 11,
			TextColor3 = C.sub,
			TextXAlignment = Enum.TextXAlignment.Center,
		})
		c.badge = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, -14, 0, 14),
			Size = UDim2.fromOffset(18, 18),
			BackgroundColor3 = C.window,
			BackgroundTransparency = 0.15,
			BorderSizePixel = 0,
			ZIndex = 4,
		}, c.frame)
		corner(c.badge, "full")
		stroke(c.badge, C.knob, 0.4)
		c.badgeScale = new("UIScale", { Scale = 0 }, c.badge)
		K.glyph(c.badge, "check", 11, C.text, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 5,
		})
		c.star = new("ImageButton", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(14, 14),
			Size = UDim2.fromOffset(20, 20),
			BackgroundColor3 = C.window,
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Image = "",
			ZIndex = 4,
		}, c.frame)
		corner(c.star, "full")
		c.starIcon = K.glyph(c.star, "star", 12, C.value, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ImageTransparency = 1,
			ZIndex = 5,
		})
		c.frame.MouseEnter:Connect(function()
			c.hovered = true
			dress(c, true)
		end)
		c.frame.MouseLeave:Connect(function()
			c.hovered = false
			dress(c, true)
		end)
		c.star.MouseButton1Click:Connect(function()
			local e = c.entry
			if not e then return end
			local key = galPath .. "|" .. e.name
			if K.favItems[key] then
				K.favItems[key] = nil
				SFX.off()
			else
				K.favItems[key] = { gal = galPath, item = e.name, label = e.label }
				SFX.on()
			end
			dress(c)
			if saveFavs then saveFavs() end
		end)
		K.press(c.frame, c.stage)
		c.frame.MouseButton1Click:Connect(function()
			if c.entry then tap(c.entry) end
		end)
		if type(cfg.Context) == "function" then
			c.frame.MouseButton2Click:Connect(function()
				if not c.entry then return end
				local x, y = spot(c)
				task.spawn(cfg.Context, c.entry.name, c.entry, x, y, c.frame)
			end)
		end
		if type(cfg.Action) == "table" and type(cfg.Action.callback) == "function" then
			c.act = new("ImageButton", {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromOffset(size - 14, size - 14),
				Size = UDim2.fromOffset(20, 20),
				BackgroundColor3 = C.window,
				BackgroundTransparency = 0.45,
				AutoButtonColor = false,
				Image = "",
				ZIndex = 4,
			}, c.frame)
			corner(c.act, "full")
			c.actIcon = K.glyph(c.act, "dots", 12, C.text, {
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				ZIndex = 5,
			})
			c.act.MouseButton1Click:Connect(function()
				if not c.entry then return end
				local x, y = spot(c)
				task.spawn(cfg.Action.callback, c.entry.name, c.entry, x, y, c.frame)
			end)
		end
		return c
	end

	function layout()
		if not visible() then return end
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local width = list.AbsoluteSize.X / s - 4
		local lanes = math.max(math.floor((width + gap) / (size + gap)), 1)
		local cell = math.floor((width - (lanes - 1) * gap) / lanes)
		local rows = math.ceil(#view / lanes)
		local h = cell + 20 + gap
		local canvasHeight = #view == 0 and 88 or rows * h + 2
		local visibleHeight = math.min(maxHeight, math.max(60, canvasHeight))
		if list.Size.Y.Offset ~= visibleHeight then list.Size = UDim2.new(1, 0, 0, visibleHeight) end
		if list.CanvasSize.Y.Offset ~= canvasHeight then
			list.CanvasSize = UDim2.fromOffset(0, canvasHeight)
		end
		local top = math.min(list.CanvasPosition.Y / s, math.max(0, canvasHeight - visibleHeight))
		local first = math.max(math.floor(top / h), 0) * lanes + 1
		local last = math.min(#view, (math.floor((top + visibleHeight) / h) + 1) * lanes)
		if drawnGeneration == viewGeneration and drawnFirst == first and drawnLast == last and drawnCell == cell and drawnLanes == lanes then return end
		drawnGeneration, drawnFirst, drawnLast, drawnCell, drawnLanes = viewGeneration, first, last, cell, lanes
		local used = 0
		for i = first, last do
			used += 1
			local c = pool[used]
			if not c then
				c = makeCell()
				pool[used] = c
			end
			local e = view[i]
			c.frame.Size = UDim2.fromOffset(cell, cell + 20)
			c.stage.Size = UDim2.fromOffset(cell - 8, cell - 8)
			c.label.Position = UDim2.new(0, 6, 0, cell - 3)
			if c.act then c.act.Position = UDim2.fromOffset(cell - 14, cell - 14) end
			c.frame.Position = UDim2.fromOffset(1 + ((i - 1) % lanes) * (cell + gap), 1 + math.floor((i - 1) / lanes) * h)
			c.frame.Visible = true
			if c.entry ~= e then
				c.entry = e
				c.thumb.Image = picture(e)
				if e.rect and e.rectsize then
					c.thumb.ImageRectOffset = e.rect
					c.thumb.ImageRectSize = e.rectsize
				else
					c.thumb.ImageRectOffset = Vector2.new()
					c.thumb.ImageRectSize = Vector2.new()
				end
				c.label.Text = e.label
				c.hovered = false
				dress(c)
				if cfg.Paint then pcall(cfg.Paint, c, e.raw) end
			end
		end
		for j = used + 1, #pool do
			pool[j].frame.Visible = false
			pool[j].entry = nil
		end
		live = used
		empty.Visible = #view == 0
		if #view == 0 then
			emptyText.Text = query ~= "" and "Nothing found" or (cfg.Empty == nil and "Empty" or tostring(cfg.Empty))
			emptyIcon.Visible = true
		end
	end

	local function sieve()
		table.clear(view)
		for _, e in ipairs(data) do
			if query == "" or string.find(string.lower(e.label), query, 1, true) then view[#view + 1] = e end
		end
		viewGeneration += 1
		updateCount()
		queueLayout()
	end

	local function soak(ls)
		table.clear(data)
		local seen = {}
		for _, v in pairs(type(ls) == "table" and ls or {}) do
			local e = melt(v)
			if e and not seen[e.name] then
				seen[e.name] = true
				data[#data + 1] = e
			end
		end
		if multi then
			for nm in pairs(bag) do
				if not seen[nm] then bag[nm] = nil end
			end
		elseif pick and not seen[pick] then
			pick = nil
		end
		sieve()
	end

	connectUI(list:GetPropertyChangedSignal("CanvasPosition"), queueLayout, frame)
	connectUI(list:GetPropertyChangedSignal("AbsoluteSize"), queueLayout, frame)
	connectUI(root:GetPropertyChangedSignal("Visible"), queueLayout, frame)
	connectUI(sub.page:GetPropertyChangedSignal("Visible"), queueLayout, frame)
	connectUI(frame:GetPropertyChangedSignal("Visible"), queueLayout, frame)
	connectUI(sub.page.AncestryChanged, queueLayout, frame)
	if field then
		field:GetPropertyChangedSignal("Text"):Connect(function()
			local q = string.lower(string.match(field.Text, "^%s*(.-)%s*$") or "")
			if q ~= query then
				query = q
				sieve()
			end
		end)
	end

	function api.get() return value() end
	function api.set(v, quiet)
		callbackGeneration += 1
		if multi then
			table.clear(bag)
			if type(v) == "table" then
				for k, s in pairs(v) do
					if s == true and type(k) == "string" then bag[k] = true
					elseif type(s) == "string" and s ~= "" then bag[s] = true end
				end
			elseif type(v) == "string" and v ~= "" then
				for s in string.gmatch(v, "[^,]+") do
					local nm = string.match(s, "^%s*(.-)%s*$")
					if nm ~= "" then bag[nm] = true end
				end
			end
		else
			if type(v) == "table" then v = v.name or v.Name or v[1] end
			pick = (type(v) == "string" and v ~= "") and v or nil
		end
		for i = 1, live do dress(pool[i]) end
		updateCount()
		queueLayout()
		if not quiet then shout() end
	end
	function api.setdata(ls) soak(ls) end
	function api.clear()
		table.clear(bag)
		pick = nil
		for i = 1, live do dress(pool[i], true) end
		updateCount()
		shout()
	end
	function api.all()
		if not multi then return end
		for _, e in ipairs(view) do bag[e.name] = true end
		for i = 1, live do dress(pool[i], true) end
		updateCount()
		shout()
	end
	function api.refresh() sieve() end
	function api.art(nm)
		for _, e in ipairs(data) do
			if e.name == nm then return picture(e) end
		end
	end
	function api.search(q) if field then field.Text = tostring(q or "") end end

	registry[galPath] = { get = value, set = function(v) api.set(v) end }
	galleryByPath[galPath] = api
	K.searchIndex[#K.searchIndex + 1] = { label = nice(name), where = tabName .. " / " .. subName, tab = tab, sub = subIndex, card = frame }
	soak(cfg.Values)
	if cfg.Default ~= nil then api.set(cfg.Default, true) end
	api.frame = frame
	return api
end

-- You, standing on a dark stage; the ESP and chams paint over the figure.
-- Drag to turn (a flick keeps it turning), wheel to come closer.
function UI.clone(tabName, subName, columnIndex, cfg)
	LPH_ATTRIBUTES(VM(NONE))
	local tab, sub = findSub(tabName, subName)
	local frame, _, _, body, tools = card(columnOf(sub, columnIndex), cfg.Name or "preview")
	pad(body, 2, 0, 0, 0)
	local previewHeight = math.floor((tonumber(cfg.Height) or 250) * (MOBILE and 0.8 or 1.05))
	tab.cards = (tab.cards or 0) + 1
	K.addCard(sub, frame, columnIndex, nil, previewHeight + 12)
	local folded = false
	local stage = new("Frame", {
		Size = UDim2.new(1, 0, 0, previewHeight),
		BackgroundColor3 = C.window,
		ClipsDescendants = true,
	}, body)
	corner(stage, 10)
	if K.art.glow then
		new("ImageLabel", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.42),
			Size = UDim2.fromScale(1.3, 1.1),
			BackgroundTransparency = 1,
			Image = K.art.glow,
			ImageColor3 = C.white,
			ImageTransparency = 0.94,
		}, stage)
		new("ImageLabel", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.89),
			Size = UDim2.new(0.5, 0, 0, 22),
			BackgroundTransparency = 1,
			Image = K.art.glow,
			ImageColor3 = C.void,
			ImageTransparency = 0.2,
		}, stage)
	end
	-- a faint floor line the figure stands on
	new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0.885),
		Size = UDim2.new(0.7, 0, 0, 1),
		BackgroundColor3 = C.border,
		BorderSizePixel = 0,
	}, stage).ZIndex = 1
	local vp = new("ViewportFrame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Ambient = Color3.fromRGB(160, 160, 166),
		LightColor = Color3.fromRGB(255, 255, 255),
		LightDirection = Vector3.new(-0.4, -1, -0.6),
		Active = true,
		ClipsDescendants = true,
		ZIndex = 2,
	}, stage)
	local world = new("WorldModel", {}, vp)
	local cam = new("Camera", { FieldOfView = 32 }, vp)
	K.wheelBlockers[vp] = true
	vp.CurrentCamera = cam
	local item = { viewport = vp, parts = {}, active = false }
	local renders, model = {}, nil
	local yaw, zoom, dragging, lastX, finger = math.pi, 1, false, nil, nil
	local spin = 0
	local center, extents = Vector3.zero, Vector3.new(3, 6, 2)
	local bodyNames = {
		Head = true, Torso = true, ["Left Arm"] = true, ["Right Arm"] = true, ["Left Leg"] = true, ["Right Leg"] = true,
		UpperTorso = true, LowerTorso = true,
		LeftUpperArm = true, LeftLowerArm = true, LeftHand = true, RightUpperArm = true, RightLowerArm = true, RightHand = true,
		LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true, RightUpperLeg = true, RightLowerLeg = true, RightFoot = true,
	}
	local buildPending, buildQueued = true, false
	local function visible()
		return root.Visible and sub.page.Visible and sub.page.Parent == K.content and frame.Visible and not folded
	end
	local function aim()
		if not visible() then return end
		local size = vp.AbsoluteSize
		if size.X < 2 or size.Y < 2 then return end
		local half = math.tan(math.rad(cam.FieldOfView) / 2)
		local aspect = size.X / size.Y
		local fit = math.max(extents.Y / 2 / half, math.max(extents.X, extents.Z) / 2 / (half * aspect))
		local distance = math.max(4, (fit * 1.24 + extents.Z / 2) * zoom)
		local target = center + Vector3.new(0, extents.Y * 0.02, 0)
		cam.CFrame = CFrame.lookAt(target + Vector3.new(math.sin(yaw), 0.12, math.cos(yaw)).Unit * distance, target)
	end

	local function build()
		buildPending = true
		if not visible() then return end
		local char = LP.Character
		if not char or not frame.Parent then return end
		local was = char.Archivable
		char.Archivable = true
		local ok, copy = pcall(function() return char:Clone() end)
		char.Archivable = was
		if not ok or not copy then return end
		for _, d in ipairs(copy:GetDescendants()) do
			if d:IsA("LuaSourceContainer") or d:IsA("Sound") or d:IsA("ForceField") then d:Destroy() end
		end
		table.clear(item.parts)
		for _, d in ipairs(copy:GetDescendants()) do
			if d:IsA("BasePart") then
				d.Anchored = true
				item.parts[#item.parts + 1] = d
			end
		end
		copy:PivotTo(CFrame.new(0, 0, 0))
		if LP.Character ~= char then copy:Destroy() return end
		if model then model:Destroy() end
		copy.Parent = world
		model = copy
		buildPending = false
		local lo, hi
		for _, part in ipairs(copy:GetChildren()) do
			if part:IsA("BasePart") and bodyNames[part.Name] then
				local half = part.Size / 2
				for _, x in ipairs({ -1, 1 }) do for _, y in ipairs({ -1, 1 }) do for _, z in ipairs({ -1, 1 }) do
					local p = part.CFrame:PointToWorldSpace(Vector3.new(half.X * x, half.Y * y, half.Z * z))
					lo = lo and Vector3.new(math.min(lo.X, p.X), math.min(lo.Y, p.Y), math.min(lo.Z, p.Z)) or p
					hi = hi and Vector3.new(math.max(hi.X, p.X), math.max(hi.Y, p.Y), math.max(hi.Z, p.Z)) or p
				end end end
			end
		end
		if lo and hi then center, extents = (lo + hi) / 2, hi - lo end
		aim()
		if cfg.Callback then task.spawn(cfg.Callback, model, item) end
	end
	local function queueBuild()
		if not visible() then return end
		if not buildPending then aim() return end
		if buildQueued then return end
		buildQueued = true
		task.defer(function()
			buildQueued = false
			if frame.Parent then build() end
		end)
	end
	connectUI(LP.CharacterAdded, function() task.delay(1, build) end, frame)
	connectUI(root:GetPropertyChangedSignal("Visible"), queueBuild, frame)
	connectUI(sub.page:GetPropertyChangedSignal("Visible"), queueBuild, frame)
	connectUI(sub.page.AncestryChanged, queueBuild, frame)
	connectUI(frame:GetPropertyChangedSignal("Visible"), queueBuild, frame)
	queueBuild()
	local refresh, refreshIcon = K.iconButton(tools, "refresh", 22, { LayoutOrder = 1 })
	local fold, foldIcon = K.iconButton(tools, "chevron-down", 22, { LayoutOrder = 2 })
	connectUI(refresh.MouseButton1Click, function()
		SFX.click()
		refreshIcon.Rotation = 0
		tween(refreshIcon, 0.5, { Rotation = 360 }, K.ease.out)
		task.defer(build)
	end, frame)
	connectUI(fold.MouseButton1Click, function()
		folded = not folded
		SFX.click()
		if not folded then stage.Visible = true end
		if not folded then queueBuild() end
		tween(stage, 0.35, { Size = UDim2.new(1, 0, 0, folded and 0 or previewHeight) }, K.ease.out)
		tween(foldIcon, 0.35, { Rotation = folded and -90 or 0 }, K.ease.out)
		if folded then task.delay(0.35, function() if folded and stage.Parent then stage.Visible = false end end) end
	end, frame)
	connectUI(vp.InputBegan, function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging, lastX = true, input.Position.X
			finger = input.UserInputType == Enum.UserInputType.Touch and input or nil
		end
	end, frame)
	connectUI(vp.InputChanged, function(input)
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			zoom = math.clamp(zoom * (input.Position.Z > 0 and 0.88 or 1.14), 0.45, 2.4)
			aim()
		end
	end, frame)
	connectUI(vp:GetPropertyChangedSignal("AbsoluteSize"), aim, frame)
	connectUI(UIS.InputChanged, function(input)
		if not dragging or not root.Visible then return end
		if (finger and input == finger) or (not finger and input.UserInputType == Enum.UserInputType.MouseMovement) then
			local dx = input.Position.X - (lastX or input.Position.X)
			lastX = input.Position.X
			spin = -dx * 0.012
			yaw += spin
			aim()
		end
	end, frame)
	connectUI(UIS.InputEnded, function(input)
		if (finger and input == finger) or (not finger and input.UserInputType == Enum.UserInputType.MouseButton1) then
			dragging, finger = false, nil
		end
	end, frame)
	connectUI(root:GetPropertyChangedSignal("Visible"), function()
		if not root.Visible then dragging, finger = false, nil end
	end, frame)

	local ticker
	ticker = connectUI(game:GetService("RunService").RenderStepped, function(dt)
		if not frame.Parent then ticker:Disconnect() return end
		local wasActive = item.active
		item.active = visible()
		if item.active and not dragging and math.abs(spin) > 0.0005 then
			yaw += spin
			spin *= math.exp(-dt * 4)
			aim()
		end
		if item.active or wasActive then
			for _, fn in ipairs(renders) do pcall(fn, item) end
		end
	end, frame)

	return {
		viewport = vp,
		onrender = function(_, fn) renders[#renders + 1] = fn end,
		refresh = build,
	}
end

-- -------------------------------------------------------------- favourites --
K.fav = { section = nil, gallery = nil, built = {} }

saveFavs = function()
	local rows = {}
	for path in pairs(K.favs) do rows[#rows + 1] = path end
	table.sort(rows)
	local items = {}
	for _, rec in pairs(K.favItems) do items[#items + 1] = rec end
	K.ensureFolders()
	pcall(writefile, FAV_FILE, HttpService:JSONEncode({ rows = rows, items = items }))
end

local function loadFavs()
	local ok, data = pcall(function() return HttpService:JSONDecode(readfile(FAV_FILE)) end)
	if not ok or type(data) ~= "table" then return end
	for _, path in ipairs(type(data.rows) == "table" and data.rows or {}) do
		if type(path) == "string" then K.favs[path] = true end
	end
	for _, rec in ipairs(type(data.items) == "table" and data.items or {}) do
		if type(rec) == "table" and type(rec.gal) == "string" and type(rec.item) == "string" then
			K.favItems[rec.gal .. "|" .. rec.item] = rec
		end
	end
end

rebuildFavs = function()
	local F = K.fav
	if not F.section then
		F.section = UI.section("Favorites", "Saved", 1, "Pinned settings")
		F.section.nofav = true
		F.gallery = UI.gallery("Favorites", "Saved", 2, {
			Name = "Pinned items",
			Cell = 70,
			Height = 300,
			Reset = true,
			Empty = "",
			Callback = function(key)
				local rec = key and K.favItems[key]
				local gal = rec and galleryByPath[rec.gal]
				if gal then
					gal.set(rec.item)
					notify(tostring(rec.label or rec.item))
				end
			end,
		})
		local _, sub = findSub("Favorites", "Saved")
		F.hint = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.45),
			Size = UDim2.fromOffset(320, 56),
			BackgroundTransparency = 1,
			Visible = false,
		}, sub.page)
		K.glyph(F.hint, "star", 22, C.faint, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0) })
		K.text(F.hint, {
			Position = UDim2.fromOffset(0, 34),
			Size = UDim2.new(1, 0, 0, 18),
			Text = "No favorites yet",
			TextSize = 13,
			TextColor3 = C.sub,
			TextXAlignment = Enum.TextXAlignment.Center,
		})
	end
	for _, key in ipairs(F.built) do
		registry[key] = nil
		bindables[key] = nil
	end
	table.clear(F.built)
	for _, child in ipairs(F.section.body:GetChildren()) do
		if child:IsA("GuiObject") then child:Destroy() end
	end
	K.rowOrders[F.section.body] = 0

	local paths = {}
	for path in pairs(K.favs) do paths[#paths + 1] = path end
	table.sort(paths)
	local used, shown = {}, 0
	for _, path in ipairs(paths) do
		local spec, item = K.favSpecs[path], registry[path]
		if spec and (item or spec.kind == "button") then
			local label, n = spec.label, 2
			while used[label] do
				label = spec.label .. " " .. n
				n += 1
			end
			used[label] = true
			shown += 1
			F.built[#F.built + 1] = F.section.path .. "/" .. label
			local kind = spec.kind
			if kind == "toggle" or kind == "switch" then
				F.section:toggle(label, item.get() == true, function(v) item.set(v) end)
			elseif kind == "slider" then
				F.section:slider(label, spec.min, spec.max, tonumber(item.get()) or spec.min, function(v) item.set(v) end, spec.suffix, spec.step)
			elseif kind == "dropdown" then
				F.section:dropdown(label, spec.options, item.get(), function(v) item.set(v) end)
			elseif kind == "multi" then
				F.section:multi(label, spec.options, item.get(), function(v) item.set(v) end)
			elseif kind == "color" then
				F.section:color(label, item.get(), function(v) item.set(v) end)
			elseif kind == "keybind" then
				F.section:keybind(label, item.get(), function(v) item.set(v) end)
			elseif kind == "button" then
				F.section:button(label, spec.press)
			else
				shown -= 1
				F.built[#F.built] = nil
			end
		end
	end
	F.section.card.Visible = shown > 0

	local list = {}
	for key, rec in pairs(K.favItems) do
		local src = galleryByPath[rec.gal]
		local art = src and src.art and src.art(rec.item) or nil
		list[#list + 1] = { name = key, label = rec.label or rec.item, art = art }
	end
	table.sort(list, function(a, b) return a.label < b.label end)
	F.gallery.setdata(list)
	F.gallery.frame.Visible = #list > 0
	F.hint.Visible = shown == 0 and #list == 0
end

-- ------------------------------------------------------------------ configs --
local currentConfig = "config"

function K.listConfigs()
	local names = {}
	local ok, files = pcall(listfiles, K.CONFIG_DIR)
	if ok and type(files) == "table" then
		for _, file in ipairs(files) do
			local name = tostring(file):match("([^/\\]+)%" .. K.CONFIG_EXT .. "$")
			if name then names[#names + 1] = name end
		end
	end
	table.sort(names)
	return names
end

function K.snapshot()
	local values = {}
	for key, control in pairs(registry) do
		if not control.secret then values[key] = control.get() end
	end
	local subs = {}
	for _, tab in ipairs(tabs) do subs[tab.name] = tab.active end
	local keys, modes = {}, {}
	for path, control in pairs(bindables) do
		if not control.secret then
			keys[path] = control.bindKey
			if control.isToggle and control.bindMode == "hold" then modes[path] = "hold" end
		end
	end
	return HttpService:JSONEncode({
		store = K.extraSave and K.extraSave() or nil,
		values = values,
		binds = keys,
		bindModes = modes,
		tab = current and current.name,
		subs = subs,
		size = { root.Size.X.Offset, root.Size.Y.Offset },
	})
end

function K.applyConfig(data)
	local keyed, moded = {}, {}
	for path, key in pairs(type(data.binds) == "table" and data.binds or {}) do keyed[path] = key end
	for path, mode in pairs(type(data.bindModes) == "table" and data.bindModes or {}) do moded[path] = mode end
	for path, control in pairs(bindables) do
		if control.secret then continue end
		K.releaseHold(control)
		local mode = moded[path]
		control.bindMode = control.isToggle and mode == "hold" and "hold" or "toggle"
		local key = keyed[path]
		K.assignBind(control, type(key) == "string" and key or nil)
	end
	local values = type(data.values) == "table" and data.values or {}
	-- the palette first: it is where the colour cards start from
	local PALETTE = "Settings/Theme/Presets/Palette"
	if registry[PALETTE] and values[PALETTE] ~= nil then pcall(registry[PALETTE].set, values[PALETTE]) end
	for key, value in pairs(values) do
		if key ~= PALETTE then
			local control = registry[key]
			if control then pcall(control.set, value) end
		end
	end
	if K.extraLoad and data.store ~= nil then pcall(K.extraLoad, data.store) end
	for _, tab in ipairs(tabs) do
		local index = type(data.subs) == "table" and tonumber(data.subs[tab.name])
		if index and tab.subs[index] then tab.active = index end
	end
	if type(data.size) == "table" and not MOBILE then
		local w, h = tonumber(data.size[1]), tonumber(data.size[2])
		if w and h then
			K.desired = Vector2.new(math.max(w, L.MINW), math.max(h, L.MINH))
			K.fitRoot()
		end
	end
end

function K.remember(name)
	currentConfig = name
	pcall(writefile, ROOT .. "/last.txt", name)
	if K.paintStatus then K.paintStatus() end
end

function K.saveConfig(name)
	K.ensureFolders()
	local ok = pcall(function() writefile(K.CONFIG_DIR .. "/" .. name .. K.CONFIG_EXT, K.snapshot()) end)
	if ok then K.remember(name) end
	return ok
end

local function loadConfig(name)
	local ok, data = pcall(function()
		return HttpService:JSONDecode(readfile(K.CONFIG_DIR .. "/" .. name .. K.CONFIG_EXT))
	end)
	if not ok or type(data) ~= "table" then return false end
	K.remember(name)
	K.applyConfig(data)
	return true
end
UI.save = K.saveConfig
UI.load = loadConfig
K.currentConfig = function() return currentConfig end

-- the configs open in the sheet: the list, a field for a new one, codes
do
	local body = new("Frame", {
		Name = "Configs",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
	}, K.attic)
	pad(body, 4, 18, 18, 18)
	new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, body)
	local selected
	local function caption(text, order)
		local o = K.text(body, {
			LayoutOrder = order,
			Size = UDim2.new(1, 0, 0, 34),
			FontFace = K.face.semi,
			Text = text,
			TextSize = 12,
			TextColor3 = C.sub,
			TextYAlignment = Enum.TextYAlignment.Bottom,
		})
		pad(o, 0, 8, 0, 0)
		return o
	end
	local function fill()
		for _, child in ipairs(body:GetChildren()) do
			if child:IsA("GuiObject") then child:Destroy() end
		end
		caption("Saved", 1)
		local names = K.listConfigs()
		if not table.find(names, selected) then selected = table.find(names, currentConfig) and currentConfig or names[1] end
		for i, name in ipairs(names) do
			local active = name == currentConfig
			local chosen = name == selected
			local row = new("TextButton", {
				LayoutOrder = 1 + i,
				Size = UDim2.new(1, 0, 0, MOBILE and 42 or 38),
				BackgroundColor3 = C.field,
				BackgroundTransparency = chosen and 0 or 1,
				AutoButtonColor = false,
				Text = "",
			}, body)
			corner(row, 8)
			local mark = new("Frame", {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, 12, 0.5, 0),
				Size = UDim2.fromOffset(6, 6),
				BackgroundColor3 = active and C.accent or C.chip,
				BorderSizePixel = 0,
			}, row)
			corner(mark, "full")
			local label = K.text(row, {
				Position = UDim2.fromOffset(28, 0),
				Size = UDim2.new(1, -40, 1, 0),
				FontFace = chosen and K.face.semi or K.face.medium,
				Text = name,
				TextColor3 = chosen and C.text or C.value,
			})
			row.MouseEnter:Connect(function()
				tween(label, 0.15, { TextColor3 = C.text })
				if not chosen then tween(row, 0.15, { BackgroundTransparency = 0.5 }) end
			end)
			row.MouseLeave:Connect(function()
				tween(label, 0.2, { TextColor3 = chosen and C.text or C.value })
				if not chosen then tween(row, 0.2, { BackgroundTransparency = 1 }) end
			end)
			row.MouseButton1Click:Connect(function()
				selected = name
				SFX.click()
				fill()
			end)
		end
		if #names == 0 then
			K.text(body, {
				LayoutOrder = 2,
				Size = UDim2.new(1, 0, 0, 30),
				Text = "Nothing saved",
				TextColor3 = C.faint,
			})
		end
		local function action(parent, text, order, total, fn)
			local button = new("TextButton", {
				LayoutOrder = order, Size = UDim2.new(1 / total, -8 * (total - 1) / total, 1, 0),
				BackgroundColor3 = C.field, AutoButtonColor = false, FontFace = K.face.medium,
				Text = text, TextSize = 13, TextColor3 = C.value,
			}, parent)
			corner(button, 8)
			K.sheen(button, 0.82)
			button.MouseEnter:Connect(function() tween(button, 0.15, { BackgroundColor3 = C.hover, TextColor3 = C.text }) end)
			button.MouseLeave:Connect(function() tween(button, 0.2, { BackgroundColor3 = C.field, TextColor3 = C.value }) end)
			K.press(button)
			button.MouseButton1Click:Connect(function() SFX.click(); fn() end)
		end
		local function overwrite(name)
			K.confirm("Overwrite config?", name, "Overwrite", function()
				notify(K.saveConfig(name) and ("Saved <b>" .. name .. "</b>") or "Can't write files")
				fill()
			end)
		end
		local order = #names + 3
		if selected then
			local target = selected
			local actions = new("Frame", { LayoutOrder = order, Size = UDim2.new(1, 0, 0, 34), BackgroundTransparency = 1 }, body)
			new("UIListLayout", { FillDirection = Enum.FillDirection.Horizontal, SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 8) }, actions)
			action(actions, "Load", 1, 3, function()
				K.confirm("Load config?", target, "Load", function()
					notify(loadConfig(target) and ("Loaded <b>" .. target .. "</b>") or ("Can't load " .. target))
					fill()
				end)
			end)
			action(actions, "Overwrite", 2, 3, function() overwrite(target) end)
			action(actions, "Delete", 3, 3, function()
				K.confirm("Delete config?", target, "Delete", function()
					local ok = pcall(delfile, K.CONFIG_DIR .. "/" .. target .. K.CONFIG_EXT)
					if ok and currentConfig == target then
						currentConfig = "config"
						pcall(delfile, ROOT .. "/last.txt")
					end
					notify(ok and ("Deleted " .. target) or ("Can't delete " .. target))
					fill()
				end)
			end)
		end
		caption("New", order + 1)
		local line = new("Frame", { LayoutOrder = order + 2, Size = UDim2.new(1, 0, 0, 36), BackgroundTransparency = 1 }, body)
		local nameBox = new("TextBox", {
			Size = UDim2.new(1, -86, 1, 0),
			BackgroundColor3 = C.field,
			ClearTextOnFocus = false,
			FontFace = K.face.medium,
			PlaceholderText = "Name",
			PlaceholderColor3 = C.faint,
			Text = "",
			TextSize = 13,
			TextColor3 = C.text,
			TextXAlignment = Enum.TextXAlignment.Left,
		}, line)
		corner(nameBox, 8)
		local nameEdge = stroke(nameBox, C.text, 1)
		pad(nameBox, 0, 0, 12, 12)
		nameBox.Focused:Connect(function() tween(nameEdge, 0.15, { Transparency = 0.6 }) end)
		nameBox.FocusLost:Connect(function() tween(nameEdge, 0.2, { Transparency = 1 }) end)
		local save = new("TextButton", {
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.fromScale(1, 0),
			Size = UDim2.new(0, 78, 1, 0),
			BackgroundColor3 = C.accent,
			AutoButtonColor = false,
			FontFace = K.face.semi,
			Text = "Save",
			TextSize = 13,
			TextColor3 = C.onAccent,
		}, line)
		corner(save, 8)
		K.sheen(save, 0.86, true)
		K.press(save)
		local function submit()
			local name = nameBox.Text:gsub("[^%w%-_ ]", ""):gsub("^%s+", ""):gsub("%s+$", "")
			if name == "" then name = currentConfig end
			for _, saved in ipairs(names) do
				if string.lower(saved) == string.lower(name) then overwrite(saved); return end
			end
			SFX.on()
			notify(K.saveConfig(name) and ("Saved <b>" .. name .. "</b>") or "Can't write files")
			fill()
		end
		save.MouseButton1Click:Connect(submit)
		nameBox.FocusLost:Connect(function(enter) if enter then submit() end end)
	end
	K.configButton.MouseButton1Click:Connect(function()
		if K.sheetOpen(body) then K.closeSheets(true) return end
		SFX.click()
		fill()
		K.openSheet("Configs", body, { replace = true })
	end)
end

-- ------------------------------------------------------------------ search --
-- The search button grows a field across the top bar while the categories
-- fade out. Matches drop below it and re-rank as you type: settings before
-- whole pages, names that start with the words first, the typed part lit.
-- Up and down pick, Enter goes.
do
	local open, results, empty = false, nil, nil
	local hits, items, selected = {}, {}, 1
	local ITEM, W = MOBILE and 42 or 40, 400
	local function width()
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		return math.clamp(K.searchBar.AbsoluteSize.X / s, 340, 600)
	end
	local ESC = { ["&"] = "&amp;", ["<"] = "&lt;", [">"] = "&gt;" }

	local function hideResults()
		if results then
			local gone = results
			results = nil
			tween(gone, 0.12, { Position = gone.Position + UDim2.fromOffset(0, -4) })
			task.delay(0.1, function() gone:Destroy() end)
		end
		table.clear(items)
		empty = nil
	end

	local function fadeCats(show)
		if MOBILE then return end
		if show then K.cats.Visible = true end
		for _, t in ipairs(tabs) do
			if t.label then tween(t.label, show and 0.3 or 0.14, { TextTransparency = show and 0 or 1 }) end
		end
		tween(K.catPill, show and 0.3 or 0.14, { BackgroundTransparency = show and 0 or 1 })
		if not show then
			task.delay(0.15, function() if open then K.cats.Visible = false end end)
		end
	end

	-- the field runs from where the categories start to just before the tools
	local function geometry()
		local s = math.max(scaler.Scale * K.pop.Scale, 0.01)
		local x0 = K.top.AbsolutePosition.X
		local right = (K.tools.AbsolutePosition.X - x0) / s - 10
		local left = MOBILE and ((K.brand.AbsolutePosition.X + K.brand.AbsoluteSize.X - x0) / s + 14)
			or ((K.cats.AbsolutePosition.X - x0) / s)
		return right, math.max(180, right - left)
	end

	local function lit(on)
		K.searchButton:SetAttribute("Lit", on)
		local ic = K.searchButton:FindFirstChildOfClass("ImageLabel")
		if ic then tween(ic, 0.2, { ImageColor3 = on and C.text or C.sub }) end
	end

	function K.closeSearch()
		if not open then return end
		open = false
		hideResults()
		if K.searchBox:IsFocused() then K.searchBox:ReleaseFocus() end
		local bar = K.searchBar
		tween(bar, 0.26, { Size = UDim2.fromOffset(34, 34), BackgroundTransparency = 1 }, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
		tween(K.searchIcon, 0.14, { ImageTransparency = 1 })
		tween(K.searchInput.hint, 0.12, { TextTransparency = 1 })
		K.searchClear.Visible = false
		task.delay(0.27, function()
			if open then return end
			bar.Visible = false
			K.searchBox.Text = ""
		end)
		fadeCats(true)
		lit(false)
	end

	local function openSearch()
		if open then return end
		open = true
		K.closePopup()
		local right, width = geometry()
		local bar = K.searchBar
		bar.Position = UDim2.new(0, right, 0.5, 0)
		bar.Size = UDim2.fromOffset(34, 34)
		bar.BackgroundTransparency = 1
		bar.Visible = true
		K.searchIcon.ImageTransparency = 1
		K.searchInput.hint.TextTransparency = 1
		K.searchClear.Visible = false
		tween(bar, 0.5, { Size = UDim2.fromOffset(width, 34), BackgroundTransparency = 0 }, K.ease.out)
		tween(K.searchIcon, 0.3, { ImageTransparency = 0 })
		tween(K.searchInput.hint, 0.45, { TextTransparency = 0 })
		fadeCats(false)
		lit(true)
		task.defer(function() K.searchBox:CaptureFocus() end)
	end
	K.openSearch = openSearch
	local flashes = setmetatable({}, { __mode = "k" })

	local function goTo(entry)
		selectTab(entry.tab, false, entry.sub)
		K.closeSearch()
		local section = entry.section
		if section and section.revealOptions then section.revealOptions() end
		local target = entry.target or entry.card
		if not target then return end
		task.delay(0.35, function()
			if not target.Parent or not root.Visible or K.current() ~= entry.tab or entry.tab.active ~= entry.sub then return end
			local scroll = target:FindFirstAncestorWhichIsA("ScrollingFrame")
			if scroll then
				local y = target.AbsolutePosition.Y - scroll.AbsolutePosition.Y + scroll.CanvasPosition.Y - 12
				K.scrollTo(scroll, y)
			end
			local head = target:FindFirstChild("Label") or (target:FindFirstChild("Header") and target.Header:FindFirstChild("Title"))
			local flash = flashes[target]
			if not flash then
				flash = { color = target.BackgroundColor3, transparency = target.BackgroundTransparency, headColor = head and head.TextColor3, sequence = 0 }
				flashes[target] = flash
			end
			flash.sequence += 1
			local sequence = flash.sequence
			if head then
				head.TextColor3 = C.white
				tween(head, 1.4, { TextColor3 = flash.headColor })
			end
			target.BackgroundColor3, target.BackgroundTransparency = C.hover, math.min(flash.transparency, 0.2)
			tween(target, 1.2, { BackgroundColor3 = flash.color, BackgroundTransparency = flash.transparency })
			task.delay(1.45, function() if flash.sequence == sequence then flashes[target] = nil end end)
		end)
	end

	local function paintSelected()
		for i, it in ipairs(items) do
			tween(it.frame, 0.12, { BackgroundTransparency = i == selected and 0 or 1 })
		end
	end

	-- the typed part of a name, lit
	local function marked(label, query)
		local low = string.lower(label)
		local at = string.find(low, query, 1, true)
		local function esc(t) return (string.gsub(t, "[&<>]", ESC)) end
		if not at then return esc(label) end
		local stop = at + #query - 1
		return esc(string.sub(label, 1, at - 1))
			.. '<font color="#' .. C.text:ToHex() .. '"><b>' .. esc(string.sub(label, at, stop)) .. "</b></font>"
			.. esc(string.sub(label, stop + 1))
	end

	local function refresh()
		local query = string.match(string.lower(K.searchBox.Text), "^%s*(.-)%s*$") or ""
		K.searchClear.Visible = K.searchBox.Text ~= ""
		if query == "" then
			hideResults()
			return
		end
		table.clear(hits)
		local seen = {}
		local ranked = {}
		for _, entry in ipairs(K.searchIndex) do
			local label = string.lower(tostring(entry.label))
			local at = string.find(label, query, 1, true)
			local key = label .. "|" .. tostring(entry.where)
			if at and not seen[key] then
				seen[key] = true
				ranked[#ranked + 1] = { entry = entry, score = (at == 1 and 0 or 100) + (entry.card and 0 or 50) + #label }
			end
		end
		table.sort(ranked, function(a, b) return a.score < b.score end)
		for i = 1, math.min(#ranked, 8) do hits[i] = ranked[i].entry end
		selected = 1
		local count = #hits
		local height = math.max(1, count) * ITEM + 10
		if not (results and results.Parent) then W = width() end
		local box
		if results and results.Parent then
			tween(results, 0.22, { Size = UDim2.fromOffset(W, height) }, K.ease.out)
			box = results:FindFirstChild("Box")
		else
			local holder
			holder, box = K.float(W, height, 130)
			K.drop(holder, K.place(K.searchBar, Vector2.new(W, height)))
			results = holder
		end
		for _, it in ipairs(items) do it.frame:Destroy() end
		table.clear(items)
		if empty then empty:Destroy() empty = nil end
		for i, entry in ipairs(hits) do
			local item = new("TextButton", {
				Position = UDim2.fromOffset(5, 5 + (i - 1) * ITEM),
				Size = UDim2.new(1, -10, 0, ITEM),
				BackgroundColor3 = C.hover,
				BackgroundTransparency = i == selected and 0 or 1,
				AutoButtonColor = false,
				Text = "",
				ZIndex = 132,
			}, box)
			corner(item, 8)
			local name = K.text(item, {
				Position = UDim2.fromOffset(12, 0),
				Size = UDim2.new(0.45, -12, 1, 0),
				RichText = true,
				Text = marked(tostring(entry.label), query),
				TextSize = 13,
				TextColor3 = C.value,
				TextTransparency = 1,
				ZIndex = 133,
			})
			local where = K.text(item, {
				AnchorPoint = Vector2.new(1, 0),
				Position = UDim2.new(1, -12, 0, 0),
				Size = UDim2.new(0.55, -12, 1, 0),
				Text = tostring(entry.where),
				TextSize = 12,
				TextColor3 = C.faint,
				TextTransparency = 1,
				TextXAlignment = Enum.TextXAlignment.Right,
				ZIndex = 133,
			})
			tween(name, 0.18, { TextTransparency = 0 })
			tween(where, 0.24, { TextTransparency = 0 })
			item.MouseEnter:Connect(function()
				selected = i
				paintSelected()
			end)
			item.MouseButton1Click:Connect(function()
				SFX.click()
				goTo(entry)
			end)
			items[i] = { frame = item, entry = entry }
		end
		if count == 0 then
			empty = K.text(box, {
				Size = UDim2.fromScale(1, 1),
				Text = "Nothing found",
				TextSize = 13,
				TextColor3 = C.faint,
				TextXAlignment = Enum.TextXAlignment.Center,
				ZIndex = 132,
			})
		end
	end

	K.searchBox:GetPropertyChangedSignal("Text"):Connect(refresh)
	K.searchBox.FocusLost:Connect(function(enter)
		if enter and hits[selected] then goTo(hits[selected]) end
	end)
	K.searchClear.MouseButton1Click:Connect(function()
		SFX.click()
		K.searchBox.Text = ""
		task.defer(function() K.searchBox:CaptureFocus() end)
	end)
	K.searchButton.MouseButton1Click:Connect(function()
		SFX.click()
		if open then K.closeSearch() else openSearch() end
	end)
	connectUI(UIS.InputBegan, function(input)
		if not open then return end
		if input.KeyCode == Enum.KeyCode.Down or input.KeyCode == Enum.KeyCode.Up then
			if #items == 0 then return end
			selected = math.clamp(selected + (input.KeyCode == Enum.KeyCode.Down and 1 or -1), 1, #items)
			paintSelected()
			return
		end
		if not K.isPress(input) then return end
		local p = K.pointer(input)
		if not (K.inside(results, p) or K.inside(K.searchBar, p) or K.inside(K.searchButton, p)) then
			task.defer(K.closeSearch)
		end
	end)
end

-- ====================================================================== 40_app.lua
-- ------------------------------------------------------- opening, closing --
local isOpen = false
K.menuKey = Enum.KeyCode.LeftControl

-- open: the whole window fades in as it grows from 94% and rises into
-- place, the shadow blooming under it; close: it fades and sinks a little.
-- During the motion main rides in a CanvasGroup, after it main is put back.
local function setOpen(open, quiet)
	if K.unloaded then return end
	if isOpen == open then return end
	isOpen = open
	K.glass.open = open
	K.closeAll()
	if K.pendingBind then
		K.pendingBind.listening = false
		K.pendingBind.paintBind()
		K.pendingBind = nil
	end
	local pop, shell, shadow, fade, veil = K.pop, K.shell, K.windowShadow, K.fade, K.veil
	K.motion = (K.motion or 0) + 1
	local motion = K.motion
	local function settle()
		if motion ~= K.motion then return end
		if fade then
			K.main.Parent = shell
			fade.Visible = false
		end
		veil.Visible = false
	end
	if fade then
		K.main.Parent = fade
		fade.Visible = true
	end
	if open then
		K.fitRoot()
		pop.Scale = 0.94
		shell.Position = UDim2.fromOffset(0, 18)
		if fade then
			fade.GroupTransparency = 1
		else
			veil.Visible = true
			veil.BackgroundTransparency = 0
		end
		root.Visible = true
		if shadow then
			shadow.ImageTransparency = 1
			tween(shadow, 0.6, { ImageTransparency = 0.2 }, K.ease.out)
		end
		tween(pop, 0.55, { Scale = 1 }, K.ease.out)
		tween(shell, 0.55, { Position = UDim2.new() }, K.ease.out)
		if fade then
			tween(fade, 0.32, { GroupTransparency = 0 }, Enum.EasingStyle.Quad).Completed:Once(function(state)
				if state == Enum.PlaybackState.Completed then settle() end
			end)
		else
			tween(veil, 0.35, { BackgroundTransparency = 1 }, K.ease.out)
			task.delay(0.56, settle)
		end
		local tab = K.current()
		if tab then
			if tab.onOpen then pcall(tab.onOpen) end
			task.defer(function()
				K.markTab(tab, true)
				K.markSub(tab, true)
			end)
		end
	else
		if fade then
			tween(fade, 0.2, { GroupTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		else
			veil.Visible = true
			tween(veil, 0.18, { BackgroundTransparency = 0 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		end
		if shadow then tween(shadow, 0.18, { ImageTransparency = 1 }) end
		tween(shell, 0.22, { Position = UDim2.fromOffset(0, 10) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(pop, 0.22, { Scale = 0.96 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.delay(0.23, function()
			if motion ~= K.motion then return end
			root.Visible = false
			settle()
		end)
	end
	K.glass.apply(true)
	if not quiet then
		if open then SFX.on() else SFX.off() end
	end
end
K.closeButton.MouseButton1Click:Connect(function() setOpen(false) end)

function K.unload()
	if K.unloaded or env.__SaladGui ~= gui then return end
	K.unloaded = true
	local sounds = env.__SaladSounds
	K.motion = (K.motion or 0) + 1
	isOpen = false
	K.pendingBind = nil
	pcall(K.stopSlider)
	pcall(K.closeAll)
	K.glass.open = false
	K.glass.apply()
	root.Visible = false
	local cleanups = {}
	for _, key in ipairs({ "__SaladFeaturesCleanup", "__SaladOverlayCleanup" }) do
		if type(env[key]) == "function" then cleanups[#cleanups + 1] = env[key] end
		env[key] = nil
	end
	if env.__SALAD_API and env.__SALAD_API.K == K then env.__SALAD_API = nil end
	if env.__SaladSounds == sounds then env.__SaladSounds = nil end
	for _, cleanup in ipairs(cleanups) do pcall(cleanup) end
	if sounds then pcall(function() sounds:Destroy() end) end
	if env.__SaladGui == gui then env.__SaladGui = nil end
	gui:Destroy()
end

-- keys: a waiting bind takes the next key; bound keys fire; the menu key
-- opens and closes; Tab searches; Escape closes what floats
connectUI(UIS.InputBegan, function(input, processed)
	local pending = K.pendingBind
	local button = (input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.MouseButton3)
		and pending and pending.mouse and input.UserInputType.Name
	if input.UserInputType ~= Enum.UserInputType.Keyboard and not button then return end
	if pending then
		K.pendingBind = nil
		pending.listening = false
		if input.KeyCode == Enum.KeyCode.Escape then
			K.assignBind(pending, pending.bindKey)
			return
		end
		if input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete then
			K.assignBind(pending, nil)
			SFX.off()
		elseif button or input.KeyCode ~= Enum.KeyCode.Unknown then
			K.assignBind(pending, button or input.KeyCode.Name)
			SFX.on()
		end
		return
	end
	if input.KeyCode == K.menuKey and not processed then
		setOpen(not isOpen)
		return
	end
	local control = not processed and K.binds[input.KeyCode.Name]
	if control then
		if control.isToggle and control.bindMode == "hold" then
			if not control.held then
				control.held = true
				registry[control.path].set(true)
			end
		else
			control.trigger()
		end
	end
	if isOpen and input.KeyCode == Enum.KeyCode.Escape then K.closeAll() end
	if not processed and isOpen and input.KeyCode == Enum.KeyCode.Tab and K.openSearch then
		K.openSearch()
	end
end)

connectUI(UIS.InputEnded, function(input)
	if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
	local control = K.binds[input.KeyCode.Name]
	if control and control.isToggle and control.bindMode == "hold" then K.releaseHold(control) end
end)

-- a phone opens the menu from a small dark tile with the mark; drag it to
-- either side
if MOBILE then
	local button = new("TextButton", {
		Name = "Launcher",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0, 36, 0.5, 0),
		Size = UDim2.fromOffset(46, 46),
		BackgroundColor3 = C.window,
		BackgroundTransparency = 0.02,
		AutoButtonColor = false,
		Text = "",
		ZIndex = 300,
	}, gui)
	corner(button, 14)
	stroke(button, C.border, 0)
	K.shadow(button, 16, 0.4, 299)
	K.logo(button, 22, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		ZIndex = 301,
	})
	local scale = new("UIScale", { Scale = math.clamp(baseScale, 0.8, 1) }, button)
	local touch, start, origin, moved
	button.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
			touch, start, origin, moved = input, input.Position, button.Position, false
			tween(scale, 0.12, { Scale = math.clamp(baseScale, 0.8, 1) * 0.92 })
		end
	end)
	connectUI(UIS.InputChanged, function(input)
		if not touch or (input ~= touch and input.UserInputType ~= Enum.UserInputType.MouseMovement) then return end
		local d = input.Position - start
		if d.Magnitude > 8 then moved = true end
		if moved then
			button.Position = UDim2.new(origin.X.Scale, origin.X.Offset + d.X, origin.Y.Scale, origin.Y.Offset + d.Y)
		end
	end)
	connectUI(UIS.InputEnded, function(input)
		if not touch or (input ~= touch and input.UserInputType ~= Enum.UserInputType.MouseButton1) then return end
		touch = nil
		tween(scale, 0.3, { Scale = math.clamp(baseScale, 0.8, 1) }, K.ease.spring)
		if not moved then
			setOpen(not isOpen)
			return
		end
		local view = K.view()
		local at = button.AbsolutePosition + button.AbsoluteSize / 2
		local left = at.X < view.X / 2
		local y = math.clamp(at.Y, 40, view.Y - 40)
		tween(button, 0.45, { Position = UDim2.fromOffset(left and 36 or view.X - 36, y) }, K.ease.out)
	end)
	K.launcher = button
end

-- --------------------------------------------------------------- settings --
-- ------------------------------------------------------------------- theme --
-- Recolouring goes by value: whatever wears a key's old colour takes its new
-- one (the palette ladder keeps every key's colour distinct). Pieces drawn
-- later by code that captured a colour at load are translated from the
-- load-time palette as they appear. The font swaps the same way, by family.
do
	local PROPS = {
		{ "GuiObject", "BackgroundColor3" },
		{ "TextLabel", "TextColor3" }, { "TextButton", "TextColor3" }, { "TextBox", "TextColor3" },
		{ "TextBox", "PlaceholderColor3" },
		{ "ImageLabel", "ImageColor3" }, { "ImageButton", "ImageColor3" },
		{ "ScrollingFrame", "ScrollBarImageColor3" },
		{ "UIStroke", "Color" },
	}
	local byClass = {}
	local function propsOf(o)
		local list = byClass[o.ClassName]
		if not list then
			list = {}
			for _, pr in ipairs(PROPS) do
				if o:IsA(pr[1]) then list[#list + 1] = pr[2] end
			end
			byClass[o.ClassName] = list
		end
		return list
	end
	local function id(c)
		return math.floor(c.R * 255 + 0.5) * 65536 + math.floor(c.G * 255 + 0.5) * 256 + math.floor(c.B * 255 + 0.5)
	end
	local function mapOf(palette)
		local map = {}
		for _, key in ipairs(THEME.keys) do map[id(palette[key])] = key end
		return map
	end
	local function recolor(o, map)
		for _, prop in ipairs(propsOf(o)) do
			local v = o[prop]
			local key = map[id(v)]
			if key and C[key] ~= v then o[prop] = C[key] end
		end
	end
	local function isText(o)
		return o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox")
	end
	local function refont(o, from, to)
		if isText(o) then
			local f = o.FontFace
			if f.Family == from then o.FontFace = Font.new(to, f.Weight, f.Style) end
		end
	end

	-- later pieces: only once the look differs from what the features know
	local bootMap = mapOf(THEME.boot)
	local hook
	local function changed()
		for _, key in ipairs(THEME.keys) do
			if C[key] ~= THEME.boot[key] then return true end
		end
		return K.face.medium.Family ~= K.fonts.boot
	end
	local function watch()
		if hook or not changed() then return end
		hook = connectUI(gui.DescendantAdded, function(o)
			task.defer(function()
				if not o.Parent then return end
				recolor(o, bootMap)
				refont(o, K.fonts.boot, K.face.medium.Family)
			end)
		end)
	end

	local function sync()
		THEME.alias()
		if K.repaintOverlay then pcall(K.repaintOverlay) end
	end

	-- a whole palette at once (a preset)
	function K.applyPalette(palette)
		local from = {}
		for _, key in ipairs(THEME.keys) do from[key] = C[key] end
		local map = mapOf(from)
		for _, key in ipairs(THEME.keys) do
			if palette[key] then C[key] = palette[key] end
		end
		for _, o in ipairs(gui:GetDescendants()) do recolor(o, map) end
		sync()
		watch()
		for key, control in pairs(K.themeControls or {}) do
			if control.get() ~= C[key] then control.set(C[key]) end
		end
	end

	-- one colour from its card; a burst (a config) settles in one pass
	local pending
	function K.setThemeColor(key, color)
		if typeof(color) ~= "Color3" then return end
		color = THEME.rgb(color)
		if C[key] == color and not (pending and pending[key]) then return end
		if not pending then
			pending = {}
			task.defer(function()
				local batch = pending
				pending = nil
				local palette = {}
				for k, v in pairs(batch) do palette[k] = v end
				K.applyPalette(palette)
			end)
		end
		pending[key] = color
	end

	function K.applyPreset(name)
		local palette = THEME.presets[name]
		if palette then K.applyPalette(palette) end
	end

	-- every piece of text keeps the size it was made with as an attribute and
	-- is drawn at that times the factor; later text is caught as it appears
	local textFactor, textHook = 1, nil
	local function sizeText(o)
		if not isText(o) then return end
		local base = o:GetAttribute("BaseTextSize")
		if not base then
			base = o.TextSize
			o:SetAttribute("BaseTextSize", base)
		end
		local want = base * textFactor
		if o.TextSize ~= want then o.TextSize = want end
	end
	function K.setTextScale(f)
		textFactor = tonumber(f) or 1
		for _, o in ipairs(gui:GetDescendants()) do sizeText(o) end
		if not textHook and f ~= 1 then
			textHook = connectUI(gui.DescendantAdded, function(o)
				task.defer(function() if o.Parent then sizeText(o) end end)
			end)
		end
	end

	function K.setFont(name)
		local family = K.fonts.family[name]
		if not family then return end
		local from = K.face.medium.Family
		if from == family then return end
		K.face = K.facesOf(family)
		for _, o in ipairs(gui:GetDescendants()) do refont(o, from, family) end
		watch()
		if K.current() then
			task.delay(0.15, function()
				local tab = K.current()
				if tab then K.markTab(tab, true); K.markSub(tab, true) end
			end)
		end
	end
end

local function initThemes()
	local sec = UI.section("Settings", "Menu", 1, "Menu")
	-- sizes come as presets: the menu as a whole, and the text on its own
	local SIZES = { Small = 0.86, Normal = 1, Large = 1.14, Huge = 1.28 }
	sec:dropdown("Menu Size", { "Small", "Normal", "Large", "Huge" }, "Normal", function(name)
		K.setMenuScale((K.autoScale or 1) * (SIZES[name] or 1))
	end)
	local TEXT = { Small = 0.92, Normal = 1, Large = 1.12, Huge = 1.24 }
	sec:dropdown("Text Size", { "Small", "Normal", "Large", "Huge" }, "Normal", function(name)
		K.setTextScale(TEXT[name] or 1)
	end)
	if not MOBILE then
		sec:dropdown("Menu Key", { "LeftControl", "RightControl", "RightShift", "Insert", "Home", "End" }, "LeftControl", function(name)
			K.menuKey = Enum.KeyCode[name] or Enum.KeyCode.LeftControl
		end)
	end
	sec:slider("Window Opacity", 70, 100, 100, function(v)
		K.main.BackgroundTransparency = 1 - v / 100
	end, "%", 1)
	sec:toggle("Blur Background", false, function(v)
		K.glass.blurEnabled = v
		K.glass.apply(true)
	end)
	sec:slider("Blur Amount", 0, 24, K.glass.blur, function(v)
		K.glass.blur = v
		K.glass.apply()
	end, "", 1)
	sec:slider("Dim Background", 0, 80, math.floor(K.glass.dim * 100 + 0.5), function(v)
		K.glass.dim = v / 100
		K.glass.apply()
	end, "%", 1)
	sec:button("Unload", K.unload)

	-- the look: a preset to start from, the type, and every colour on its own
	local presets = UI.section("Settings", "Theme", 1, "Presets")
	presets:dropdown("Palette", THEME.order, "Onyx", function(name) K.applyPreset(name) end)
	presets:dropdown("Font", K.fonts.order, "Inter", function(name) K.setFont(name) end)
	presets:button("Reset Colors", function()
		local item = registry["Settings/Theme/Presets/Palette"]
		if item then item.set("Onyx") else K.applyPreset("Onyx") end
	end)
	local colors = UI.section("Settings", "Theme", 2, "Colors")
	K.themeControls = {}
	for _, spec in ipairs({
		{ "Background", "window" }, { "Cards", "card" }, { "Panels", "panel" }, { "Fields", "field" },
		{ "Hover", "hover" }, { "Chips", "chip" }, { "Lines", "line" }, { "Borders", "border" },
		{ "Tracks", "track" }, { "Knobs", "knob" }, { "Text", "text" }, { "Labels", "value" },
		{ "Muted", "sub" }, { "Faint", "faint" }, { "Icons", "icon" }, { "Accent", "accent" },
		{ "On Accent", "onAccent" },
	}) do
		local key = spec[2]
		K.themeControls[key] = colors:color(spec[1], C[key], function(c) K.setThemeColor(key, c) end)
	end
end

-- The watermark and the hotkey list:
-- small glass plates (the panel colour, a soft edge, a faint wash from the
-- top, a thin gloss line). The watermark sits top right - the SALAD mark,
-- then your face, name, frame rate, ping and time; the hotkeys sit at the
-- left edge - a switch you can flip, the name and the key. Both drag, both
-- fade in and out as a whole.
local function initOverlay()
	local Stats = game:GetService("Stats")
	local connections = {}
	local painters = {}

	local function draggable(hit, target)
		local dragging, start, position
		connections[#connections + 1] = hit.InputBegan:Connect(function(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
			dragging, start, position = input, input.Position, target.Position
		end)
		connections[#connections + 1] = UIS.InputChanged:Connect(function(input)
			if not dragging then return end
			if input ~= dragging and input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
			local delta = input.Position - start
			target.Position = UDim2.new(position.X.Scale, position.X.Offset + delta.X, position.Y.Scale, position.Y.Offset + delta.Y)
		end)
		connections[#connections + 1] = UIS.InputEnded:Connect(function(input)
			if input == dragging or input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = nil end
		end)
	end

	local function holder(name, props)
		local g = new("CanvasGroup", {
			Name = name,
			Size = UDim2.fromOffset(0, 0),
			AutomaticSize = Enum.AutomaticSize.XY,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			GroupTransparency = 1,
			Visible = false,
			ZIndex = 150,
		}, gui)
		for k, v in pairs(props) do g[k] = v end
		pad(g, 10, 10, 10, 10)
		local s = new("UIScale", { Scale = baseScale * 0.92 }, g)
		s:SetAttribute("Follow", 0.92)
		followScale[#followScale + 1] = s
		return g
	end

	-- a gradient that fades a frame along `rotation`
	local function wash(o, rotation, points)
		local seq = {}
		for i, p in ipairs(points) do seq[i] = NumberSequenceKeypoint.new(p[1], p[2]) end
		new("UIGradient", { Rotation = rotation, Transparency = NumberSequence.new(seq) }, o)
	end

	-- the glass plate; `padX`/`gap` lay its contents in a centred row
	local function plate(parent, order, padX, gap, size)
		local card = new("Frame", {
			Size = size or UDim2.fromOffset(0, 30),
			AutomaticSize = size and Enum.AutomaticSize.None or Enum.AutomaticSize.X,
			BackgroundColor3 = C.panel,
			BackgroundTransparency = 0.16,
			BorderSizePixel = 0,
			LayoutOrder = order,
			ZIndex = 2,
		}, parent)
		corner(card, 8)
		local edge = stroke(card, C.border, 0.45)
		local skin = new("Frame", {
			Size = UDim2.fromScale(1, 1),
			BackgroundColor3 = C.text,
			BackgroundTransparency = 0.82,
			BorderSizePixel = 0,
			ZIndex = 2,
		}, card)
		corner(skin, 8)
		wash(skin, 90, { { 0, 0.5 }, { 0.6, 0.82 }, { 1, 0.9 } })
		local gloss = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, 1),
			Size = UDim2.new(1, -14, 0, 1),
			BackgroundColor3 = C.text,
			BackgroundTransparency = 0.7,
			BorderSizePixel = 0,
			ZIndex = 3,
		}, card)
		wash(gloss, 0, { { 0, 1 }, { 0.5, 0.1 }, { 1, 1 } })
		local hold = new("Frame", {
			Size = size and UDim2.fromScale(1, 1) or UDim2.fromOffset(0, 30),
			AutomaticSize = size and Enum.AutomaticSize.None or Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			ZIndex = 3,
		}, card)
		if padX then pad(hold, 0, 0, padX, padX) end
		if gap then
			new("UIListLayout", {
				FillDirection = Enum.FillDirection.Horizontal,
				HorizontalAlignment = Enum.HorizontalAlignment.Center,
				VerticalAlignment = Enum.VerticalAlignment.Center,
				SortOrder = Enum.SortOrder.LayoutOrder,
				Padding = UDim.new(0, gap),
			}, hold)
		end
		painters[#painters + 1] = function()
			card.BackgroundColor3 = C.panel
			edge.Color = C.border
			skin.BackgroundColor3 = C.text
			gloss.BackgroundColor3 = C.text
		end
		return card, hold
	end

	local function label(parent, order, text, color, width)
		return K.text(parent, {
			LayoutOrder = order,
			Size = UDim2.fromOffset(width or 0, 20),
			AutomaticSize = width and Enum.AutomaticSize.None or Enum.AutomaticSize.X,
			Text = text,
			TextSize = 14,
			TextColor3 = color or C.text,
			TextTransparency = 0.05,
			TextTruncate = Enum.TextTruncate.None,
			ZIndex = 4,
		})
	end

	local function fadeTo(g, on)
		if on then g.Visible = true end
		tween(g, on and 0.3 or 0.22, { GroupTransparency = on and 0 or 1 }, on and K.ease.out or Enum.EasingStyle.Quad,
			on and Enum.EasingDirection.Out or Enum.EasingDirection.In).Completed:Connect(function(state)
			if state == Enum.PlaybackState.Completed and not on then g.Visible = false end
		end)
	end

	-- ------------------------------------------------------------ watermark
	-- under Roblox's own top bar, so it never sits on the game's buttons
	local nest = holder("SaladWatermark", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, -8, 0, K.topInset() + 2),
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 8),
	}, nest)

	local badge, badgeHold = plate(nest, 1, 12, 8)
	draggable(badge, nest)
	if K.art.logo then
		K.brushmark(badgeHold, 20, { LayoutOrder = 1, ZIndex = 4 })
	else
		label(badgeHold, 1, "salad")
	end

	local stat, statHold = plate(nest, 2, 13, 8)
	draggable(stat, nest)
	local face = new("ImageLabel", {
		LayoutOrder = 10,
		Size = UDim2.fromOffset(22, 22),
		BackgroundColor3 = C.window,
		BackgroundTransparency = 0.3,
		BorderSizePixel = 0,
		Image = string.format("rbxthumb://type=AvatarHeadShot&id=%d&w=150&h=150", LP.UserId),
		ScaleType = Enum.ScaleType.Crop,
		ZIndex = 4,
	}, statHold)
	corner(face, "full")
	local faceEdge = stroke(face, C.border, 0.35)
	local who = label(statHold, 20, LP.Name)
	local function chip(order, icon, width)
		local rail = new("Frame", { LayoutOrder = order, Size = UDim2.fromOffset(14, 16), BackgroundTransparency = 1, ZIndex = 4 }, statHold)
		local line = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(1, 16),
			BackgroundColor3 = C.text,
			BackgroundTransparency = 0.62,
			BorderSizePixel = 0,
			ZIndex = 4,
		}, rail)
		wash(line, 90, { { 0, 0.85 }, { 0.5, 0 }, { 1, 0.85 } })
		local art = K.glyph(statHold, icon, 15, C.text, { LayoutOrder = order + 1, ImageTransparency = 0.25, ZIndex = 4 })
		local text = label(statHold, order + 2, "", C.text, width)
		painters[#painters + 1] = function()
			line.BackgroundColor3 = C.text
			art.ImageColor3 = C.text
			text.TextColor3 = C.text
		end
		return text
	end
	local fps = chip(30, "layers", 30)
	local ping = chip(40, "wifi", 46)
	local clock = chip(50, "clock", 40)
	painters[#painters + 1] = function()
		faceEdge.Color = C.border
		face.BackgroundColor3 = C.window
		who.TextColor3 = C.text
	end

	-- ------------------------------------------------------------- hotkeys
	local hutch = holder("SaladKeybinds", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 8, 0.5, 0),
	})
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Vertical,
		HorizontalAlignment = Enum.HorizontalAlignment.Left,
		SortOrder = Enum.SortOrder.LayoutOrder,
		Padding = UDim.new(0, 3),
	}, hutch)
	local crown, crownHold = plate(hutch, 0, 14, 8, UDim2.fromOffset(120, 36))
	local crownArt = K.glyph(crownHold, "keyboard", 17, C.sub, { LayoutOrder = 1, ZIndex = 4 })
	local crownText = label(crownHold, 2, "hotkeys")
	draggable(crown, hutch)
	painters[#painters + 1] = function()
		crownArt.ImageColor3 = C.sub
		crownText.TextColor3 = C.text
	end

	local rows = {}
	local listEnabled, markEnabled = true, true
	local shownKeys, shownMark = false, false

	-- the crown is as wide as the widest row
	local function crest()
		task.defer(function()
			local s = math.max(hutch:FindFirstChildOfClass("UIScale").Scale, 0.01)
			local wide = 120
			for _, r in pairs(rows) do
				if r.row.Parent then wide = math.max(wide, r.row.AbsoluteSize.X / s) end
			end
			tween(crown, 0.3, { Size = UDim2.fromOffset(math.floor(wide + 0.5), 36) }, K.ease.out)
		end)
	end

	local function knob(r, on, instant)
		if r.on == on then return end
		r.on = on
		local goalRail = { BackgroundColor3 = on and C.accent or C.window }
		local goalBead = {
			Position = UDim2.new(on and 0.68 or 0.32, 0, 0.5, 0),
			BackgroundColor3 = on and C.window or C.white,
			BackgroundTransparency = on and 0 or 0.45,
		}
		if instant then
			for k, v in pairs(goalRail) do r.rail[k] = v end
			for k, v in pairs(goalBead) do r.bead[k] = v end
		else
			tween(r.rail, 0.25, goalRail, K.ease.out)
			tween(r.bead, 0.25, goalBead, K.ease.out)
		end
	end

	local function makeRow(path, spec)
		local r = { path = path }
		r.row = new("CanvasGroup", {
			Size = UDim2.fromOffset(0, 36),
			AutomaticSize = Enum.AutomaticSize.X,
			BackgroundTransparency = 1,
			GroupTransparency = 1,
			ZIndex = 2,
		}, hutch)
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			SortOrder = Enum.SortOrder.LayoutOrder,
			Padding = UDim.new(0, 5),
		}, r.row)
		pad(r.row, 2, 2, 2, 2)
		local tumb = plate(r.row, 1, nil, nil, UDim2.fromOffset(32, 32))
		r.rail = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromOffset(24, 13),
			BackgroundColor3 = C.window,
			BorderSizePixel = 0,
			ZIndex = 4,
		}, tumb)
		corner(r.rail, "full")
		r.bead = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.32, 0, 0.5, 0),
			Size = UDim2.fromOffset(9, 9),
			BackgroundColor3 = C.white,
			BackgroundTransparency = 0.45,
			BorderSizePixel = 0,
			ZIndex = 5,
		}, r.rail)
		corner(r.bead, "full")
		local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 6 }, tumb)
		connections[#connections + 1] = hit.MouseButton1Click:Connect(function()
			local item = registry[path]
			if item and type(item.get()) == "boolean" then
				item.set(not item.get())
				SFX.click()
			end
		end)
		local info, infoHold = plate(r.row, 2, 14, 10)
		info.Size = UDim2.fromOffset(0, 32)
		infoHold.Size = UDim2.fromOffset(0, 32)
		r.name = label(infoHold, 1, spec.name)
		local cue, cueHold = plate(r.row, 3, 12, 0)
		cue.Size = UDim2.fromOffset(32, 32)
		cueHold.Size = UDim2.fromOffset(0, 32)
		r.key = label(cueHold, 1, spec.key, C.accent)
		r.key.TextTransparency = 0.1
		painters[#painters + 1] = function()
			if not r.row.Parent then return end
			r.name.TextColor3 = C.text
			r.key.TextColor3 = C.accent
			local on = r.on
			r.on = nil
			knob(r, on, true)
		end
		knob(r, spec.lit == true, true)
		tween(r.row, 0.28, { GroupTransparency = 0 }, K.ease.out)
		return r
	end

	local function showKeys(want)
		want = want and listEnabled
		if want == shownKeys then return end
		shownKeys = want
		fadeTo(hutch, want)
	end

	refreshKeyList = function()
		if not hutch.Parent then return end
		local list = {}
		for path, control in pairs(bindables) do
			if control.bindKey and not control.unlisted then
				local item = registry[path]
				local lit
				if control.lit then
					lit = control.lit()
				elseif item then
					local v = item.get()
					if type(v) == "boolean" then lit = v end
				end
				list[#list + 1] = { path = path, name = nice(control.listLabel or control.label), key = control.bindKey, lit = lit }
			end
		end
		table.sort(list, function(a, b) return a.name < b.name end)
		local seen = {}
		for index, spec in ipairs(list) do
			seen[spec.path] = true
			local r = rows[spec.path]
			if not r then
				r = makeRow(spec.path, spec)
				rows[spec.path] = r
			end
			r.row.LayoutOrder = index
			r.name.Text = spec.name
			r.key.Text = spec.key
			knob(r, spec.lit == true)
		end
		for path, r in pairs(rows) do
			if not seen[path] then
				rows[path] = nil
				local gone = r.row
				tween(gone, 0.22, { GroupTransparency = 1 }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
				task.delay(0.23, function() gone:Destroy() end)
			end
		end
		crest()
		showKeys(#list > 0)
	end

	local function showMark(want)
		want = want and markEnabled
		if want == shownMark then return end
		shownMark = want
		fadeTo(nest, want)
	end

	local hud = UI.section("Settings", "Menu", 2, "HUD")
	hud:toggle("Watermark", true, function(v)
		markEnabled = v
		shownMark = not v
		showMark(v)
	end)
	hud:toggle("Keybind List", true, function(v)
		listEnabled = v
		shownKeys = not v
		refreshKeyList()
	end)
	showMark(true)
	refreshKeyList()

	local links = UI.section("Settings", "Menu", 2, "Links")
	for _, link in ipairs({ { "Telegram", "https://t.me/yanderovisual" }, { "TikTok", "https://www.tiktok.com/@yanderovs" } }) do
		links:button(link[1], function()
			local copied = pcall(setclipboard or toclipboard, link[2])
			notify(copied and (link[1] .. " link copied") or link[2])
		end)
	end

	-- the theme page repaints these by hand too: their tints are not menu keys
	function K.repaintOverlay()
		for _, paint in ipairs(painters) do pcall(paint) end
	end

	-- the status line is gone; configs still call this when they change
	function K.paintStatus() end
	local frames, elapsed = 0, 0
	connections[#connections + 1] = K.RS.RenderStepped:Connect(function(dt)
		frames += 1
		elapsed += dt
		if elapsed < 0.5 then return end
		local rate = math.floor(frames / elapsed + 0.5)
		frames, elapsed = 0, 0
		if not nest.Visible then return end
		local ok, ms = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
		local name = K.watermarkName or LP.Name
		if who.Text ~= name then who.Text = name end
		fps.Text = tostring(rate)
		ping.Text = (ok and math.floor(ms + 0.5) or 0) .. "ms"
		clock.Text = os.date("%H:%M")
	end)
	clock.Text = os.date("%H:%M")
	env.__SaladOverlayCleanup = function()
		for _, conn in ipairs(connections) do pcall(function() conn:Disconnect() end) end
		refreshKeyList = nil
	end
end

-- after every feature is built: the last config, the favourites, the first
-- category, and the window opens
function K.boot()
	local ok, name = pcall(readfile, ROOT .. "/last.txt")
	if ok and type(name) == "string" and name ~= "" then
		currentConfig = name
		loadConfig(name)
	end
	pcall(loadFavs)
	pcall(rebuildFavs)
	selectTab(tabs[1], true, 1)
	for _, t in ipairs(tabs) do paintTab(t, false) end
	if K.paintStatus then K.paintStatus() end
	setOpen(not K.silentBoot, true)
	task.delay(0.12, function()
		if K.unloaded then return end
		local tab = K.current()
		if tab then K.markTab(tab, true); K.markSub(tab, true) end
	end)
	getgenv().__SALAD_API = {
		UI = UI,
		C = C,
		K = K,
		LP = LP,
		notify = notify,
		new = new,
		env = env,
		registry = registry,
	}
end

-- ====================================================================== adapter
-- Kicia's pages call AddTab / AddSection / AddToggle ...; this answers them
-- with the menu's cards and rows. Every row shows store:Get(path), follows
-- store:Changed(path) and writes store:Set(path, v), as Kicia's window did.
UI.kicia = (function()
	local store, persistence, stateObj, stateData, colorAnim, onUnload, kicia

	-- a signal with Kicia's shape: Connect(fn) -> { Disconnect }, Fire(...)
	local function signal()
		local s = { list = {} }
		function s:Connect(fn)
			local entry = { fn = fn }
			self.list[#self.list + 1] = entry
			local c = { Connected = true }
			function c.Disconnect()
				entry.dead = true
				c.Connected = false
			end
			return c
		end
		s.connect = s.Connect
		function s:Once(fn)
			local c
			c = self:Connect(function(...)
				c.Disconnect()
				fn(...)
			end)
			return c
		end
		function s:Fire(...)
			for _, entry in ipairs(table.clone(self.list)) do
				if not entry.dead then task.spawn(entry.fn, ...) end
			end
		end
		function s:Destroy() table.clear(self.list) end
		return s
	end

	local function same(a, b)
		if a == b then return true end
		if type(a) ~= "table" or type(b) ~= "table" then return false end
		for k, v in pairs(a) do if not same(v, b[k]) then return false end end
		for k in pairs(b) do if a[k] == nil then return false end end
		return true
	end

	-- two rows of one card may not share a name: the second gets a trailing
	-- space, which no one sees
	local function unique(hs, text)
		text = tostring(text or "")
		if text == "" then text = "Item" end
		while registry[hs.path .. "/" .. text] or bindables[hs.path .. "/" .. text] or K.favSpecs[hs.path .. "/" .. text] do
			text = text .. " "
		end
		return text
	end

	local function lastRow(body)
		local best, order = nil, -math.huge
		for _, child in ipairs(body:GetChildren()) do
			if child:IsA("GuiObject") and (child.Name == "Row" or child.Name == "Buttons") and child.LayoutOrder > order then
				best, order = child, child.LayoutOrder
			end
		end
		return best
	end

	local UNITS = { px = "px", s = "s", ["%"] = "%", ms = "ms", ["deg/s"] = "°/s" }
	local RENAME = { ["Apply To"] = "Weapon" }
	local HIDDEN = { "^Hold a weapon, then click the pin", "^Custom loadout is ready" }

	local function hidden(text)
		for _, pattern in ipairs(HIDDEN) do
			if string.find(tostring(text), pattern) then return true end
		end
		return false
	end

	local function wordsOf(text)
		local set = {}
		for w in string.gmatch(string.lower(tostring(text or "")), "%S+") do set[w] = true end
		return set
	end

	local function covers(a, b)
		for w in pairs(b) do
			if not a[w] then return false end
		end
		return next(b) ~= nil
	end

	local function merge(...)
		local out = {}
		for _, set in ipairs({ ... }) do
			for w in pairs(set) do out[w] = true end
		end
		return out
	end

	local function secret(path)
		local item = registry[path]
		if item then item.secret = true end
	end

	-- --------------------------------------------------------- elements --
	local rowControl = setmetatable({}, { __mode = "k" })

	local function element(row, kind)
		local E = { Row = row, Kind = kind, ValueChanged = signal(), Changed = signal(), Clicked = signal(), shown = true, inGroup = true }
		function E:OnChanged(fn) return self.Changed:Connect(fn) end
		function E:Connect(sig, fn) return sig:Connect(fn) end
		function E:paintVisible()
			if self.Row and self.Row.Parent then self.Row.Visible = self.shown and self.inGroup end
		end
		function E:SetVisible(b)
			self.shown = b ~= false
			self:paintVisible()
		end
		function E:SetOptions() end
		function E:SetFeatureEnabled() end
		function E:SetShowInList() end
		function E:SetLabel(text)
			local label = self.Row and self.Row:FindFirstChild("Label")
			if label then label.Text = tostring(text or "") end
		end
		function E:Destroy() if self.Row then self.Row:Destroy() end end
		return E
	end

	-- a value row: apply(v) shows v without firing; E.user(v) is a change made by hand
	local function valued(E, opts, apply, initial)
		E.Value = initial
		local muted = false
		E.muted = function() return muted end
		function E:Set(v, silent)
			self.Value = v
			muted = true
			pcall(apply, v)
			muted = false
			self.ValueChanged:Fire(v)
			if not silent then
				self.Changed:Fire(v)
				if opts.OnChanged then task.spawn(opts.OnChanged, v) end
			end
		end
		function E.user(v)
			if muted then return end
			E.Value = v
			E.ValueChanged:Fire(v)
			E.Changed:Fire(v)
			if opts.OnChanged then task.spawn(opts.OnChanged, v) end
		end
		return E
	end

	-- the pin: hold a weapon and give this setting that weapon's own value
	local function pinChip(E, path)
		local pins = store and store.Pins
		local row = E.Row
		if not (pins and row and type(pins.CanPin) == "function") then return end
		local tall = row.Size.Y.Offset > K.L.ROW
		local b = new("ImageButton", {
			Name = "Pin",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = tall and UDim2.new(1, -98, 0, 13) or UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.fromOffset(18, 18),
			BackgroundTransparency = 1,
			AutoButtonColor = false,
			Image = "",
			Visible = false,
			ZIndex = 5,
		}, row)
		local icon = K.glyph(b, "map-pin", 13, C.faint, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			ZIndex = 6,
		})
		-- like the star: shown under the pointer, and while pinned
		local could, on, hovered = false, false, false
		local function look()
			icon.ImageColor3 = on and C.text or C.faint
			icon.ImageTransparency = (on or hovered) and 0 or 1
		end
		local function paint()
			local ok, can = pcall(pins.CanPin, path)
			can = ok and can == true
			on = can and pins.IsPinned(path) == true
			if can ~= b.Visible then
				b.Visible = can
				if not tall then arrange(row) end
			end
			K.Icons.set(icon, "map-pin", on)
			look()
			if can or could then E:Set(store:Get(path), true) end
			could = can
		end
		row.MouseEnter:Connect(function() hovered = true; look() end)
		row.MouseLeave:Connect(function() hovered = false; look() end)
		b.MouseButton1Click:Connect(function()
			SFX.click()
			pcall(pins.Toggle, path)
		end)
		pins.Changed:Connect(paint)
		paint()
	end

	-- Kicia's two-way link (P.bind): sliders write once per short burst
	local function bindStore(E, path, debounce)
		if not (store and type(path) == "table") then return end
		E.path = path
		E:Set(store:Get(path), true)
		store:Changed(path):Connect(function(v)
			if not same(v, E.Value) then E:Set(v, true) end
		end)
		local pending, scheduled = nil, false
		E.Changed:Connect(function(v)
			if not debounce then store:Set(path, v) return end
			pending = v
			if scheduled then return end
			scheduled = true
			task.delay(0.05, function()
				scheduled = false
				store:Set(path, pending)
			end)
		end)
		pinChip(E, path)
	end

	-- a row that only names what sits on its end (a colour, a key)
	local function plainRow(hs, text)
		local row = rowBase(hs.body)
		rowLabel(row, text, 0)
		hs:register(unique(hs, text))
		return row
	end

	-- a soft text field on a row
	local function textRow(hs, text, placeholder)
		local row = rowBase(hs.body)
		rowLabel(row, text, 0)
		local face = new("Frame", {
			Name = "Field",
			AnchorPoint = Vector2.new(1, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(0.55, 0, 0, K.L.ROW - 8),
			BackgroundColor3 = C.field,
			BorderSizePixel = 0,
			ZIndex = 3,
		}, row)
		corner(face, 7)
		K.sheen(face, 0.82)
		local edge = stroke(face, C.text, 1)
		local box = new("TextBox", {
			Position = UDim2.fromOffset(10, 0),
			Size = UDim2.new(1, -20, 1, 0),
			BackgroundTransparency = 1,
			ClearTextOnFocus = false,
			FontFace = K.face.medium,
			PlaceholderText = tostring(placeholder or ""),
			PlaceholderColor3 = C.faint,
			Text = "",
			TextSize = 12,
			TextColor3 = C.text,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			ClipsDescendants = true,
			ZIndex = 4,
		}, face)
		box.Focused:Connect(function() tween(edge, 0.15, { Transparency = 0.6 }) end)
		box.FocusLost:Connect(function() tween(edge, 0.2, { Transparency = 1 }) end)
		arrange(row)
		return row, box
	end

	local function caption(hs, text)
		local row = rowBase(hs.body, 28)
		K.text(row, {
			Name = "Caption",
			Position = UDim2.fromOffset(0, 6),
			Size = UDim2.new(1, 0, 0, 22),
			FontFace = K.face.semi,
			Text = tostring(nice(text or "")),
			TextSize = 11,
			TextColor3 = C.sub,
		})
		return row
	end

	local function toList(v)
		local out = {}
		if type(v) ~= "table" then return out end
		if #v > 0 then
			for _, s in ipairs(v) do out[#out + 1] = tostring(s) end
		else
			for k, on in pairs(v) do if on == true then out[#out + 1] = tostring(k) end end
		end
		return out
	end

	-- ------------------------------------------------------------ keys --
	local SHORT = {
		MouseButton1 = "MB1", MouseButton2 = "MB2", MouseButton3 = "MB3", LeftShift = "LShift", RightShift = "RShift",
		LeftControl = "LCtrl", RightControl = "RCtrl", LeftAlt = "LAlt", RightAlt = "RAlt",
	}
	local function keyName(v)
		if typeof(v) == "EnumItem" then return v.Name end
		if type(v) == "string" and v ~= "" and v ~= "None" then return v end
		return nil
	end
	local function keyEnum(name)
		if not name then return nil end
		if name == "MouseButton1" or name == "MouseButton2" or name == "MouseButton3" then return Enum.UserInputType[name] end
		local ok, e = pcall(function() return Enum.KeyCode[name] end)
		return ok and e or nil
	end

	-- Kicia's key on a row: the menu's own key chip, but the key and its mode
	-- live in Kicia's store and Kicia's keybind controller runs them
	local function kiciaKey(hs, opts, row, label)
		local map = type(opts.ConfigMap) == "table" and opts.ConfigMap or {}
		local modes = type(opts.Modes) == "table" and opts.Modes or { "Toggle" }
		local default = type(opts.Default) == "table" and opts.Default or {}
		local control = row and rowControl[row]
		if not control then
			label = unique(hs, label or opts.Label or opts.ListLabel or "Keybind")
			row = row or rowBase(hs.body)
			if not row:FindFirstChild("Label") then rowLabel(row, label, 0) end
			local hit = new("TextButton", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "", ZIndex = 3 }, row)
			K.rowHover(row, hit)
			control = hs:bindable(label, hit, row, function() end)
			control.standalone = true
			hs:register(label)
		end
		control.secret = true
		control.mouse = true
		control.trigger = function() end
		control.listLabel = opts.ListLabel or opts.Label
		local E = element(row, "keybind")
		E.Value = { Key = keyName(default.Key), Mode = default.Mode or modes[1] }
		local feature, inList = true, opts.InKeybindList ~= false
		local muted = false
		local function mode()
			local m = map.Mode and store and store:Get(map.Mode)
			return type(m) == "string" and m or E.Value.Mode or modes[1]
		end
		local function listed()
			local show = not map.ShowInList or not store or store:Get(map.ShowInList) ~= false
			control.unlisted = not (inList and feature and show)
		end
		local base = control.paintBind
		control.paintBind = function()
			base()
			local key = control.bindKey
			local m = mode()
			local shown = key ~= nil or control.listening == true or control.standalone or (m ~= "Always" and #modes > 1)
			local text
			if control.listening then
				text = "..."
			elseif key then
				text = (SHORT[key] or key) .. (#modes > 1 and (" · " .. m) or "")
			else
				text = #modes > 1 and m or "None"
			end
			control.chip.Visible = shown
			control.chip.Text = text
			control.chip.Size = UDim2.fromOffset(math.max(24, 14 + utf8.len(text) * 6.4), 20)
			local holder = control.chip.Parent
			if holder and holder.Name == "Row" then task.defer(arrange, holder) end
		end
		control.lit = function()
			if not feature then return false end
			if map.Active and store then return store:Get(map.Active) == true end
			return true
		end
		control.onAssign = function(name)
			E.Value = { Key = name, Mode = mode() }
			if muted then return end
			if store and map.Key then store:Set(map.Key, keyEnum(name)) end
			-- a key on an always-on feature means it should listen to it now
			if store and map.Mode and #modes > 1 then
				local m = mode()
				if name and m == "Always" then
					for _, other in ipairs(modes) do
						if other ~= "Always" then store:Set(map.Mode, other) break end
					end
				elseif not name and table.find(modes, "Always") then
					store:Set(map.Mode, "Always")
				end
			end
			E.Changed:Fire(E.Value)
			if opts.OnChanged then task.spawn(opts.OnChanged, E.Value) end
		end
		local function sync()
			local key = map.Key and store and keyName(store:Get(map.Key)) or E.Value.Key
			muted = true
			K.assignBind(control, key)
			muted = false
			listed()
			control.paintBind()
		end
		control.chip.MouseButton2Click:Connect(function()
			if #modes < 2 then return end
			local i = table.find(modes, mode()) or 0
			local nextMode = modes[i % #modes + 1]
			SFX.click()
			if store and map.Mode then
				store:Set(map.Mode, nextMode)
			else
				E.Value = { Key = E.Value.Key, Mode = nextMode }
				control.paintBind()
			end
		end)
		if store then
			for _, p in ipairs({ map.Key, map.Mode, map.ShowInList }) do
				if type(p) == "table" then store:Changed(p):Connect(sync) end
			end
			if map.Active then
				store:Changed(map.Active):Connect(function()
					if refreshKeyList then refreshKeyList() end
				end)
			end
		end
		function E:Set(v, silent)
			if type(v) ~= "table" then return end
			if store and map.Mode and v.Mode then store:Set(map.Mode, v.Mode) end
			if v.Key ~= nil then
				local name = keyName(v.Key)
				if store and map.Key then store:Set(map.Key, keyEnum(name)) end
				E.Value = { Key = name, Mode = v.Mode or mode() }
			end
			sync()
		end
		function E:SetFeatureEnabled(b)
			feature = b ~= false
			listed()
			if refreshKeyList then refreshKeyList() end
		end
		function E:SetShowInList(b)
			if store and map.ShowInList then store:Set(map.ShowInList, b ~= false) else inList = b ~= false end
			listed()
			if refreshKeyList then refreshKeyList() end
		end
		E.ActiveChanged, E.ShowInListChanged, E.InvisibleChanged = signal(), signal(), signal()
		sync()
		return E
	end

	-- ------------------------------------------------------------ colour --
	local function asColor(v)
		if typeof(v) == "Color3" then return v end
		if typeof(v) == "ColorSequence" then return v.Keypoints[1].Value end
		if type(v) == "table" and typeof(v.Rgb) == "Color3" then return v.Rgb end
		return nil
	end

	local function colorRow(hs, opts, row)
		local path = opts.Config
		local label
		if row then
			local l = row:FindFirstChild("Label")
			label = unique(hs, (l and l.Text or opts.Label or "Item") .. " color")
		else
			label = unique(hs, opts.Label or "Color")
		end
		local first = asColor(opts.Default) or (path and store and asColor(store:Get(path))) or C.accent
		local E = element(row, "color")
		local value = first
		local api, swatch
		if row then
			local before = {}
			for _, c in ipairs(row:GetChildren()) do before[c] = true end
			api = hs:inlineColor(row, label, first, function(c) E.picked(c) end)
			for _, c in ipairs(row:GetChildren()) do
				if not before[c] and c.Name == "Swatch" then swatch = c end
			end
			local tools = row.Name == "Header" and row:FindFirstChild("Tools")
			if swatch and tools then
				-- a card switch's colours line up in the title's tools
				swatch.Parent = tools
				swatch.LayoutOrder = 5
			elseif swatch then
				-- a second colour on one row stands beside the first
				for _, c in ipairs(row:GetChildren()) do
					if c ~= swatch and c.Name == "Swatch" then
						swatch.Name = "Swatch2"
						arrange(row)
						break
					end
				end
			end
		else
			api = hs:color(label, first, function(c) E.picked(c) end)
			E.Row = lastRow(hs.body)
			swatch = E.Row and E.Row:FindFirstChild("Swatch")
		end
		secret(hs.path .. "/" .. label)
		local ramp = swatch and new("UIGradient", { Enabled = false }, swatch)
		local function paint(v)
			if not ramp then return end
			if typeof(v) == "ColorSequence" then
				ramp.Color = v
				ramp.Enabled = true
				swatch.BackgroundColor3 = Color3.new(1, 1, 1)
			else
				ramp.Enabled = false
			end
		end
		valued(E, opts, function(v)
			local c = asColor(v)
			if c then
				value = c
				api.set(c)
			end
			paint(v)
		end, first)
		-- the picker gives one colour: on a gradient it is the first stop
		function E.picked(c)
			if E.muted() then return end
			value = c
			local v = E.Value
			if typeof(v) == "ColorSequence" then
				local kp = v.Keypoints
				local out = { ColorSequenceKeypoint.new(0, c) }
				for i = 2, #kp do out[#out + 1] = kp[i] end
				v = ColorSequence.new(out)
			else
				v = c
			end
			paint(v)
			E.user(v)
		end
		local function setEnd(c)
			local v = E.Value
			local start = asColor(v) or value
			local out = { ColorSequenceKeypoint.new(0, start) }
			if typeof(v) == "ColorSequence" then
				local kp = v.Keypoints
				for i = 2, #kp - 1 do out[#out + 1] = kp[i] end
			end
			out[#out + 1] = ColorSequenceKeypoint.new(1, c)
			local seq = ColorSequence.new(out)
			paint(seq)
			E.user(seq)
		end
		-- right click: the end of a gradient, opacity, and the animation
		local transparency = opts.Transparency
		local animatable = opts.Animatable and colorAnim and path
		local gradient = opts.Gradient ~= nil and opts.Gradient ~= false
		if swatch and (transparency or animatable or gradient) then
			swatch.MouseButton2Click:Connect(function()
				local items, sliders = {}, {}
				if gradient then
					if typeof(E.Value) == "ColorSequence" then
						local kp = E.Value.Keypoints
						items[#items + 1] = { name = "Gradient end color", icon = "palette", callback = function()
							K.openPicker(swatch, kp[#kp].Value, setEnd)
						end }
						items[#items + 1] = { name = "Make solid", icon = "circle", callback = function()
							local c = asColor(E.Value) or value
							paint(c)
							E.user(c)
						end }
					else
						items[#items + 1] = { name = "Make gradient", icon = "palette", callback = function()
							K.openPicker(swatch, value, setEnd)
						end }
					end
				end
				local anim
				if animatable then
					local ok, got = pcall(function() return colorAnim:Get(path) end)
					anim = ok and got or { Mode = "None", Speed = 1 }
					for _, m in ipairs(transparency and { "None", "Rainbow", "Breathing" } or { "None", "Rainbow" }) do
						items[#items + 1] = {
							name = m == "None" and "Static" or m,
							icon = anim.Mode == m and "check" or nil,
							on = anim.Mode == m,
							callback = function() pcall(function() colorAnim:SetMode(path, m) end) end,
						}
					end
					sliders[#sliders + 1] = { name = "Animation speed", min = 0.1, max = 5, step = 0.1, value = anim.Speed or 1,
						callback = function(v) pcall(function() colorAnim:SetSpeed(path, v) end) end }
				end
				if transparency and store then
					local t = tonumber(store:Get(transparency)) or 0
					sliders[#sliders + 1] = { name = "Opacity", min = 0, max = 100, step = 1, suffix = "%",
						value = math.floor((1 - t) * 100 + 0.5),
						callback = function(v) store:Set(transparency, 1 - v / 100) end }
				end
				SFX.click()
				popmenu({ title = nice(label), items = items, sliders = sliders, follow = swatch, width = 220 })
			end)
		end
		bindStore(E, path)
		-- Kicia's colour animation (rainbow, breathing) runs off its store;
		-- the menu hands it each colour's entry, as Kicia's menu did
		if animatable then
			local function apply()
				pcall(function() colorAnim:Apply(path, transparency, colorAnim:Get(path)) end)
			end
			pcall(function() colorAnim:Changed():Connect(apply) end)
			apply()
		end
		return E
	end

	-- --------------------------------------------------------- container --
	-- A card, a group inside one, or an options sheet: what Kicia called a
	-- section. Rows of an inline group show while its source matches.
	local Container = {}
	Container.__index = Container

	local function container(hs, ctx, parent, test)
		local self = setmetatable({ hs = hs, ctx = ctx, parent = parent, test = test, members = {}, kids = {} }, Container)
		if parent then parent.kids[#parent.kids + 1] = self end
		return self
	end

	function Container:open()
		if self.test and not self.test() then return false end
		if self.parent then return self.parent:open() end
		return true
	end

	function Container:refresh()
		local on = self:open()
		for _, E in ipairs(self.members) do
			E.inGroup = on
			E:paintVisible()
		end
		for _, kid in ipairs(self.kids) do kid:refresh() end
	end

	function Container:adopt(E)
		self.members[#self.members + 1] = E
		E.container = self
		if self.test or self.parent then
			E.inGroup = self:open()
			E:paintVisible()
		end
		return E
	end

	function Container:GetConfig() return store end

	-- the name a row shows, the unit its value carries, and a hint for a field:
	-- no "Enable", no card or switch name in front, the card's own switch
	-- goes on its title line
	function Container:name(label, toggle)
		local text, unit, hint = tostring(label or ""), nil, nil
		local base, inner = string.match(text, "^(.-)%s*%((.-)%)$")
		if base and base ~= "" then
			text = base
			unit = UNITS[string.lower(inner)]
			if not unit then hint = inner end
		end
		local enable = toggle and string.match(text, "^Enable (.+)$")
		if enable then text = enable end
		local hs = self.hs
		if toggle and self.isSection and not hs.hasRows and hs.tools then
			local title = tostring(hs.title)
			local a, b = wordsOf(text), wordsOf(title)
			if covers(a, b) or (enable and covers(b, a)) then return title, unit, hint end
		end
		local prefix = self.prefix
		local words = self.words
		if enable and self.isSection then words = merge(words or {}, wordsOf(hs.title)) end
		if prefix and #text > #prefix + 1 and string.lower(string.sub(text, 1, #prefix + 1)) == string.lower(prefix) .. " " then
			text = string.sub(text, #prefix + 2)
		elseif words then
			local out, leading = {}, true
			for w in string.gmatch(text, "%S+") do
				if not (leading and words[string.lower(w)]) then
					leading = false
					out[#out + 1] = w
				end
			end
			if #out > 0 then text = table.concat(out, " ") end
		end
		text = RENAME[text] or text
		return string.upper(string.sub(text, 1, 1)) .. string.sub(text, 2), unit, hint
	end

	function Container:AddToggle(opts)
		local hs = self.hs
		local shown = self:name(opts.Label or "Enabled", true)
		local label = unique(hs, shown)
		local initial = opts.Default == true
		local E
		local _, row = hs:toggle(label, initial, function(v) if E then E.user(v) end end)
		E = element(row, "toggle")
		valued(E, opts, function(v)
			local item = registry[hs.path .. "/" .. label]
			if item then item.set(v == true) end
		end, initial)
		E.label = label
		E.words = merge(wordsOf(opts.Label), wordsOf(shown))
		rowControl[row] = bindables[hs.path .. "/" .. label]
		secret(hs.path .. "/" .. label)
		bindStore(E, opts.Config)
		return self:adopt(E)
	end

	function Container:AddSlider(opts)
		local hs = self.hs
		local shown, unit = self:name(opts.Label or "Value")
		local label = unique(hs, shown)
		local min, max = tonumber(opts.Min) or 0, tonumber(opts.Max) or 100
		local step = tonumber(opts.Step) or 1
		local initial = tonumber(opts.Default) or min
		local E
		local _, row = hs:slider(label, min, max, initial, function(v) if E then E.user(v) end end, opts.Suffix or unit, step)
		E = element(row, "slider")
		valued(E, opts, function(v)
			local item = registry[hs.path .. "/" .. label]
			if item and tonumber(v) then item.set(tonumber(v)) end
		end, initial)
		secret(hs.path .. "/" .. label)
		bindStore(E, opts.Config, true)
		return self:adopt(E)
	end

	-- two sliders for one { Min, Max }
	function Container:AddRangeSlider(opts)
		local hs = self.hs
		local min, max = tonumber(opts.Min) or 0, tonumber(opts.Max) or 100
		local step = tonumber(opts.Step) or 1
		local d = type(opts.Default) == "table" and opts.Default or {}
		local range = { Min = tonumber(d.Min) or min, Max = tonumber(d.Max) or max }
		local base, unit = self:name(opts.Label or "Range")
		local lo, hi = unique(hs, base .. " Min"), nil
		local E
		local _, rowLo = hs:slider(lo, min, max, range.Min, function(v) if E then E.user({ Min = v, Max = E.Value.Max }) end end, opts.Suffix or unit, step)
		hi = unique(hs, base .. " Max")
		local _, rowHi = hs:slider(hi, min, max, range.Max, function(v) if E then E.user({ Min = E.Value.Min, Max = v }) end end, opts.Suffix or unit, step)
		E = element(rowLo, "range")
		valued(E, opts, function(v)
			if type(v) ~= "table" then return end
			if tonumber(v.Min) then registry[hs.path .. "/" .. lo].set(tonumber(v.Min)) end
			if tonumber(v.Max) then registry[hs.path .. "/" .. hi].set(tonumber(v.Max)) end
		end, range)
		local paintVisible = E.paintVisible
		function E:paintVisible()
			paintVisible(self)
			rowHi.Visible = rowLo.Visible
		end
		secret(hs.path .. "/" .. lo)
		secret(hs.path .. "/" .. hi)
		bindStore(E, opts.Config, true)
		return self:adopt(E)
	end

	-- a dropdown whose values may differ from what it shows (Labels), may be
	-- empty, and may change its options
	local function choice(self, opts, multi)
		local hs = self.hs
		local label = unique(hs, (self:name(opts.Label or "Mode")))
		local labels = type(opts.Labels) == "table" and opts.Labels or {}
		local values, shown = {}, {}
		local back = {}
		local function fill(list)
			table.clear(values)
			table.clear(shown)
			table.clear(back)
			for _, v in ipairs(type(list) == "table" and list or {}) do
				local text = tostring(labels[v] or v)
				values[#values + 1] = v
				shown[#shown + 1] = text
				back[text] = v
			end
		end
		fill(opts.Options)
		local E, row, field
		if multi then
			local initial = toList(opts.Default)
			local disp = {}
			for _, v in ipairs(initial) do disp[#disp + 1] = tostring(labels[v] or v) end
			local api = hs:multi(label, shown, disp, function(list)
				if not E then return end
				local map = {}
				for _, text in ipairs(list) do
					local v = back[text]
					if v ~= nil then map[v] = true end
				end
				E.user(map)
			end)
			row = lastRow(hs.body)
			E = element(row, "multi")
			local start = {}
			for _, v in ipairs(initial) do start[v] = true end
			valued(E, opts, function(v)
				local list = {}
				for _, key in ipairs(toList(v)) do list[#list + 1] = tostring(labels[key] or key) end
				api.set(list)
			end, start)
			-- the field keeps `shown` itself: refill it and repaint
			function E:SetOptions(list)
				fill(list)
				E:Set(E.Value, true)
			end
		else
			local default = opts.Default
			if default == nil and opts.SelectFirst ~= false and opts.Config == nil and opts.List then default = values[1] end
			local _, r = hs:dropdown(label, shown, default ~= nil and tostring(labels[default] or default) or nil, function(text)
				if E then E.user(back[text]) end
			end)
			row = r
			field = row:FindFirstChild("Field")
			local valueLabel = field and field:FindFirstChild("Value", true)
			E = element(row, "dropdown")
			local function show(v)
				if valueLabel then valueLabel.Text = v == nil and "None" or tostring(labels[v] or v) end
			end
			valued(E, opts, function(v)
				local item = registry[hs.path .. "/" .. label]
				if item and v ~= nil then item.set(tostring(labels[v] or v)) end
				show(v)
			end, default)
			show(default)
			E.ValueChanged:Connect(show)
			function E:SetOptions(list)
				fill(list)
				show(E.Value)
			end
			if type(opts.GetOptions) == "function" and field then
				field.MouseButton1Down:Connect(function()
					local ok, list = pcall(opts.GetOptions)
					if ok and type(list) == "table" then fill(list) end
				end)
			end
		end
		secret(hs.path .. "/" .. label)
		bindStore(E, opts.Config)
		return self:adopt(E)
	end

	function Container:AddDropdown(opts) return choice(self, opts, false) end
	function Container:AddMultiDropdown(opts) return choice(self, opts, true) end

	-- a list to pick one from: a dropdown that may stay empty
	function Container:AddList(opts)
		local o = table.clone(opts)
		o.List = true
		local E = choice(self, o, false)
		if opts.SelectFirst ~= false and E.Value == nil and type(opts.Options) == "table" and opts.Options[1] ~= nil then
			E:Set(opts.Options[1], true)
		end
		local set = E.SetOptions
		function E:SetOptions(list)
			set(self, list)
			if self.Value ~= nil and not table.find(list, self.Value) then self:Set(nil) end
		end
		return E
	end

	-- an order of a few things: every order is an option
	function Container:AddOrderedList(opts)
		local items = type(opts.Items) == "table" and opts.Items or {}
		local orders = {}
		local function permute(rest, acc)
			if #rest == 0 then orders[#orders + 1] = table.clone(acc) return end
			for i, v in ipairs(rest) do
				local left = table.clone(rest)
				table.remove(left, i)
				acc[#acc + 1] = v
				permute(left, acc)
				acc[#acc] = nil
			end
		end
		permute(items, {})
		local names, byName = {}, {}
		for _, order in ipairs(orders) do
			local name = table.concat(order, " > ")
			names[#names + 1] = name
			byName[name] = order
		end
		local inner = choice(self, { Label = opts.Label, Options = names, Default = names[1] }, false)
		local E = inner
		local set = inner.Set
		function E:Set(v, silent)
			local order = type(v) == "table" and v or byName[v]
			set(self, order and table.concat(order, " > ") or nil, true)
			self.Value = order
			if not silent then self.Changed:Fire(order) end
		end
		local user = inner.user
		inner.user = function(name) user(byName[name] or name) end
		E.Value = type(opts.Default) == "table" and opts.Default or orders[1]
		bindStore(E, opts.Config)
		return E
	end

	function Container:AddColor(opts)
		local o = opts
		if opts.Label and not opts.Row then
			o = table.clone(opts)
			o.Label = self:name(opts.Label)
		end
		return self:adopt(colorRow(self.hs, o, opts.Row))
	end

	function Container:AddKeybind(opts)
		local E = kiciaKey(self.hs, opts, opts.Row, opts.Label)
		if not opts.Row then self:adopt(E) end
		return E
	end

	function Container:AddButton(opts)
		local hs = self.hs
		local label = unique(hs, (self:name(opts.Label or "Button")))
		local E
		local function run()
			E.Clicked:Fire()
			if opts.OnClick then task.spawn(opts.OnClick) end
		end
		hs:button(label, function()
			if opts.Confirm then
				K.confirm(nice(label), "Are you sure?", "Confirm", run)
			else
				run()
			end
		end)
		local bar = lastRow(hs.body)
		local button
		for _, c in ipairs(bar and bar:GetChildren() or {}) do
			if c:IsA("TextButton") and c.Name ~= "Bind" then button = c end
		end
		E = element(button, "button")
		local paintVisible = E.paintVisible
		function E:paintVisible()
			paintVisible(self)
			if not bar then return end
			local any = false
			for _, c in ipairs(bar:GetChildren()) do
				if c:IsA("TextButton") and c.Visible then any = true end
			end
			bar.Visible = any
		end
		function E:OnClick(fn) return self.Clicked:Connect(fn) end
		function E:Set() end
		return self:adopt(E)
	end

	function Container:AddTextBox(opts)
		local hs = self.hs
		if self.gallery and string.find(tostring(opts.Label), "^Search") then
			-- the catalog card searches itself
			return valued(element(nil, "text"), opts, function() end, "")
		end
		local shown, _, hint = self:name(opts.Label or "Text")
		local label = unique(hs, shown)
		local row, box = textRow(hs, label, opts.Placeholder or hint)
		local E = element(row, "text")
		valued(E, opts, function(v) box.Text = v == nil and "" or tostring(v) end, "")
		local lastSent = ""
		local function send()
			if E.muted() then return end
			if box.Text == lastSent then return end
			lastSent = box.Text
			E.user(box.Text)
		end
		if opts.FocusLostOnly or opts.Config then
			box.FocusLost:Connect(send)
		else
			box:GetPropertyChangedSignal("Text"):Connect(send)
		end
		E.ValueChanged:Connect(function(v) lastSent = v == nil and "" or tostring(v) end)
		hs:register(label, function() return box.Text end, function(v) box.Text = tostring(v or ""); send() end)
		secret(hs.path .. "/" .. label)
		bindStore(E, opts.Config)
		return self:adopt(E)
	end

	-- a short name becomes a row a colour can sit on; a note wraps
	function Container:AddLabel(opts)
		local hs = self.hs
		local text = tostring(opts.Label or "")
		local E
		if hidden(text) then
			E = element(nil, "label")
			E.Value = text
			function E:Set() end
			return E
		end
		if opts.TextColor == nil and #text <= 40 and text ~= "" then
			E = element(plainRow(hs, (self:name(text))), "label")
		else
			local api = hs:label(text)
			E = element(lastRow(hs.body), "label")
			if opts.TextColor and E.Row then
				local l = E.Row:FindFirstChild("Label")
				if l then l.TextColor3 = C.value end
			end
			function E:SetLabel(t)
				api.set(t)
				self.shown = not hidden(t) and tostring(t) ~= ""
				self:paintVisible()
			end
			if text == "" then E:SetVisible(false) end
		end
		E.Value = text
		function E:Set() end
		return self:adopt(E)
	end

	local dividers = {}
	function Container:AddDivider(opts)
		local E = element(caption(self.hs, opts and opts.Label or ""), "divider")
		dividers[#dividers + 1] = E
		return self:adopt(E)
	end

	local function pruneDividers()
		for _, E in ipairs(dividers) do
			local row = E.Row
			local body = row and row.Parent
			if body then
				local rows = 0
				local nextOrder = math.huge
				for _, other in ipairs(dividers) do
					local o = other.Row
					if o and o.Parent == body and o.LayoutOrder > row.LayoutOrder and o.LayoutOrder < nextOrder then
						nextOrder = o.LayoutOrder
					end
				end
				for _, child in ipairs(body:GetChildren()) do
					if child:IsA("GuiObject") and (child.Name == "Row" or child.Name == "Buttons")
						and child.LayoutOrder > row.LayoutOrder and child.LayoutOrder < nextOrder and child ~= row then
						rows += 1
					end
				end
				if rows < 2 then E:SetVisible(false) end
			end
		end
	end

	-- A group: a switch's extra settings open from the gear on its row; a
	-- choice's settings sit under it and show while the choice matches.
	function Container:AddGroup(opts)
		local source = opts.Source
		if source and source.Kind == "toggle" and opts.Option == nil then
			if not source.sheet then
				local hs = self.hs
				local sheet = hs:options(source.Row, source.label or "Options", source.label)
				sheet.nofav = hs.nofav
				source.sheet = container(sheet, self.ctx)
				source.sheet.words = merge(self.words or {}, source.words or {})
			end
			return source.sheet
		end
		local option = opts.Option
		local group = container(self.hs, self.ctx, self, function()
			if not source then return true end
			local v = source.Value
			if option == nil then return v ~= nil and v ~= false end
			if type(v) == "table" then
				if #v > 0 then return table.find(v, option) ~= nil end
				return v[option] == true
			end
			return v == option
		end)
		group.words, group.prefix, group.gallery = self.words, self.prefix, self.gallery
		if source and source.ValueChanged then
			source.ValueChanged:Connect(function() group:refresh() end)
		end
		return group
	end

	-- a catalog: the cell's own picture, or Kicia's 3D render of the item
	local function paintCell(c, raw)
		local old = c.stage:FindFirstChild("Render")
		if old then old:Destroy() end
		c.thumb.Visible = true
		if type(raw) == "table" and type(raw.Render) == "function" then
			local holder = new("Frame", {
				Name = "Render",
				AnchorPoint = Vector2.new(0.5, 0.5),
				Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.new(1, -6, 1, -6),
				BackgroundTransparency = 1,
				ZIndex = c.thumb.ZIndex,
			}, c.stage)
			pcall(raw.Render, raw, { Content = holder, HideImage = function() c.thumb.Visible = false end })
		end
	end

	local function catalog(tabName, subName, col, title)
		local cfg = {
			Name = (string.gsub(title, " Catalog$", "")) .. "s",
			Height = 420,
			Cell = 84,
			Empty = "Loading",
			EmptyIcon = "hourglass",
			Paint = paintCell,
		}
		local api = UI.gallery(tabName, subName, col, cfg)
		secret(tabName .. "/" .. subName .. "/" .. cfg.Name)
		local rows = new("Frame", {
			Name = "Rows",
			LayoutOrder = 0,
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
		}, api.frame:FindFirstChild("Body"))
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder }, rows)
		local tab, _, index = findSub(tabName, subName)
		local hs = setmetatable({
			body = rows,
			card = api.frame,
			title = title,
			tab = tab,
			sub = index,
			path = tabName .. "/" .. subName .. "/" .. title,
			where = tabName .. " / " .. subName,
		}, Section)
		return hs, api, cfg
	end

	function Container:AddSkinChanger(opts)
		local api, cfg = self.gallery, self.galleryCfg
		local items, filter = {}, nil
		local E = element(api.frame, "skins")
		cfg.Callback = function(name)
			if E.muted and E.muted() then return end
			E.user(name)
		end
		valued(E, opts, function(v) api.set(v, true) end, nil)
		local function apply()
			local list = {}
			for _, item in ipairs(items) do
				local ok, keep = true, true
				if filter then ok, keep = pcall(filter, item, string.lower(tostring(item.Name or ""))) end
				if not ok or keep then list[#list + 1] = item end
			end
			api.setdata(list)
			if E.Value ~= nil then api.set(E.Value, true) end
		end
		function E:SetItems(list)
			items = type(list) == "table" and list or {}
			apply()
		end
		function E:SetFilter(fn)
			filter = fn
			apply()
		end
		local STATES = { Loading = "Loading", NoMatches = "Nothing found", Empty = "Empty" }
		function E:SetState(state, message)
			cfg.Empty = message or STATES[state] or ""
			if state == "Loading" then api.setdata({}) end
			api.refresh()
		end
		function E:SetClearFilterAction() end
		function E:paintVisible() end
		return E
	end

	-- --------------------------------------------------------- pages --
	local function columnFor(side, columns)
		if columns == 1 or side == "full" then return "full" end
		return side == "right" and 2 or 1
	end

	local Grid = {}
	Grid.__index = Grid
	function Grid:AddSection(opts)
		local col = columnFor(opts.Side, self.columns)
		local title = tostring(opts.Title or "Settings")
		if string.find(title, " Catalog$") then
			local hs, api, cfg = catalog(self.tab, self.sub, col, title)
			local c = container(hs, { tab = self.tab, sub = self.sub, col = col })
			c.gallery, c.galleryCfg = api, cfg
			return c
		end
		local c = container(UI.section(self.tab, self.sub, col, title), { tab = self.tab, sub = self.sub, col = col })
		c.isSection, c.prefix = true, title
		return c
	end
	function Grid:AddMultiSection(opts)
		local out = {}
		for _, title in ipairs(opts.Titles or {}) do
			out[#out + 1] = self:AddSection({ Title = title, Side = opts.Side })
		end
		return table.unpack(out)
	end

	local Page = {}
	Page.__index = Page
	function Page:Grid(opts)
		return setmetatable({ tab = self.tab, sub = self.sub, columns = opts and opts.Columns or 2 }, Grid)
	end
	function Page:Open() K.jump(self.tab, self.sub) end
	-- the first time the page is on screen
	function Page:OnFirstOpen(fn)
		local _, sub = findSub(self.tab, self.sub)
		local done = false
		local function check()
			if done or K.unloaded then return end
			if sub.page.Parent == K.content and sub.page.Visible and root.Visible then
				done = true
				task.spawn(fn)
			end
		end
		sub.page:GetPropertyChangedSignal("Visible"):Connect(check)
		sub.page:GetPropertyChangedSignal("Parent"):Connect(check)
		root:GetPropertyChangedSignal("Visible"):Connect(check)
		check()
	end

	local Category = {}
	Category.__index = Category
	function Category:AddTab(opts)
		return setmetatable({ tab = self.name, sub = tostring(opts.Label) }, Page)
	end

	-- ---------------------------------------------------------- dialogs --
	-- A dialog is a sheet: each page a part with its fields and its action.
	local function dialog(title, build)
		local body = new("Frame", {
			Name = "Dialog",
			Size = UDim2.new(1, 0, 0, 0),
			AutomaticSize = Enum.AutomaticSize.Y,
			BackgroundTransparency = 1,
		}, K.attic)
		pad(body, 6, 18, 20, 20)
		new("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2) }, body)
		local pages = {}
		local D = {}
		function D:AddPage(spec, fill)
			local hs = setmetatable({
				body = body,
				path = "Dialog/" .. tostring(title) .. "/" .. tostring(spec.Title),
				where = tostring(title),
				nofav = true,
				inSheet = true,
			}, Section)
			caption(hs, spec.Title)
			if spec.Description then hs:label(spec.Description) end
			local page = container(hs, {})
			if fill then pcall(fill, page) end
			local enabled = spec.ActionEnabled ~= false
			local P = {}
			local function act()
				local ok, done = pcall(spec.OnAction)
				if ok and done then notify(tostring(spec.Title) .. ": done") end
			end
			hs:button(tostring(spec.ActionText or "Apply"), function()
				if not enabled then return end
				local c = spec.Confirmation
				if type(c) == "table" then
					local text = type(c.Description) == "function" and c.Description() or c.Description
					K.confirm(tostring(c.Title or spec.Title), tostring(text or ""), tostring(c.ActionText or "Confirm"), act)
				else
					act()
				end
			end)
			local bar = lastRow(body)
			local button
			for _, c in ipairs(bar and bar:GetChildren() or {}) do
				if c:IsA("TextButton") then button = c end
			end
			function P:SetActionEnabled(b)
				enabled = b ~= false
				if button then button.TextTransparency = enabled and 0 or 0.6 end
			end
			P:SetActionEnabled(enabled)
			pages[#pages + 1] = spec
			return P
		end
		pcall(build, D)
		for _, spec in ipairs(pages) do
			if type(spec.OnOpen) == "function" then pcall(spec.OnOpen) end
		end
		K.openSheet(nice(title), body, {
			replace = true,
			onClose = function() task.delay(0.5, function() body:Destroy() end) end,
		})
	end

	-- ------------------------------------------------------------ menu --
	local Menu = {}
	Menu.__index = Menu

	function Menu.new(cfg)
		store = cfg.Config
		persistence = cfg.Persistence
		stateObj, stateData = cfg.State, cfg.StateData
		colorAnim = cfg.ColorAnimation
		onUnload = cfg.OnUnload
		-- the store goes into the menu's configs, whole
		K.extraSave = function()
			local ok, r = pcall(function() return persistence:ExportToJson() end)
			return ok and type(r) == "table" and r.Ok and r.Value or nil
		end
		K.extraLoad = function(json)
			if type(json) == "string" and json ~= "" then persistence:LoadFromJson(json) end
		end
		env.__SaladFeaturesCleanup = function()
			if onUnload then pcall(onUnload) end
			local rebuild = getgenv().KiciaRebuild
			if rebuild and rebuild.Unload then pcall(rebuild.Unload) end
		end
		return setmetatable({}, Menu)
	end

	function Menu:AddTab(opts) return setmetatable({ name = tostring(opts.Label) }, Category) end
	function Menu:Dialog(opts, build) dialog(opts and opts.Title or "Dialog", build) end
	function Menu:GetConfig() return store end
	function Menu:GetPersistence() return persistence end
	function Menu:GetStateData() return stateData end
	function Menu:GetColorAnimation() return colorAnim end
	function Menu:SaveState() if stateObj and stateData then pcall(function() stateObj:Save(stateData) end) end end
	function Menu:SetWatermarkUsername(name) K.watermarkName = name ~= nil and tostring(name) or nil end
	function Menu:Destroy() K.unload() end
	function Menu:Unload() K.unload() end

	-- the menu's own settings, then this script's
	function Menu:AddSettingsTab()
		initThemes()
		initOverlay()
		local page = setmetatable({ tab = "Settings", sub = "Script" }, Page):Grid({ Columns = 2 })
		local start = page:AddSection({ Title = "Startup", Side = "left" })
		start:AddToggle({ Label = "Re-run After Teleport", Config = { "AutoExecuteScript", "Enabled" } })
		start:AddToggle({
			Label = "Silent Load",
			Default = stateData ~= nil and stateData.SilentLoad == true,
			OnChanged = function(v)
				if stateData then
					stateData.SilentLoad = v
					self:SaveState()
				end
			end,
		})
		local notes = page:AddSection({ Title = "Notifications", Side = "right" })
		notes:AddToggle({ Label = "Enabled", Config = { "Notifications", "Enabled" } })
		local sides = kicia and kicia.aB().SideSpecs or { "TopLeft", "TopRight", "BottomLeft", "BottomRight", "Center", "Crosshair" }
		notes:AddDropdown({
			Label = "Position",
			Options = sides,
			Labels = { TopLeft = "Top Left", TopRight = "Top Right", BottomLeft = "Bottom Left", BottomRight = "Bottom Right" },
			Config = { "Notifications", "Side" },
		})
		notes:AddSlider({ Label = "Crosshair Offset", Min = -500, Max = 500, Default = 0, Suffix = "px", Config = { "Notifications", "Offset" } })
		notes:AddSlider({ Label = "Text Size", Min = 10, Max = 28, Config = { "Notifications", "Size" } })
		local fonts = kicia and kicia.az().Order
		if fonts then notes:AddDropdown({ Label = "Font", Options = fonts, Config = { "Notifications", "Font" } }) end
	end

	-- Kicia's toasts wear the menu's colours
	local function paintToasts()
		if not store then return end
		local colors = {
			Accent = C.accent, Background = C.window, ElementBackground = C.card, Outline = C.border,
			TextColor = C.text, Unselected = C.sub, TabButtonSelected = C.chip,
		}
		for key, color in pairs(colors) do
			if store:Get({ "Theme", key }) ~= color then store:Set({ "Theme", key }, color) end
		end
	end

	-- the end of the build: the last config, then the window (unless silent)
	function Menu:SetVisible(visible)
		if not K.booted then
			pruneDividers()
			local repaint = K.repaintOverlay
			K.repaintOverlay = function()
				if repaint then repaint() end
				paintToasts()
			end
			local load = K.extraLoad
			K.extraLoad = function(json)
				load(json)
				paintToasts()
			end
			paintToasts()
			K.booted = true
			K.silentBoot = visible == false
			K.boot()
			return
		end
		setOpen(visible ~= false)
	end

	return {
		Menu = function(modules)
			kicia = modules
			return Menu
		end,
	}
end)()

