-- Signal and Trove
local Signal = {}
Signal.__index = Signal
function Signal.new()
	return setmetatable({ _handlers = {} }, Signal)
end
function Signal:Connect(fn)
	local h = { fn = fn, connected = true }
	table.insert(self._handlers, h)
	local sig = self
	return {
		Connected = true,
		Disconnect = function(c)
			if not h.connected then
				return
			end
			h.connected = false
			c.Connected = false
			local i = table.find(sig._handlers, h)
			if i then
				table.remove(sig._handlers, i)
			end
		end,
	}
end
function Signal:Once(fn)
	local c
	c = self:Connect(function(...)
		c:Disconnect()
		fn(...)
	end)
	return c
end
function Signal:Fire(...)
	local list = table.clone(self._handlers)
	for _, h in ipairs(list) do
		if h.connected then
			task.spawn(h.fn, ...)
		end
	end
end
function Signal:FireSync(...)
	for _, h in ipairs(table.clone(self._handlers)) do
		if h.connected then
			h.fn(...)
		end
	end
end
function Signal:Destroy()
	table.clear(self._handlers)
end
K.Signal = Signal

local Trove = {}
Trove.__index = Trove
function Trove.new(name)
	return setmetatable({ _name = name, _items = {} }, Trove)
end
local function cleanItem(o)
	local t = typeof(o)
	if t == "RBXScriptConnection" then
		o:Disconnect()
	elseif t == "Instance" then
		pcall(function()
			o:Destroy()
		end)
	elseif t == "thread" then
		pcall(task.cancel, o)
	elseif type(o) == "function" then
		pcall(o)
	elseif type(o) == "table" then
		-- some objects (Kicia's signal connections) error on unknown fields
		local function member(k)
			local ok, v = pcall(function()
				return o[k]
			end)
			return ok and type(v) == "function" and v or nil
		end
		local cancel, getStatus = member("cancel"), member("getStatus")
		if cancel and getStatus then
			pcall(cancel, o)
			return
		end
		local destroy = member("Destroy")
		if destroy then
			pcall(destroy, o)
			return
		end
		local disconnect = member("Disconnect")
		if disconnect then
			pcall(disconnect, o)
		end
	end
end
function Trove:Add(o)
	table.insert(self._items, o)
	return o
end
function Trove:Connect(sig, fn)
	return self:Add(sig:Connect(fn))
end
function Trove:Extend()
	return self:Add(Trove.new(self._name))
end
function Trove:Remove(o, keep)
	local i = table.find(self._items, o)
	if i then
		table.remove(self._items, i)
		if not keep then
			cleanItem(o)
		end
	end
end
-- Promise held until it settles; cancelled if the trove is cleaned first.
function Trove:AddPromise(promise)
	if tostring(promise:getStatus()) == "Started" then
		self:Add(promise)
		promise:finally(function()
			if not self._cleaning then
				self:Remove(promise, true)
			end
		end)
	end
	return promise
end
-- Sub-trove that cleans itself up when `instance` is destroyed.
function Trove:AttachExtend(instance)
	local sub = self:Extend()
	sub:Connect(instance.Destroying, function()
		self:Remove(sub)
	end)
	return sub
end
function Trove:Clean()
	local items = self._items
	self._items = {}
	self._cleaning = true
	for i = #items, 1, -1 do
		cleanItem(items[i])
	end
	self._cleaning = false
end
Trove.Destroy = Trove.Clean
K.Trove = Trove

