				Config = Q("Tracer", "OutlineColor"),
				Transparency = Q("Tracer", "OutlineTransparency"),
			})
			tr:AddSlider({ Label = "Outline Thickness", Min = 1, Max = 6, Config = Q("Tracer", "OutlineThickness") })
		end
		side("Enemies", "Enemy", "left")
		side("Teammates", "Team", "right")
	end
end

